//! Apple Metal kernels for MACE-Polar runtime slices.
//!
//! This starts with the shared block-linear forward primitive used throughout
//! the PolarMACE local backbone. Later slices can keep the same gate and backend
//! while moving prepared graph buffers and fused heads onto GPU-resident storage.
#![allow(unsafe_code)]

use std::collections::HashMap;
use std::ffi::c_void;
use std::sync::{Arc, Mutex, OnceLock};
use std::time::Instant;

use metal::{
    Buffer, CommandQueue, CompileOptions, ComputePipelineState, Device, MTLResourceOptions, MTLSize,
};

use super::{
    invalid, mace_polar_trace_stage, mace_polar_trace_timings_enabled,
    MacePolarBlockLinearInstruction, MacePolarBlockLinearSpec, MacePolarConvWeightMlpInputRows,
    MacePolarDensityFnMlpInputRows, MacePolarError, MacePolarFlatRows, MacePolarFlatRowsF32,
    MacePolarParsedGatePlan, MacePolarProductSymmetricU1Entry, MacePolarProductSymmetricU2Entry,
    MacePolarProductSymmetricU3Entry, MacePolarProductSymmetricWeightedFeaturePlan, MacePolarRows,
};

#[derive(Clone)]
pub(super) struct MacePolarFlatRowsF32Metal {
    pub(super) row_count: usize,
    pub(super) width: usize,
    len: usize,
    buffer: Buffer,
}

impl std::fmt::Debug for MacePolarFlatRowsF32Metal {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("MacePolarFlatRowsF32Metal")
            .field("row_count", &self.row_count)
            .field("width", &self.width)
            .field("len", &self.len)
            .finish_non_exhaustive()
    }
}

#[derive(Clone, Copy)]
enum FlatF32CotangentSource<'a> {
    Cpu(&'a MacePolarFlatRowsF32),
    Metal(&'a MacePolarFlatRowsF32Metal),
}

#[derive(Clone, Copy)]
enum FlatF32RowsSource<'a> {
    Cpu(&'a MacePolarFlatRowsF32),
    Metal(&'a MacePolarFlatRowsF32Metal),
}

struct FusedCutoffNorm7VjpFlatF32Output {
    rows: Option<MacePolarFlatRowsF32>,
    rows_metal: Option<MacePolarFlatRowsF32Metal>,
    cutoff_cotangent: Vec<f64>,
}

type ConvTpVjpFlatF32Output = (
    Option<MacePolarRows>,
    Option<MacePolarFlatRows>,
    Option<MacePolarFlatRowsF32>,
    MacePolarFlatRowsF32Metal,
    MacePolarFlatRowsF32Metal,
    MacePolarFlatRowsF32Metal,
);

impl<'a> FlatF32CotangentSource<'a> {
    fn row_count(self) -> usize {
        match self {
            Self::Cpu(rows) => rows.row_count,
            Self::Metal(rows) => rows.row_count,
        }
    }

    fn width(self) -> usize {
        match self {
            Self::Cpu(rows) => rows.width,
            Self::Metal(rows) => rows.width,
        }
    }

    fn len(self) -> usize {
        match self {
            Self::Cpu(rows) => rows.values.len(),
            Self::Metal(rows) => rows.len,
        }
    }

    fn byte_len(self) -> usize {
        self.len().saturating_mul(std::mem::size_of::<f32>())
    }
}

impl<'a> FlatF32RowsSource<'a> {
    fn row_count(self) -> usize {
        match self {
            Self::Cpu(rows) => rows.row_count,
            Self::Metal(rows) => rows.row_count,
        }
    }

    fn width(self) -> usize {
        match self {
            Self::Cpu(rows) => rows.width,
            Self::Metal(rows) => rows.width,
        }
    }

    fn len(self) -> usize {
        match self {
            Self::Cpu(rows) => rows.values.len(),
            Self::Metal(rows) => rows.len,
        }
    }

    fn byte_len(self) -> usize {
        self.len().saturating_mul(std::mem::size_of::<f32>())
    }
}

