#[derive(Clone)]
pub(super) struct SparseUvuStaticTable {
    left_width: usize,
    right_width: usize,
    output_width: usize,
    hidden_dim: usize,
    weight_f32: Vec<f32>,
    output_mask_f32: Vec<f32>,
    metal_buffers: Arc<OnceLock<Result<SparseUvuStaticBuffers, String>>>,
}

impl SparseUvuStaticTable {
    pub(super) fn left_width(&self) -> usize {
        self.left_width
    }

    pub(super) fn right_width(&self) -> usize {
        self.right_width
    }

    pub(super) fn output_width(&self) -> usize {
        self.output_width
    }

    pub(super) fn from_slices(
        weight: &[f64],
        output_mask: &[f64],
        left_width: usize,
        right_width: usize,
        output_width: usize,
        hidden_dim: usize,
        name: &str,
    ) -> Result<Self, String> {
        if hidden_dim == 0 {
            return Err(format!("{name} hidden dim must be positive"));
        }
        if right_width != hidden_dim {
            return Err(format!(
                "{name} sparse UVU right width mismatch: expected hidden dim {hidden_dim}, got {right_width}"
            ));
        }
        if output_width != left_width {
            return Err(format!(
                "{name} sparse UVU output width mismatch: expected left width {left_width}, got {output_width}"
            ));
        }
        if output_mask.len() != output_width {
            return Err(format!(
                "{name} output mask length mismatch: expected {output_width}, got {}",
                output_mask.len()
            ));
        }
        let irrep_dims = sparse_uvu_product_irrep_dims(left_width, hidden_dim, name)?;
        let expected_weight = irrep_dims
            .len()
            .checked_mul(hidden_dim)
            .and_then(|value| value.checked_mul(hidden_dim))
            .ok_or_else(|| format!("{name} sparse UVU weight length overflows usize"))?;
        if weight.len() != expected_weight {
            return Err(format!(
                "{name} sparse UVU weight length mismatch: expected {expected_weight}, got {}",
                weight.len()
            ));
        }
        Ok(Self {
            left_width,
            right_width,
            output_width,
            hidden_dim,
            weight_f32: weight.iter().map(|value| *value as f32).collect(),
            output_mask_f32: output_mask.iter().map(|value| *value as f32).collect(),
            metal_buffers: Arc::new(OnceLock::new()),
        })
    }

    pub(super) fn from_product_dot_slices(
        weight: &[f64],
        output_mask: &[f64],
        product_width: usize,
        hidden_dim: usize,
        name: &str,
    ) -> Result<Self, String> {
        if hidden_dim == 0 {
            return Err(format!("{name} hidden dim must be positive"));
        }
        if output_mask.len() != hidden_dim {
            return Err(format!(
                "{name} output mask length mismatch: expected {hidden_dim}, got {}",
                output_mask.len()
            ));
        }
        let irrep_dims = sparse_uvu_product_irrep_dims(product_width, hidden_dim, name)?;
        let expected_weight = irrep_dims
            .len()
            .checked_mul(hidden_dim)
            .and_then(|value| value.checked_mul(hidden_dim))
            .ok_or_else(|| format!("{name} sparse UVU weight length overflows usize"))?;
        if weight.len() != expected_weight {
            return Err(format!(
                "{name} sparse UVU product-dot weight length mismatch: expected {expected_weight}, got {}",
                weight.len()
            ));
        }
        Ok(Self {
            left_width: product_width,
            right_width: product_width,
            output_width: hidden_dim,
            hidden_dim,
            weight_f32: weight.iter().map(|value| *value as f32).collect(),
            output_mask_f32: output_mask.iter().map(|value| *value as f32).collect(),
            metal_buffers: Arc::new(OnceLock::new()),
        })
    }

    pub(super) fn is_product_dot(&self) -> bool {
        self.output_width == self.hidden_dim
            && self.left_width == self.right_width
            && self.left_width != self.hidden_dim
    }

    fn metal_buffers(&self, device: &Device) -> Result<&SparseUvuStaticBuffers, String> {
        self.metal_buffers
            .get_or_init(|| SparseUvuStaticBuffers::new(device, self))
            .as_ref()
            .map_err(Clone::clone)
    }

    #[cfg(test)]
    fn has_metal_buffers(&self) -> bool {
        self.metal_buffers.get().is_some()
    }
}

impl std::fmt::Debug for SparseUvuStaticTable {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("SparseUvuStaticTable")
            .field("left_width", &self.left_width)
            .field("right_width", &self.right_width)
            .field("output_width", &self.output_width)
            .field("hidden_dim", &self.hidden_dim)
            .field("weight_len", &self.weight_f32.len())
            .field("output_mask_len", &self.output_mask_f32.len())
            .finish_non_exhaustive()
    }
}

struct SparseUvuStaticBuffers {
    weight_buffer: Buffer,
    output_mask_buffer: Buffer,
}

impl SparseUvuStaticBuffers {
    fn new(device: &Device, table: &SparseUvuStaticTable) -> Result<Self, String> {
        let options = MTLResourceOptions::StorageModeShared;
        Ok(Self {
            weight_buffer: buffer_with_slice_on_device(device, &table.weight_f32, options),
            output_mask_buffer: buffer_with_slice_on_device(
                device,
                &table.output_mask_f32,
                options,
            ),
        })
    }
}

fn sparse_uvu_product_irrep_dims(
    product_width: usize,
    hidden_dim: usize,
    name: &str,
) -> Result<Vec<usize>, String> {
    match product_width / hidden_dim {
        1 if product_width == hidden_dim => Ok(vec![1]),
        4 if product_width == hidden_dim * 4 => Ok(vec![1, 3]),
        9 if product_width == hidden_dim * 9 => Ok(vec![1, 3, 5]),
        _ => Err(format!(
            "{name} unsupported product feature width {product_width}"
        )),
    }
}

fn sparse_uvu_path_weight(table: &SparseUvuStaticTable, name: &str) -> Result<f32, String> {
    if table.is_product_dot() {
        let block_count =
            sparse_uvu_product_irrep_dims(table.left_width, table.hidden_dim, name)?.len();
        Ok(1.0_f32 / ((table.hidden_dim * block_count) as f32).sqrt())
    } else {
        Ok(1.0_f32 / (table.hidden_dim as f32).sqrt())
    }
}

#[derive(Clone)]
pub(super) struct NodeEmbeddingStaticTable {
    type_count: usize,
    hidden_dim: usize,
    embeddings_f32: Vec<f32>,
    metal_buffers: Arc<OnceLock<Result<NodeEmbeddingStaticBuffers, String>>>,
}

impl NodeEmbeddingStaticTable {
    pub(super) fn from_slices(
        weight: &[f64],
        bias: &[f64],
        output_mask: &[f64],
        type_count: usize,
        hidden_dim: usize,
        name: &str,
    ) -> Result<Self, String> {
        let expected_weight = type_count
            .checked_mul(hidden_dim)
            .ok_or_else(|| format!("{name} node embedding weight length overflows usize"))?;
        if weight.len() != expected_weight {
            return Err(format!(
                "{name} node embedding weight length mismatch: expected {expected_weight}, got {}",
                weight.len()
            ));
        }
        if !bias.is_empty() && bias.len() != hidden_dim {
            return Err(format!(
                "{name} node embedding bias length mismatch: expected 0 or {hidden_dim}, got {}",
                bias.len()
            ));
        }
        if output_mask.len() != hidden_dim {
            return Err(format!(
                "{name} node embedding output mask length mismatch: expected {hidden_dim}, got {}",
                output_mask.len()
            ));
        }
        let path_weight = 1.0 / (type_count as f64).sqrt();
        let mut embeddings_f32 = Vec::with_capacity(expected_weight);
        for type_id in 0..type_count {
            let weight_base = type_id * hidden_dim;
            for feature in 0..hidden_dim {
                let bias_value = bias.get(feature).copied().unwrap_or(0.0);
                let value = (path_weight * weight[weight_base + feature] + bias_value)
                    * output_mask[feature];
                embeddings_f32.push(value as f32);
            }
        }
        Ok(Self {
            type_count,
            hidden_dim,
            embeddings_f32,
            metal_buffers: Arc::new(OnceLock::new()),
        })
    }

    fn metal_buffers(&self, device: &Device) -> Result<&NodeEmbeddingStaticBuffers, String> {
        self.metal_buffers
            .get_or_init(|| NodeEmbeddingStaticBuffers::new(device, self))
            .as_ref()
            .map_err(Clone::clone)
    }

    #[cfg(test)]
    fn has_metal_buffers(&self) -> bool {
        self.metal_buffers.get().is_some()
    }
}

impl std::fmt::Debug for NodeEmbeddingStaticTable {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("NodeEmbeddingStaticTable")
            .field("type_count", &self.type_count)
            .field("hidden_dim", &self.hidden_dim)
            .field("embedding_len", &self.embeddings_f32.len())
            .finish_non_exhaustive()
    }
}

