pub(super) struct ConvTpStaticTable {
    input1_dim: usize,
    input2_dim: usize,
    weight_dim: usize,
    output_dim: usize,
    output_mask_all_one: bool,
    output_mask_f32: Vec<f32>,
    instructions: Vec<PolarConvTpInstructionMetal>,
    cgs: Vec<PolarConvTpCgMetal>,
    lane_offsets: Vec<u32>,
    lane_entries: Vec<PolarConvTpLaneEntryMetal>,
    vjp_input1_lane_offsets: Vec<u32>,
    vjp_input1_lane_entries: Vec<PolarConvTpVjpInput1LaneEntryMetal>,
    vjp_input2_lane_offsets: Vec<u32>,
    vjp_input2_lane_entries: Vec<PolarConvTpVjpInput2LaneEntryMetal>,
    vjp_weight_lane_offsets: Vec<u32>,
    vjp_weight_lane_entries: Vec<PolarConvTpVjpWeightLaneEntryMetal>,
    metal_buffers: Arc<OnceLock<Result<ConvTpStaticBuffers, String>>>,
}

impl ConvTpStaticTable {
    pub(super) fn from_plan(
        plan: &e3nn_core::TensorProductPlan,
        output_mask: &[f64],
        name: &str,
    ) -> Result<Self, String> {
        let output_dim = plan.output_dim();
        if output_mask.len() != output_dim {
            return Err(format!(
                "{name} output mask length mismatch: expected {output_dim}, got {}",
                output_mask.len()
            ));
        }
        let (instructions, cgs) = pack_conv_tp_static_table(plan, name)?;
        let (lane_offsets, lane_entries) = pack_conv_tp_lane_static_table(plan, name)?;
        let (
            vjp_input1_lane_offsets,
            vjp_input1_lane_entries,
            vjp_input2_lane_offsets,
            vjp_input2_lane_entries,
            vjp_weight_lane_offsets,
            vjp_weight_lane_entries,
        ) = pack_conv_tp_vjp_lane_static_table(plan, name)?;
        Ok(Self {
            input1_dim: plan.input1_dim(),
            input2_dim: plan.input2_dim(),
            weight_dim: plan.weight_numel,
            output_dim,
            output_mask_all_one: output_mask.iter().all(|value| *value == 1.0),
            output_mask_f32: output_mask.iter().map(|value| *value as f32).collect(),
            instructions,
            cgs,
            lane_offsets,
            lane_entries,
            vjp_input1_lane_offsets,
            vjp_input1_lane_entries,
            vjp_input2_lane_offsets,
            vjp_input2_lane_entries,
            vjp_weight_lane_offsets,
            vjp_weight_lane_entries,
            metal_buffers: Arc::new(OnceLock::new()),
        })
    }

    fn params(
        &self,
        node_count: usize,
        edge_count: usize,
    ) -> Result<PolarConvTpParamsMetal, String> {
        Ok(PolarConvTpParamsMetal {
            node_count: u32::try_from(node_count)
                .map_err(|_| "node count exceeds Metal u32 range".to_owned())?,
            edge_count: u32::try_from(edge_count)
                .map_err(|_| "edge count exceeds Metal u32 range".to_owned())?,
            input1_dim: u32::try_from(self.input1_dim)
                .map_err(|_| "conv-TP input1 dimension exceeds Metal u32 range".to_owned())?,
            input2_dim: u32::try_from(self.input2_dim)
                .map_err(|_| "conv-TP input2 dimension exceeds Metal u32 range".to_owned())?,
            weight_dim: u32::try_from(self.weight_dim)
                .map_err(|_| "conv-TP weight dimension exceeds Metal u32 range".to_owned())?,
            output_dim: u32::try_from(self.output_dim)
                .map_err(|_| "conv-TP output dimension exceeds Metal u32 range".to_owned())?,
            instruction_count: u32::try_from(self.instructions.len())
                .map_err(|_| "conv-TP instruction count exceeds Metal u32 range".to_owned())?,
        })
    }

    fn metal_buffers(&self, device: &Device) -> Result<&ConvTpStaticBuffers, String> {
        self.metal_buffers
            .get_or_init(|| ConvTpStaticBuffers::new(device, self))
            .as_ref()
            .map_err(Clone::clone)
    }

    #[cfg(test)]
    fn has_metal_buffers(&self) -> bool {
        self.metal_buffers.get().is_some()
    }
}

