    #[allow(clippy::too_many_arguments)]
    fn torch_linear_f32_cotangent_vjp_cutoff_retained_then_layer_norm_silu_vjp_flat_f32_with_static_tables_impl(
        &self,
        output_cotangent_source: FlatF32CotangentSource<'_>,
        retained_cutoff_output_rows: &[Vec<f64>],
        retained_cutoff_output_f32: Option<FlatF32RowsSource<'_>>,
        cutoffs: &[f64],
        linear_table: &DenseLinearStaticTable,
        layer_norm_input_rows: &[Vec<f64>],
        layer_norm_table: &LayerNormStaticTable,
        name: &str,
        read_output_cpu: bool,
        retain_output_metal: bool,
    ) -> Result<FusedCutoffNorm7VjpFlatF32Output, String> {
        let row_count = output_cotangent_source.row_count();
        if output_cotangent_source.width() != linear_table.output_dim {
            return Err(format!(
                "{name}.width mismatch: expected {}, got {}",
                linear_table.output_dim,
                output_cotangent_source.width()
            ));
        }
        let expected_len = row_count
            .checked_mul(output_cotangent_source.width())
            .ok_or_else(|| {
                "torch-linear retained-cutoff fused VJP output cotangent length overflows usize"
                    .to_owned()
            })?;
        if output_cotangent_source.len() != expected_len {
            return Err(format!(
                "{name}.values length mismatch: expected {expected_len}, got {}",
                output_cotangent_source.len()
            ));
        }
        if linear_table.input_dim != layer_norm_table.width {
            return Err(format!(
                "{name}.linear_norm width mismatch: linear input={} norm width={}",
                linear_table.input_dim, layer_norm_table.width
            ));
        }
        if row_count == 0 {
            let rows = read_output_cpu.then(|| MacePolarFlatRowsF32 {
                values: Vec::new(),
                row_count: 0,
                width: layer_norm_table.width,
            });
            let rows_metal = retain_output_metal.then(|| MacePolarFlatRowsF32Metal {
                row_count: 0,
                width: layer_norm_table.width,
                len: 0,
                buffer: self
                    .device
                    .new_buffer(1, MTLResourceOptions::StorageModeShared),
            });
            return Ok(FusedCutoffNorm7VjpFlatF32Output {
                rows,
                rows_metal,
                cutoff_cotangent: Vec::new(),
            });
        }
        if retained_cutoff_output_rows.len() != row_count {
            return Err(format!(
                "{name}.retained_cutoff_output row count mismatch: expected {row_count}, got {}",
                retained_cutoff_output_rows.len()
            ));
        }
        if cutoffs.len() != row_count {
            return Err(format!(
                "{name}.cutoffs length mismatch: expected {row_count}, got {}",
                cutoffs.len()
            ));
        }
        if layer_norm_input_rows.len() != row_count {
            return Err(format!(
                "{name}.layer_norm_input row count mismatch: expected {row_count}, got {}",
                layer_norm_input_rows.len()
            ));
        }

        let hidden_len = row_count
            .checked_mul(linear_table.input_dim)
            .ok_or_else(|| {
                "torch-linear retained-cutoff fused VJP hidden length overflows usize".to_owned()
            })?;
        let output_len = row_count
            .checked_mul(linear_table.output_dim)
            .ok_or_else(|| {
                "torch-linear retained-cutoff fused VJP output length overflows usize".to_owned()
            })?;
        if hidden_len == 0 {
            let rows = read_output_cpu.then(|| MacePolarFlatRowsF32 {
                values: Vec::new(),
                row_count,
                width: layer_norm_table.width,
            });
            let rows_metal = retain_output_metal.then(|| MacePolarFlatRowsF32Metal {
                row_count,
                width: layer_norm_table.width,
                len: 0,
                buffer: self
                    .device
                    .new_buffer(1, MTLResourceOptions::StorageModeShared),
            });
            return Ok(FusedCutoffNorm7VjpFlatF32Output {
                rows,
                rows_metal,
                cutoff_cotangent: vec![0.0; row_count],
            });
        }

        let linear_params = PolarTorchLinearParamsMetal {
            row_count: u32::try_from(row_count)
                .map_err(|_| "row count exceeds Metal u32 range".to_owned())?,
            input_dim: u32::try_from(linear_table.input_dim)
                .map_err(|_| "linear input dim exceeds Metal u32 range".to_owned())?,
            output_dim: u32::try_from(linear_table.output_dim)
                .map_err(|_| "linear output dim exceeds Metal u32 range".to_owned())?,
        };
        let layer_norm_params = PolarLayerNormSiluParamsMetal {
            row_count: linear_params.row_count,
            width: linear_params.input_dim,
            eps: layer_norm_table.eps_f32,
        };
        let dispatch_len = hidden_len.checked_add(row_count).ok_or_else(|| {
            "torch-linear retained-cutoff fused VJP dispatch length overflows usize".to_owned()
        })?;

        let options = MTLResourceOptions::StorageModeShared;
        let linear_buffers = linear_table.metal_buffers(&self.device)?;
        let layer_norm_buffers = layer_norm_table.metal_buffers(&self.device)?;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;

        let retained_output_f32_source = if let Some(rows_f32) = retained_cutoff_output_f32 {
            validate_flat_rows_f32_source(rows_f32, row_count, linear_table.output_dim, name)?;
            Some(rows_f32)
        } else {
            flatten_rows_f32_into(
                retained_cutoff_output_rows,
                linear_table.output_dim,
                &format!("{name}.retained_cutoff_output"),
                &mut scratch.weight_f32,
            )?;
            None
        };
        f64_to_f32_vec_into(cutoffs, &mut scratch.cutoff_f32);
        flatten_rows_f32_into(
            layer_norm_input_rows,
            layer_norm_table.width,
            &format!("{name}.layer_norm_input"),
            &mut scratch.input_f32,
        )?;
        scratch.output_f32.clear();
        scratch.output_f32.resize(hidden_len, 0.0);
        scratch.gate_f32.clear();
        scratch.gate_f32.resize(row_count, 0.0);

        debug_assert_eq!(output_cotangent_source.len(), output_len);
        if retained_output_f32_source.is_none() {
            debug_assert_eq!(scratch.weight_f32.len(), output_len);
        }
        debug_assert_eq!(scratch.input_f32.len(), hidden_len);

        let output_cotangent_bytes = output_cotangent_source.byte_len();
        let retained_output_bytes = retained_output_f32_source.map_or_else(
            || std::mem::size_of_val(scratch.weight_f32.as_slice()),
            FlatF32RowsSource::byte_len,
        );
        let cutoff_bytes = std::mem::size_of_val(scratch.cutoff_f32.as_slice());
        let hidden_bytes = hidden_len
            .checked_mul(std::mem::size_of::<f32>())
            .ok_or_else(|| {
                "torch-linear retained-cutoff fused VJP hidden byte length overflows usize"
                    .to_owned()
            })?;
        let cutoff_cotangent_bytes = std::mem::size_of_val(scratch.gate_f32.as_slice());
        let linear_params_bytes = std::mem::size_of_val(std::slice::from_ref(&linear_params));
        let layer_norm_params_bytes =
            std::mem::size_of_val(std::slice::from_ref(&layer_norm_params));

        if matches!(output_cotangent_source, FlatF32CotangentSource::Cpu(_)) {
            scratch
                .input_buffer
                .ensure_capacity(&self.device, output_cotangent_bytes, options)?;
        }
        if !matches!(
            retained_output_f32_source,
            Some(FlatF32RowsSource::Metal(_))
        ) {
            scratch
                .weight_buffer
                .ensure_capacity(&self.device, retained_output_bytes, options)?;
        }
        scratch
            .cutoff_buffer
            .ensure_capacity(&self.device, cutoff_bytes, options)?;
        scratch
            .hidden_a_buffer
            .ensure_capacity(&self.device, hidden_bytes, options)?;
        scratch
            .hidden_b_buffer
            .ensure_capacity(&self.device, hidden_bytes, options)?;
        scratch
            .output_buffer
            .ensure_capacity(&self.device, hidden_bytes, options)?;
        scratch
            .gate_mask_buffer
            .ensure_capacity(&self.device, cutoff_cotangent_bytes, options)?;
        scratch.dense_output_params_buffer.ensure_capacity(
            &self.device,
            linear_params_bytes,
            options,
        )?;
        scratch.layer_norm_params_buffer.ensure_capacity(
            &self.device,
            layer_norm_params_bytes,
            options,
        )?;

        if let FlatF32CotangentSource::Cpu(rows) = output_cotangent_source {
            copy_slice_to_buffer(&rows.values, scratch.input_buffer.buffer()?);
        }
        match retained_output_f32_source {
            Some(FlatF32RowsSource::Cpu(rows_f32)) => {
                copy_slice_to_buffer(&rows_f32.values, scratch.weight_buffer.buffer()?);
            }
            Some(FlatF32RowsSource::Metal(_)) => {}
            None => {
                copy_slice_to_buffer(&scratch.weight_f32, scratch.weight_buffer.buffer()?);
            }
        }
        copy_slice_to_buffer(&scratch.cutoff_f32, scratch.cutoff_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.input_f32, scratch.hidden_b_buffer.buffer()?);
        copy_slice_to_buffer(
            std::slice::from_ref(&linear_params),
            scratch.dense_output_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&layer_norm_params),
            scratch.layer_norm_params_buffer.buffer()?,
        );

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();

        encoder.set_compute_pipeline_state(&self.torch_linear_vjp_cutoff_retained_pipeline);
        match output_cotangent_source {
            FlatF32CotangentSource::Cpu(_) => {
                encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
            }
            FlatF32CotangentSource::Metal(rows) => {
                encoder.set_buffer(0, Some(&rows.buffer), 0);
            }
        }
        match retained_output_f32_source {
            Some(FlatF32RowsSource::Metal(rows)) => {
                encoder.set_buffer(1, Some(&rows.buffer), 0);
            }
            Some(FlatF32RowsSource::Cpu(_)) | None => {
                encoder.set_buffer(1, Some(scratch.weight_buffer.buffer()?), 0);
            }
        }
        encoder.set_buffer(2, Some(scratch.cutoff_buffer.buffer()?), 0);
        encoder.set_buffer(3, Some(&linear_buffers.weight_buffer), 0);
        encoder.set_buffer(4, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(5, Some(scratch.gate_mask_buffer.buffer()?), 0);
        encoder.set_buffer(6, Some(scratch.dense_output_params_buffer.buffer()?), 0);
        self.dispatch_1d(
            &encoder,
            &self.torch_linear_vjp_cutoff_retained_pipeline,
            dispatch_len,
        )?;

        encoder.set_compute_pipeline_state(&self.layer_norm_silu_vjp_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(2, Some(&layer_norm_buffers.weight_buffer), 0);
        encoder.set_buffer(3, Some(&layer_norm_buffers.bias_buffer), 0);
        encoder.set_buffer(4, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(5, Some(scratch.layer_norm_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.layer_norm_silu_vjp_pipeline, row_count)?;

        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }

        let rows_metal = if retain_output_metal {
            Some(self.clone_flat_rows_f32_buffer(
                scratch.output_buffer.buffer()?,
                row_count,
                layer_norm_table.width,
                name,
            )?)
        } else {
            None
        };
        let rows = if read_output_cpu {
            let output_ptr = scratch.output_buffer.buffer()?.contents().cast::<f32>();
            copy_ptr_to_slice(output_ptr, &mut scratch.output_f32);
            Some(MacePolarFlatRowsF32 {
                values: scratch.output_f32.clone(),
                row_count,
                width: layer_norm_table.width,
            })
        } else {
            None
        };
        let cutoff_ptr = scratch.gate_mask_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(cutoff_ptr, &mut scratch.gate_f32);

        let cutoff_cotangent = scratch
            .gate_f32
            .iter()
            .map(|value| f64::from(*value))
            .collect();
        Ok(FusedCutoffNorm7VjpFlatF32Output {
            rows,
            rows_metal,
            cutoff_cotangent,
        })
    }

    fn layer_norm_silu_rows_f32_with_static_table(
        &self,
        input_rows: &[Vec<f64>],
        table: &LayerNormStaticTable,
        name: &str,
    ) -> Result<MacePolarRows, String> {
        let row_count = input_rows.len();
        if row_count == 0 {
            return Ok(Vec::new());
        }
        let output_len = row_count
            .checked_mul(table.width)
            .ok_or_else(|| "layer-norm SiLU output length overflows usize".to_owned())?;
        let params = PolarLayerNormSiluParamsMetal {
            row_count: u32::try_from(row_count)
                .map_err(|_| "row count exceeds Metal u32 range".to_owned())?,
            width: u32::try_from(table.width)
                .map_err(|_| "layer norm width exceeds Metal u32 range".to_owned())?,
            eps: table.eps_f32,
        };

        let options = MTLResourceOptions::StorageModeShared;
        let table_buffers = table.metal_buffers(&self.device)?;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;
        flatten_rows_f32_into(input_rows, table.width, name, &mut scratch.input_f32)?;
        scratch.output_f32.clear();
        scratch.output_f32.resize(output_len, 0.0);

        let input_bytes = std::mem::size_of_val(scratch.input_f32.as_slice());
        let output_bytes = std::mem::size_of_val(scratch.output_f32.as_slice());
        let params_bytes = std::mem::size_of_val(std::slice::from_ref(&params));

        scratch
            .input_buffer
            .ensure_capacity(&self.device, input_bytes, options)?;
        scratch
            .output_buffer
            .ensure_capacity(&self.device, output_bytes, options)?;
        scratch
            .params_buffer
            .ensure_capacity(&self.device, params_bytes, options)?;

        copy_slice_to_buffer(&scratch.input_f32, scratch.input_buffer.buffer()?);
        copy_slice_to_buffer(
            std::slice::from_ref(&params),
            scratch.params_buffer.buffer()?,
        );

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();
        encoder.set_compute_pipeline_state(&self.layer_norm_silu_pipeline);
        encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&table_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(&table_buffers.bias_buffer), 0);
        encoder.set_buffer(3, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(scratch.params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.layer_norm_silu_pipeline, row_count)?;
        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }

        let output_ptr = scratch.output_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(output_ptr, &mut scratch.output_f32);

        Ok(scratch
            .output_f32
            .chunks_exact(table.width)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect())
    }

