    fn layer_norm_silu_flat_f32_rows_vjp_f32_with_static_table(
        &self,
        output_cotangent_rows: &MacePolarFlatRowsF32,
        input_rows: &[Vec<f64>],
        table: &LayerNormStaticTable,
        name: &str,
    ) -> Result<MacePolarRows, String> {
        output_cotangent_rows
            .validate(name)
            .map_err(|err| err.to_string())?;
        let row_count = output_cotangent_rows.row_count;
        if row_count == 0 {
            return Ok(Vec::new());
        }
        if output_cotangent_rows.width != table.width {
            return Err(format!(
                "{name}.width mismatch: expected {}, got {}",
                table.width, output_cotangent_rows.width
            ));
        }
        if input_rows.len() != row_count {
            return Err(format!(
                "{name}.input row count mismatch: expected {row_count}, got {}",
                input_rows.len()
            ));
        }
        let output_len = row_count
            .checked_mul(table.width)
            .ok_or_else(|| "layer-norm SiLU VJP output length overflows usize".to_owned())?;
        let params = PolarLayerNormSiluParamsMetal {
            row_count: u32::try_from(row_count)
                .map_err(|_| "row count exceeds Metal u32 range".to_owned())?,
            width: u32::try_from(table.width)
                .map_err(|_| "layer norm width exceeds Metal u32 range".to_owned())?,
            eps: table.eps_f32,
        };

        let options = MTLResourceOptions::StorageModeShared;
        let table_buffers = table.metal_buffers(&self.device)?;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;
        scratch.input_f32.clear();
        scratch
            .input_f32
            .reserve(output_cotangent_rows.values.len());
        scratch
            .input_f32
            .extend_from_slice(&output_cotangent_rows.values);
        flatten_rows_f32_into(
            input_rows,
            table.width,
            &format!("{name}.input"),
            &mut scratch.weight_f32,
        )?;
        scratch.output_f32.clear();
        scratch.output_f32.resize(output_len, 0.0);

        let output_cotangent_bytes = std::mem::size_of_val(scratch.input_f32.as_slice());
        let input_bytes = std::mem::size_of_val(scratch.weight_f32.as_slice());
        let output_bytes = std::mem::size_of_val(scratch.output_f32.as_slice());
        let params_bytes = std::mem::size_of_val(std::slice::from_ref(&params));

        scratch
            .input_buffer
            .ensure_capacity(&self.device, output_cotangent_bytes, options)?;
        scratch
            .weight_buffer
            .ensure_capacity(&self.device, input_bytes, options)?;
        scratch
            .output_buffer
            .ensure_capacity(&self.device, output_bytes, options)?;
        scratch
            .params_buffer
            .ensure_capacity(&self.device, params_bytes, options)?;

        copy_slice_to_buffer(&scratch.input_f32, scratch.input_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.weight_f32, scratch.weight_buffer.buffer()?);
        copy_slice_to_buffer(
            std::slice::from_ref(&params),
            scratch.params_buffer.buffer()?,
        );

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();
        encoder.set_compute_pipeline_state(&self.layer_norm_silu_vjp_pipeline);
        encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(scratch.weight_buffer.buffer()?), 0);
        encoder.set_buffer(2, Some(&table_buffers.weight_buffer), 0);
        encoder.set_buffer(3, Some(&table_buffers.bias_buffer), 0);
        encoder.set_buffer(4, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(5, Some(scratch.params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.layer_norm_silu_vjp_pipeline, row_count)?;
        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }

        let output_ptr = scratch.output_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(output_ptr, &mut scratch.output_f32);

        Ok(scratch
            .output_f32
            .chunks_exact(table.width)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect())
    }

    fn layer_norm_silu_flat_f32_rows_vjp_flat_f32_with_static_table(
        &self,
        output_cotangent_rows: &MacePolarFlatRowsF32,
        input_rows: &[Vec<f64>],
        table: &LayerNormStaticTable,
        name: &str,
    ) -> Result<MacePolarFlatRowsF32, String> {
        output_cotangent_rows
            .validate(name)
            .map_err(|err| err.to_string())?;
        let row_count = output_cotangent_rows.row_count;
        if row_count == 0 {
            return Ok(MacePolarFlatRowsF32 {
                values: Vec::new(),
                row_count: 0,
                width: table.width,
            });
        }
        if output_cotangent_rows.width != table.width {
            return Err(format!(
                "{name}.width mismatch: expected {}, got {}",
                table.width, output_cotangent_rows.width
            ));
        }
        if input_rows.len() != row_count {
            return Err(format!(
                "{name}.input row count mismatch: expected {row_count}, got {}",
                input_rows.len()
            ));
        }
        let output_len = row_count
            .checked_mul(table.width)
            .ok_or_else(|| "layer-norm SiLU VJP output length overflows usize".to_owned())?;
        let params = PolarLayerNormSiluParamsMetal {
            row_count: u32::try_from(row_count)
                .map_err(|_| "row count exceeds Metal u32 range".to_owned())?,
            width: u32::try_from(table.width)
                .map_err(|_| "layer norm width exceeds Metal u32 range".to_owned())?,
            eps: table.eps_f32,
        };

        let options = MTLResourceOptions::StorageModeShared;
        let table_buffers = table.metal_buffers(&self.device)?;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;
        scratch.input_f32.clear();
        scratch
            .input_f32
            .reserve(output_cotangent_rows.values.len());
        scratch
            .input_f32
            .extend_from_slice(&output_cotangent_rows.values);
        flatten_rows_f32_into(
            input_rows,
            table.width,
            &format!("{name}.input"),
            &mut scratch.weight_f32,
        )?;
        scratch.output_f32.clear();
        scratch.output_f32.resize(output_len, 0.0);

        let output_cotangent_bytes = std::mem::size_of_val(scratch.input_f32.as_slice());
        let input_bytes = std::mem::size_of_val(scratch.weight_f32.as_slice());
        let output_bytes = std::mem::size_of_val(scratch.output_f32.as_slice());
        let params_bytes = std::mem::size_of_val(std::slice::from_ref(&params));

        scratch
            .input_buffer
            .ensure_capacity(&self.device, output_cotangent_bytes, options)?;
        scratch
            .weight_buffer
            .ensure_capacity(&self.device, input_bytes, options)?;
        scratch
            .output_buffer
            .ensure_capacity(&self.device, output_bytes, options)?;
        scratch
            .params_buffer
            .ensure_capacity(&self.device, params_bytes, options)?;

        copy_slice_to_buffer(&scratch.input_f32, scratch.input_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.weight_f32, scratch.weight_buffer.buffer()?);
        copy_slice_to_buffer(
            std::slice::from_ref(&params),
            scratch.params_buffer.buffer()?,
        );

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();
        encoder.set_compute_pipeline_state(&self.layer_norm_silu_vjp_pipeline);
        encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(scratch.weight_buffer.buffer()?), 0);
        encoder.set_buffer(2, Some(&table_buffers.weight_buffer), 0);
        encoder.set_buffer(3, Some(&table_buffers.bias_buffer), 0);
        encoder.set_buffer(4, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(5, Some(scratch.params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.layer_norm_silu_vjp_pipeline, row_count)?;
        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }

        let output_ptr = scratch.output_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(output_ptr, &mut scratch.output_f32);

        Ok(MacePolarFlatRowsF32 {
            values: scratch.output_f32.clone(),
            row_count,
            width: table.width,
        })
    }

    #[allow(clippy::too_many_arguments)]
    fn conv_weight_mlp_tail_flat_f32_vjp_f32_with_static_tables(
        &self,
        linear_6_cotangent_rows: FlatF32RowsSource<'_>,
        linear_3_input_rows: &[Vec<f64>],
        linear_0_input_rows: &[Vec<f64>],
        net6_table: &DenseLinearStaticTable,
        norm4_table: &LayerNormStaticTable,
        net3_table: &DenseLinearStaticTable,
        norm1_table: &LayerNormStaticTable,
        net0_table: &DenseLinearStaticTable,
        prefix_input_dim: usize,
        name: &str,
    ) -> Result<MacePolarRows, String> {
        let row_count = linear_6_cotangent_rows.row_count();
        validate_flat_rows_f32_source(
            linear_6_cotangent_rows,
            row_count,
            net6_table.output_dim,
            name,
        )?;
        if row_count == 0 {
            return Ok(Vec::new());
        }
        if net6_table.input_dim != norm4_table.width
            || norm4_table.width != net3_table.output_dim
            || net3_table.input_dim != norm1_table.width
            || norm1_table.width != net0_table.output_dim
        {
            return Err(format!(
                "{name}.table width mismatch: net6_in={} norm4={} net3_out={} net3_in={} norm1={} net0_out={}",
                net6_table.input_dim,
                norm4_table.width,
                net3_table.output_dim,
                net3_table.input_dim,
                norm1_table.width,
                net0_table.output_dim
            ));
        }
        if net6_table.input_dim != net6_table.output_dim
            || net3_table.input_dim != net3_table.output_dim
        {
            return Err(format!(
                "{name}.hidden width mismatch: net6 {}x{}, net3 {}x{}",
                net6_table.input_dim,
                net6_table.output_dim,
                net3_table.input_dim,
                net3_table.output_dim
            ));
        }
        if prefix_input_dim > net0_table.input_dim {
            return Err(format!(
                "{name}.prefix_input_dim mismatch: prefix {} exceeds input dim {}",
                prefix_input_dim, net0_table.input_dim
            ));
        }
        if linear_3_input_rows.len() != row_count {
            return Err(format!(
                "{name}.linear_3_input row count mismatch: expected {row_count}, got {}",
                linear_3_input_rows.len()
            ));
        }
        if linear_0_input_rows.len() != row_count {
            return Err(format!(
                "{name}.linear_0_input row count mismatch: expected {row_count}, got {}",
                linear_0_input_rows.len()
            ));
        }

        let hidden_len = row_count
            .checked_mul(net6_table.input_dim)
            .ok_or_else(|| format!("{name} hidden length overflows usize"))?;
        let prefix_len = row_count
            .checked_mul(prefix_input_dim)
            .ok_or_else(|| format!("{name} prefix output length overflows usize"))?;
        let net6_params = PolarTorchLinearParamsMetal {
            row_count: u32::try_from(row_count)
                .map_err(|_| format!("{name} row count exceeds Metal u32 range"))?,
            input_dim: u32::try_from(net6_table.input_dim)
                .map_err(|_| format!("{name} net6 input dim exceeds Metal u32 range"))?,
            output_dim: u32::try_from(net6_table.output_dim)
                .map_err(|_| format!("{name} net6 output dim exceeds Metal u32 range"))?,
        };
        let norm4_params = PolarLayerNormSiluParamsMetal {
            row_count: net6_params.row_count,
            width: u32::try_from(norm4_table.width)
                .map_err(|_| format!("{name} norm4 width exceeds Metal u32 range"))?,
            eps: norm4_table.eps_f32,
        };
        let net3_params = PolarTorchLinearParamsMetal {
            row_count: net6_params.row_count,
            input_dim: u32::try_from(net3_table.input_dim)
                .map_err(|_| format!("{name} net3 input dim exceeds Metal u32 range"))?,
            output_dim: u32::try_from(net3_table.output_dim)
                .map_err(|_| format!("{name} net3 output dim exceeds Metal u32 range"))?,
        };
        let norm1_params = PolarLayerNormSiluParamsMetal {
            row_count: net6_params.row_count,
            width: u32::try_from(norm1_table.width)
                .map_err(|_| format!("{name} norm1 width exceeds Metal u32 range"))?,
            eps: norm1_table.eps_f32,
        };
        let net0_params = PolarTorchLinearVjpPrefixParamsMetal {
            row_count: net6_params.row_count,
            prefix_input_dim: u32::try_from(prefix_input_dim)
                .map_err(|_| format!("{name} prefix input dim exceeds Metal u32 range"))?,
            output_dim: u32::try_from(net0_table.output_dim)
                .map_err(|_| format!("{name} net0 output dim exceeds Metal u32 range"))?,
            weight_input_dim: u32::try_from(net0_table.input_dim)
                .map_err(|_| format!("{name} net0 input dim exceeds Metal u32 range"))?,
        };

        let options = MTLResourceOptions::StorageModeShared;
        let net6_buffers = net6_table.metal_buffers(&self.device)?;
        let norm4_buffers = norm4_table.metal_buffers(&self.device)?;
        let net3_buffers = net3_table.metal_buffers(&self.device)?;
        let norm1_buffers = norm1_table.metal_buffers(&self.device)?;
        let net0_buffers = net0_table.metal_buffers(&self.device)?;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;
        if let FlatF32RowsSource::Cpu(rows) = linear_6_cotangent_rows {
            scratch.input_f32.clear();
            scratch.input_f32.extend_from_slice(&rows.values);
        }
        flatten_rows_f32_into(
            linear_3_input_rows,
            norm4_table.width,
            &format!("{name}.linear_3_input"),
            &mut scratch.weight_f32,
        )?;
        flatten_rows_f32_into(
            linear_0_input_rows,
            norm1_table.width,
            &format!("{name}.linear_0_input"),
            &mut scratch.bias_f32,
        )?;
        scratch.output_f32.clear();
        scratch.output_f32.resize(prefix_len, 0.0);

        let hidden_bytes = hidden_len
            .checked_mul(std::mem::size_of::<f32>())
            .ok_or_else(|| format!("{name} hidden byte length overflows usize"))?;
        let prefix_bytes = prefix_len
            .checked_mul(std::mem::size_of::<f32>())
            .ok_or_else(|| format!("{name} prefix byte length overflows usize"))?;
        let output_buffer_bytes = hidden_bytes.max(prefix_bytes);
        let input_bytes = linear_6_cotangent_rows.byte_len();
        let linear3_bytes = std::mem::size_of_val(scratch.weight_f32.as_slice());
        let linear0_bytes = std::mem::size_of_val(scratch.bias_f32.as_slice());
        let net6_params_bytes = std::mem::size_of_val(std::slice::from_ref(&net6_params));
        let norm4_params_bytes = std::mem::size_of_val(std::slice::from_ref(&norm4_params));
        let net3_params_bytes = std::mem::size_of_val(std::slice::from_ref(&net3_params));
        let norm1_params_bytes = std::mem::size_of_val(std::slice::from_ref(&norm1_params));
        let net0_params_bytes = std::mem::size_of_val(std::slice::from_ref(&net0_params));

        if matches!(linear_6_cotangent_rows, FlatF32RowsSource::Cpu(_)) {
            scratch
                .input_buffer
                .ensure_capacity(&self.device, input_bytes, options)?;
        }
        scratch
            .hidden_a_buffer
            .ensure_capacity(&self.device, hidden_bytes, options)?;
        scratch
            .hidden_b_buffer
            .ensure_capacity(&self.device, hidden_bytes, options)?;
        scratch
            .weight_buffer
            .ensure_capacity(&self.device, linear3_bytes, options)?;
        scratch
            .bias_buffer
            .ensure_capacity(&self.device, linear0_bytes, options)?;
        scratch
            .output_buffer
            .ensure_capacity(&self.device, output_buffer_bytes, options)?;
        scratch
            .params_buffer
            .ensure_capacity(&self.device, net6_params_bytes, options)?;
        scratch.layer_norm_params_buffer.ensure_capacity(
            &self.device,
            norm4_params_bytes,
            options,
        )?;
        scratch.dense_input_params_buffer.ensure_capacity(
            &self.device,
            net3_params_bytes,
            options,
        )?;
        scratch.dense_hidden_params_buffer.ensure_capacity(
            &self.device,
            norm1_params_bytes,
            options,
        )?;
        scratch.dense_output_params_buffer.ensure_capacity(
            &self.device,
            net0_params_bytes,
            options,
        )?;

        if matches!(linear_6_cotangent_rows, FlatF32RowsSource::Cpu(_)) {
            copy_slice_to_buffer(&scratch.input_f32, scratch.input_buffer.buffer()?);
        }
        copy_slice_to_buffer(&scratch.weight_f32, scratch.weight_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.bias_f32, scratch.bias_buffer.buffer()?);
        copy_slice_to_buffer(
            std::slice::from_ref(&net6_params),
            scratch.params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&norm4_params),
            scratch.layer_norm_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&net3_params),
            scratch.dense_input_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&norm1_params),
            scratch.dense_hidden_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&net0_params),
            scratch.dense_output_params_buffer.buffer()?,
        );

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();

        encoder.set_compute_pipeline_state(&self.torch_linear_vjp_pipeline);
        match linear_6_cotangent_rows {
            FlatF32RowsSource::Cpu(_) => {
                encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
            }
            FlatF32RowsSource::Metal(rows) => {
                encoder.set_buffer(0, Some(&rows.buffer), 0);
            }
        }
        encoder.set_buffer(1, Some(&net6_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(3, Some(scratch.params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.torch_linear_vjp_pipeline, hidden_len)?;

        encoder.set_compute_pipeline_state(&self.layer_norm_silu_vjp_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(scratch.weight_buffer.buffer()?), 0);
        encoder.set_buffer(2, Some(&norm4_buffers.weight_buffer), 0);
        encoder.set_buffer(3, Some(&norm4_buffers.bias_buffer), 0);
        encoder.set_buffer(4, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(5, Some(scratch.layer_norm_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.layer_norm_silu_vjp_pipeline, row_count)?;

        encoder.set_compute_pipeline_state(&self.torch_linear_vjp_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&net3_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(3, Some(scratch.dense_input_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.torch_linear_vjp_pipeline, hidden_len)?;

        encoder.set_compute_pipeline_state(&self.layer_norm_silu_vjp_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(scratch.bias_buffer.buffer()?), 0);
        encoder.set_buffer(2, Some(&norm1_buffers.weight_buffer), 0);
        encoder.set_buffer(3, Some(&norm1_buffers.bias_buffer), 0);
        encoder.set_buffer(4, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(5, Some(scratch.dense_hidden_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.layer_norm_silu_vjp_pipeline, row_count)?;

        encoder.set_compute_pipeline_state(&self.torch_linear_vjp_prefix_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&net0_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(3, Some(scratch.dense_output_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.torch_linear_vjp_prefix_pipeline, prefix_len)?;

        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }

        let output_ptr = scratch.output_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(output_ptr, &mut scratch.output_f32);

        Ok(scratch
            .output_f32
            .chunks_exact(prefix_input_dim)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect())
    }

    #[allow(clippy::too_many_arguments)]
    fn conv_weight_mlp_cutoff_norm7_tail_metal_vjp_f32_with_static_tables(
        &self,
        output_cotangent_rows: &MacePolarFlatRowsF32Metal,
        retained_cutoff_output_rows: &[Vec<f64>],
        retained_cutoff_output_f32: &MacePolarFlatRowsF32Metal,
        cutoffs: &[f64],
        linear_6_input_rows: &[Vec<f64>],
        linear_3_input_rows: &[Vec<f64>],
        linear_0_input_rows: &[Vec<f64>],
        net9_table: &DenseLinearStaticTable,
        norm7_table: &LayerNormStaticTable,
        net6_table: &DenseLinearStaticTable,
        norm4_table: &LayerNormStaticTable,
        net3_table: &DenseLinearStaticTable,
        norm1_table: &LayerNormStaticTable,
        net0_table: &DenseLinearStaticTable,
        prefix_input_dim: usize,
        name: &str,
    ) -> Result<(MacePolarRows, Vec<f64>), String> {
        let row_count = output_cotangent_rows.row_count;
        validate_conv_weight_mlp_tables(
            net0_table,
            norm1_table,
            net3_table,
            norm4_table,
            net6_table,
            norm7_table,
            net9_table,
        )?;
        validate_flat_rows_f32_source(
            FlatF32RowsSource::Metal(output_cotangent_rows),
            row_count,
            net9_table.output_dim,
            name,
        )?;
        validate_flat_rows_f32_source(
            FlatF32RowsSource::Metal(retained_cutoff_output_f32),
            row_count,
            net9_table.output_dim,
            name,
        )?;
        if row_count == 0 {
            return Ok((Vec::new(), Vec::new()));
        }
        if retained_cutoff_output_rows.len() != row_count {
            return Err(format!(
                "{name}.retained_cutoff_output row count mismatch: expected {row_count}, got {}",
                retained_cutoff_output_rows.len()
            ));
        }
        if cutoffs.len() != row_count {
            return Err(format!(
                "{name}.cutoffs length mismatch: expected {row_count}, got {}",
                cutoffs.len()
            ));
        }
        if linear_6_input_rows.len() != row_count {
            return Err(format!(
                "{name}.linear_6_input row count mismatch: expected {row_count}, got {}",
                linear_6_input_rows.len()
            ));
        }
        if linear_3_input_rows.len() != row_count {
            return Err(format!(
                "{name}.linear_3_input row count mismatch: expected {row_count}, got {}",
                linear_3_input_rows.len()
            ));
        }
        if linear_0_input_rows.len() != row_count {
            return Err(format!(
                "{name}.linear_0_input row count mismatch: expected {row_count}, got {}",
                linear_0_input_rows.len()
            ));
        }
        if prefix_input_dim > net0_table.input_dim {
            return Err(format!(
                "{name}.prefix_input_dim mismatch: prefix {prefix_input_dim} exceeds input dim {}",
                net0_table.input_dim
            ));
        }

        let hidden = net0_table.output_dim;
        let hidden_len = row_count
            .checked_mul(hidden)
            .ok_or_else(|| format!("{name} hidden length overflows usize"))?;
        let net9_output_len = row_count
            .checked_mul(net9_table.output_dim)
            .ok_or_else(|| format!("{name} net9 output length overflows usize"))?;
        let prefix_len = row_count
            .checked_mul(prefix_input_dim)
            .ok_or_else(|| format!("{name} prefix output length overflows usize"))?;
        if net9_output_len == 0 || prefix_len == 0 {
            return Ok((vec![Vec::new(); row_count], vec![0.0; row_count]));
        }

        let net9_params = PolarTorchLinearParamsMetal {
            row_count: u32::try_from(row_count)
                .map_err(|_| format!("{name} row count exceeds Metal u32 range"))?,
            input_dim: u32::try_from(net9_table.input_dim)
                .map_err(|_| format!("{name} net9 input dim exceeds Metal u32 range"))?,
            output_dim: u32::try_from(net9_table.output_dim)
                .map_err(|_| format!("{name} net9 output dim exceeds Metal u32 range"))?,
        };
        let norm7_params = PolarLayerNormSiluParamsMetal {
            row_count: net9_params.row_count,
            width: net9_params.input_dim,
            eps: norm7_table.eps_f32,
        };
        let net6_params = PolarTorchLinearParamsMetal {
            row_count: net9_params.row_count,
            input_dim: u32::try_from(net6_table.input_dim)
                .map_err(|_| format!("{name} net6 input dim exceeds Metal u32 range"))?,
            output_dim: u32::try_from(net6_table.output_dim)
                .map_err(|_| format!("{name} net6 output dim exceeds Metal u32 range"))?,
        };
        let norm4_params = PolarLayerNormSiluParamsMetal {
            row_count: net9_params.row_count,
            width: u32::try_from(norm4_table.width)
                .map_err(|_| format!("{name} norm4 width exceeds Metal u32 range"))?,
            eps: norm4_table.eps_f32,
        };
        let net3_params = PolarTorchLinearParamsMetal {
            row_count: net9_params.row_count,
            input_dim: u32::try_from(net3_table.input_dim)
                .map_err(|_| format!("{name} net3 input dim exceeds Metal u32 range"))?,
            output_dim: u32::try_from(net3_table.output_dim)
                .map_err(|_| format!("{name} net3 output dim exceeds Metal u32 range"))?,
        };
        let norm1_params = PolarLayerNormSiluParamsMetal {
            row_count: net9_params.row_count,
            width: u32::try_from(norm1_table.width)
                .map_err(|_| format!("{name} norm1 width exceeds Metal u32 range"))?,
            eps: norm1_table.eps_f32,
        };
        let net0_params = PolarTorchLinearVjpPrefixParamsMetal {
            row_count: net9_params.row_count,
            prefix_input_dim: u32::try_from(prefix_input_dim)
                .map_err(|_| format!("{name} prefix input dim exceeds Metal u32 range"))?,
            output_dim: u32::try_from(net0_table.output_dim)
                .map_err(|_| format!("{name} net0 output dim exceeds Metal u32 range"))?,
            weight_input_dim: u32::try_from(net0_table.input_dim)
                .map_err(|_| format!("{name} net0 input dim exceeds Metal u32 range"))?,
        };
        let net9_dispatch_len = hidden_len
            .checked_add(row_count)
            .ok_or_else(|| format!("{name} net9 dispatch length overflows usize"))?;

        let net9_buffers = net9_table.metal_buffers(&self.device)?;
        let norm7_buffers = norm7_table.metal_buffers(&self.device)?;
        let net6_buffers = net6_table.metal_buffers(&self.device)?;
        let norm4_buffers = norm4_table.metal_buffers(&self.device)?;
        let net3_buffers = net3_table.metal_buffers(&self.device)?;
        let norm1_buffers = norm1_table.metal_buffers(&self.device)?;
        let net0_buffers = net0_table.metal_buffers(&self.device)?;
        let options = MTLResourceOptions::StorageModeShared;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;
        f64_to_f32_vec_into(cutoffs, &mut scratch.cutoff_f32);
        flatten_rows_f32_into(
            linear_6_input_rows,
            hidden,
            &format!("{name}.linear_6_input"),
            &mut scratch.input_f32,
        )?;
        flatten_rows_f32_into(
            linear_3_input_rows,
            hidden,
            &format!("{name}.linear_3_input"),
            &mut scratch.weight_f32,
        )?;
        flatten_rows_f32_into(
            linear_0_input_rows,
            hidden,
            &format!("{name}.linear_0_input"),
            &mut scratch.bias_f32,
        )?;
        scratch.output_f32.clear();
        scratch.output_f32.resize(prefix_len, 0.0);
        scratch.gate_f32.clear();
        scratch.gate_f32.resize(row_count, 0.0);

        let hidden_bytes = hidden_len
            .checked_mul(std::mem::size_of::<f32>())
            .ok_or_else(|| format!("{name} hidden byte length overflows usize"))?;
        let prefix_bytes = prefix_len
            .checked_mul(std::mem::size_of::<f32>())
            .ok_or_else(|| format!("{name} prefix byte length overflows usize"))?;
        let cutoff_bytes = std::mem::size_of_val(scratch.cutoff_f32.as_slice());
        let linear6_bytes = std::mem::size_of_val(scratch.input_f32.as_slice());
        let linear3_bytes = std::mem::size_of_val(scratch.weight_f32.as_slice());
        let linear0_bytes = std::mem::size_of_val(scratch.bias_f32.as_slice());
        let cutoff_cotangent_bytes = std::mem::size_of_val(scratch.gate_f32.as_slice());
        let net9_params_bytes = std::mem::size_of_val(std::slice::from_ref(&net9_params));
        let norm7_params_bytes = std::mem::size_of_val(std::slice::from_ref(&norm7_params));
        let net6_params_bytes = std::mem::size_of_val(std::slice::from_ref(&net6_params));
        let norm4_params_bytes = std::mem::size_of_val(std::slice::from_ref(&norm4_params));
        let net3_params_bytes = std::mem::size_of_val(std::slice::from_ref(&net3_params));
        let norm1_params_bytes = std::mem::size_of_val(std::slice::from_ref(&norm1_params));
        let net0_params_bytes = std::mem::size_of_val(std::slice::from_ref(&net0_params));

        scratch
            .cutoff_buffer
            .ensure_capacity(&self.device, cutoff_bytes, options)?;
        scratch
            .hidden_a_buffer
            .ensure_capacity(&self.device, hidden_bytes, options)?;
        scratch
            .hidden_b_buffer
            .ensure_capacity(&self.device, hidden_bytes, options)?;
        scratch
            .input_buffer
            .ensure_capacity(&self.device, linear6_bytes, options)?;
        scratch
            .weight_buffer
            .ensure_capacity(&self.device, linear3_bytes, options)?;
        scratch
            .bias_buffer
            .ensure_capacity(&self.device, linear0_bytes, options)?;
        scratch
            .output_buffer
            .ensure_capacity(&self.device, prefix_bytes, options)?;
        scratch
            .gate_mask_buffer
            .ensure_capacity(&self.device, cutoff_cotangent_bytes, options)?;
        scratch
            .params_buffer
            .ensure_capacity(&self.device, net9_params_bytes, options)?;
        scratch.layer_norm_params_buffer.ensure_capacity(
            &self.device,
            norm7_params_bytes,
            options,
        )?;
        scratch.dense_input_params_buffer.ensure_capacity(
            &self.device,
            net6_params_bytes,
            options,
        )?;
        scratch.dense_hidden_params_buffer.ensure_capacity(
            &self.device,
            norm4_params_bytes,
            options,
        )?;
        scratch.dense_output_params_buffer.ensure_capacity(
            &self.device,
            net3_params_bytes,
            options,
        )?;
        scratch
            .block_params_buffer
            .ensure_capacity(&self.device, norm1_params_bytes, options)?;
        scratch
            .post_params_buffer
            .ensure_capacity(&self.device, net0_params_bytes, options)?;

        copy_slice_to_buffer(&scratch.cutoff_f32, scratch.cutoff_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.input_f32, scratch.input_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.weight_f32, scratch.weight_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.bias_f32, scratch.bias_buffer.buffer()?);
        copy_slice_to_buffer(
            std::slice::from_ref(&net9_params),
            scratch.params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&norm7_params),
            scratch.layer_norm_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&net6_params),
            scratch.dense_input_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&norm4_params),
            scratch.dense_hidden_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&net3_params),
            scratch.dense_output_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&norm1_params),
            scratch.block_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&net0_params),
            scratch.post_params_buffer.buffer()?,
        );

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();

        encoder.set_compute_pipeline_state(&self.torch_linear_vjp_cutoff_retained_pipeline);
        encoder.set_buffer(0, Some(&output_cotangent_rows.buffer), 0);
        encoder.set_buffer(1, Some(&retained_cutoff_output_f32.buffer), 0);
        encoder.set_buffer(2, Some(scratch.cutoff_buffer.buffer()?), 0);
        encoder.set_buffer(3, Some(&net9_buffers.weight_buffer), 0);
        encoder.set_buffer(4, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(5, Some(scratch.gate_mask_buffer.buffer()?), 0);
        encoder.set_buffer(6, Some(scratch.params_buffer.buffer()?), 0);
        self.dispatch_1d(
            &encoder,
            &self.torch_linear_vjp_cutoff_retained_pipeline,
            net9_dispatch_len,
        )?;

        encoder.set_compute_pipeline_state(&self.layer_norm_silu_vjp_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(scratch.input_buffer.buffer()?), 0);
        encoder.set_buffer(2, Some(&norm7_buffers.weight_buffer), 0);
        encoder.set_buffer(3, Some(&norm7_buffers.bias_buffer), 0);
        encoder.set_buffer(4, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(5, Some(scratch.layer_norm_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.layer_norm_silu_vjp_pipeline, row_count)?;

        encoder.set_compute_pipeline_state(&self.torch_linear_vjp_pipeline);
        encoder.set_buffer(0, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&net6_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(3, Some(scratch.dense_input_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.torch_linear_vjp_pipeline, hidden_len)?;

        encoder.set_compute_pipeline_state(&self.layer_norm_silu_vjp_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(scratch.weight_buffer.buffer()?), 0);
        encoder.set_buffer(2, Some(&norm4_buffers.weight_buffer), 0);
        encoder.set_buffer(3, Some(&norm4_buffers.bias_buffer), 0);
        encoder.set_buffer(4, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(5, Some(scratch.dense_hidden_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.layer_norm_silu_vjp_pipeline, row_count)?;

        encoder.set_compute_pipeline_state(&self.torch_linear_vjp_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&net3_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(3, Some(scratch.dense_output_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.torch_linear_vjp_pipeline, hidden_len)?;

        encoder.set_compute_pipeline_state(&self.layer_norm_silu_vjp_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(scratch.bias_buffer.buffer()?), 0);
        encoder.set_buffer(2, Some(&norm1_buffers.weight_buffer), 0);
        encoder.set_buffer(3, Some(&norm1_buffers.bias_buffer), 0);
        encoder.set_buffer(4, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(5, Some(scratch.block_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.layer_norm_silu_vjp_pipeline, row_count)?;

        encoder.set_compute_pipeline_state(&self.torch_linear_vjp_prefix_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&net0_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(3, Some(scratch.post_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.torch_linear_vjp_prefix_pipeline, prefix_len)?;

        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }

        let output_ptr = scratch.output_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(output_ptr, &mut scratch.output_f32);
        let cutoff_ptr = scratch.gate_mask_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(cutoff_ptr, &mut scratch.gate_f32);
        let edge_aug = scratch
            .output_f32
            .chunks_exact(prefix_input_dim)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect();
        let cutoff_cotangent = scratch
            .gate_f32
            .iter()
            .map(|value| f64::from(*value))
            .collect();
        Ok((edge_aug, cutoff_cotangent))
    }

    fn conv_tp_weights_mlp_cutoff_rows_f32_with_static_tables(
        &self,
        edge_aug_rows: &[Vec<f64>],
        cutoffs: &[f64],
        dense_tables: [&DenseLinearStaticTable; 4],
        norm_tables: [&LayerNormStaticTable; 3],
        name: &str,
    ) -> Result<MacePolarRows, String> {
        let row_count = edge_aug_rows.len();
        if row_count == 0 {
            return Ok(Vec::new());
        }
        if cutoffs.len() != row_count {
            return Err(format!(
                "{name}.cutoffs length mismatch: expected {row_count}, got {}",
                cutoffs.len()
            ));
        }
        let [linear0, linear3, linear6, linear9] = dense_tables;
        let [norm1, norm4, norm7] = norm_tables;
        validate_conv_weight_mlp_tables(linear0, norm1, linear3, norm4, linear6, norm7, linear9)?;

        let hidden = linear0.output_dim;
        let output_dim = linear9.output_dim;
        let hidden_len = row_count
            .checked_mul(hidden)
            .ok_or_else(|| "conv weight MLP hidden buffer length overflows usize".to_owned())?;
        let output_len = row_count
            .checked_mul(output_dim)
            .ok_or_else(|| "conv weight MLP output length overflows usize".to_owned())?;
        if output_len == 0 {
            return Ok(vec![Vec::new(); row_count]);
        }

        let linear0_buffers = linear0.metal_buffers(&self.device)?;
        let linear3_buffers = linear3.metal_buffers(&self.device)?;
        let linear6_buffers = linear6.metal_buffers(&self.device)?;
        let linear9_buffers = linear9.metal_buffers(&self.device)?;
        let norm1_buffers = norm1.metal_buffers(&self.device)?;
        let norm4_buffers = norm4.metal_buffers(&self.device)?;
        let norm7_buffers = norm7.metal_buffers(&self.device)?;

        let dense_input_params = PolarTorchLinearParamsMetal {
            row_count: u32::try_from(row_count)
                .map_err(|_| "row count exceeds Metal u32 range".to_owned())?,
            input_dim: u32::try_from(linear0.input_dim)
                .map_err(|_| "edge MLP input dim exceeds Metal u32 range".to_owned())?,
            output_dim: u32::try_from(hidden)
                .map_err(|_| "edge MLP hidden dim exceeds Metal u32 range".to_owned())?,
        };
        let dense_hidden_params = PolarTorchLinearParamsMetal {
            row_count: dense_input_params.row_count,
            input_dim: dense_input_params.output_dim,
            output_dim: dense_input_params.output_dim,
        };
        let dense_output_params = PolarTorchLinearParamsMetal {
            row_count: dense_input_params.row_count,
            input_dim: dense_input_params.output_dim,
            output_dim: u32::try_from(output_dim)
                .map_err(|_| "edge MLP output dim exceeds Metal u32 range".to_owned())?,
        };
        let layer_norm_params = PolarLayerNormSiluParamsMetal {
            row_count: dense_input_params.row_count,
            width: dense_input_params.output_dim,
            eps: norm1.eps_f32,
        };
        let post_params = PolarCutoffRowsParamsMetal {
            row_count: dense_input_params.row_count,
            row_dim: dense_output_params.output_dim,
        };
        let options = MTLResourceOptions::StorageModeShared;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;
        flatten_rows_f32_into(
            edge_aug_rows,
            linear0.input_dim,
            name,
            &mut scratch.input_f32,
        )?;
        f64_to_f32_vec_into(cutoffs, &mut scratch.cutoff_f32);
        scratch.output_f32.clear();
        scratch.output_f32.resize(output_len, 0.0);

        let input_bytes = std::mem::size_of_val(scratch.input_f32.as_slice());
        let hidden_bytes = hidden_len
            .checked_mul(std::mem::size_of::<f32>())
            .ok_or_else(|| "conv weight MLP hidden byte length overflows usize".to_owned())?;
        let output_bytes = std::mem::size_of_val(scratch.output_f32.as_slice());
        let cutoff_bytes = std::mem::size_of_val(scratch.cutoff_f32.as_slice());
        let dense_params_bytes = std::mem::size_of_val(std::slice::from_ref(&dense_input_params));
        let layer_norm_params_bytes =
            std::mem::size_of_val(std::slice::from_ref(&layer_norm_params));
        let post_params_bytes = std::mem::size_of_val(std::slice::from_ref(&post_params));

        scratch
            .input_buffer
            .ensure_capacity(&self.device, input_bytes, options)?;
        scratch
            .hidden_a_buffer
            .ensure_capacity(&self.device, hidden_bytes, options)?;
        scratch
            .hidden_b_buffer
            .ensure_capacity(&self.device, hidden_bytes, options)?;
        scratch
            .output_buffer
            .ensure_capacity(&self.device, output_bytes, options)?;
        scratch
            .cutoff_buffer
            .ensure_capacity(&self.device, cutoff_bytes, options)?;
        scratch.dense_input_params_buffer.ensure_capacity(
            &self.device,
            dense_params_bytes,
            options,
        )?;
        scratch.dense_hidden_params_buffer.ensure_capacity(
            &self.device,
            dense_params_bytes,
            options,
        )?;
        scratch.dense_output_params_buffer.ensure_capacity(
            &self.device,
            dense_params_bytes,
            options,
        )?;
        scratch.layer_norm_params_buffer.ensure_capacity(
            &self.device,
            layer_norm_params_bytes,
            options,
        )?;
        scratch
            .post_params_buffer
            .ensure_capacity(&self.device, post_params_bytes, options)?;

        copy_slice_to_buffer(&scratch.input_f32, scratch.input_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.cutoff_f32, scratch.cutoff_buffer.buffer()?);
        copy_slice_to_buffer(
            std::slice::from_ref(&dense_input_params),
            scratch.dense_input_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&dense_hidden_params),
            scratch.dense_hidden_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&dense_output_params),
            scratch.dense_output_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&layer_norm_params),
            scratch.layer_norm_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&post_params),
            scratch.post_params_buffer.buffer()?,
        );

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();

        encoder.set_compute_pipeline_state(&self.torch_linear_pipeline);
        encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&linear0_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(&linear0_buffers.bias_buffer), 0);
        encoder.set_buffer(3, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(scratch.dense_input_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.torch_linear_pipeline, hidden_len)?;

        encoder.set_compute_pipeline_state(&self.layer_norm_silu_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&norm1_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(&norm1_buffers.bias_buffer), 0);
        encoder.set_buffer(3, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(scratch.layer_norm_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.layer_norm_silu_pipeline, row_count)?;

        encoder.set_compute_pipeline_state(&self.torch_linear_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&linear3_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(&linear3_buffers.bias_buffer), 0);
        encoder.set_buffer(3, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(scratch.dense_hidden_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.torch_linear_pipeline, hidden_len)?;

        encoder.set_compute_pipeline_state(&self.layer_norm_silu_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&norm4_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(&norm4_buffers.bias_buffer), 0);
        encoder.set_buffer(3, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(scratch.layer_norm_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.layer_norm_silu_pipeline, row_count)?;

        encoder.set_compute_pipeline_state(&self.torch_linear_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&linear6_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(&linear6_buffers.bias_buffer), 0);
        encoder.set_buffer(3, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(scratch.dense_hidden_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.torch_linear_pipeline, hidden_len)?;

        encoder.set_compute_pipeline_state(&self.layer_norm_silu_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&norm7_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(&norm7_buffers.bias_buffer), 0);
        encoder.set_buffer(3, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(scratch.layer_norm_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.layer_norm_silu_pipeline, row_count)?;

        encoder.set_compute_pipeline_state(&self.torch_linear_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&linear9_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(&linear9_buffers.bias_buffer), 0);
        encoder.set_buffer(3, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(scratch.dense_output_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.torch_linear_pipeline, output_len)?;

        encoder.set_compute_pipeline_state(&self.apply_cutoff_pipeline);
        encoder.set_buffer(0, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(scratch.cutoff_buffer.buffer()?), 0);
        encoder.set_buffer(2, Some(scratch.post_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.apply_cutoff_pipeline, output_len)?;

        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }

        let output_ptr = scratch.output_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(output_ptr, &mut scratch.output_f32);

        f32_rows_from_chunks(&scratch.output_f32, output_dim, name)
    }

    fn local_electron_mlp_rows_f32_with_static_tables(
        &self,
        input_rows: &[Vec<f64>],
        dense_tables: [&DenseLinearStaticTable; 4],
        norm_tables: [&LayerNormStaticTable; 3],
        name: &str,
    ) -> Result<LocalElectronMlpRows, String> {
        if dense_tables[3].output_dim != 1 {
            return Err(format!(
                "{name}.linear9 output mismatch: expected 1, got {}",
                dense_tables[3].output_dim
            ));
        }
        self.traced_mlp_rows_f32_with_static_tables(
            input_rows,
            dense_tables,
            norm_tables,
            true,
            name,
        )
    }

    fn traced_mlp_rows_f32_with_static_tables(
        &self,
        input_rows: &[Vec<f64>],
        dense_tables: [&DenseLinearStaticTable; 4],
        norm_tables: [&LayerNormStaticTable; 3],
        retain_rows: bool,
        name: &str,
    ) -> Result<LocalElectronMlpRows, String> {
        let row_count = input_rows.len();
        if row_count == 0 {
            return Ok(LocalElectronMlpRows {
                z0_rows: Vec::new(),
                ln1_rows: Vec::new(),
                a1_rows: Vec::new(),
                z3_rows: Vec::new(),
                ln4_rows: Vec::new(),
                a4_rows: Vec::new(),
                z6_rows: Vec::new(),
                ln7_rows: Vec::new(),
                a7_rows: Vec::new(),
                output_rows: Vec::new(),
            });
        }

        let [linear0, linear3, linear6, linear9] = dense_tables;
        let [norm1, norm4, norm7] = norm_tables;
        validate_conv_weight_mlp_tables(linear0, norm1, linear3, norm4, linear6, norm7, linear9)?;

        let hidden = linear0.output_dim;
        let hidden_len = row_count
            .checked_mul(hidden)
            .ok_or_else(|| format!("{name}.hidden buffer length overflows usize"))?;
        let trace_width = hidden
            .checked_mul(9)
            .ok_or_else(|| format!("{name}.trace width overflows usize"))?;
        let trace_len = row_count
            .checked_mul(trace_width)
            .ok_or_else(|| format!("{name}.trace length overflows usize"))?;
        let output_len = row_count
            .checked_mul(linear9.output_dim)
            .ok_or_else(|| format!("{name}.output length overflows usize"))?;

        let linear0_buffers = linear0.metal_buffers(&self.device)?;
        let linear3_buffers = linear3.metal_buffers(&self.device)?;
        let linear6_buffers = linear6.metal_buffers(&self.device)?;
        let linear9_buffers = linear9.metal_buffers(&self.device)?;
        let norm1_buffers = norm1.metal_buffers(&self.device)?;
        let norm4_buffers = norm4.metal_buffers(&self.device)?;
        let norm7_buffers = norm7.metal_buffers(&self.device)?;

        let dense_input_params = PolarTorchLinearParamsMetal {
            row_count: u32::try_from(row_count)
                .map_err(|_| "local electron row count exceeds Metal u32 range".to_owned())?,
            input_dim: u32::try_from(linear0.input_dim)
                .map_err(|_| "local electron input dim exceeds Metal u32 range".to_owned())?,
            output_dim: u32::try_from(hidden)
                .map_err(|_| "local electron hidden dim exceeds Metal u32 range".to_owned())?,
        };
        let dense_hidden_params = PolarTorchLinearParamsMetal {
            row_count: dense_input_params.row_count,
            input_dim: dense_input_params.output_dim,
            output_dim: dense_input_params.output_dim,
        };
        let dense_output_params = PolarTorchLinearParamsMetal {
            row_count: dense_input_params.row_count,
            input_dim: dense_input_params.output_dim,
            output_dim: u32::try_from(linear9.output_dim)
                .map_err(|_| "local electron output dim exceeds Metal u32 range".to_owned())?,
        };
        let layer_norm_params = PolarLayerNormSiluParamsMetal {
            row_count: dense_input_params.row_count,
            width: dense_input_params.output_dim,
            eps: norm1.eps_f32,
        };
        let trace_width_u32 = u32::try_from(trace_width)
            .map_err(|_| "local electron trace width exceeds Metal u32 range".to_owned())?;
        let hidden_u32 = u32::try_from(hidden)
            .map_err(|_| "local electron hidden dim exceeds Metal u32 range".to_owned())?;
        let copy_params = (0..9_u32)
            .map(|segment| PolarProductSegmentCopyParamsMetal {
                row_count: dense_input_params.row_count,
                segment_dim: hidden_u32,
                output_dim: trace_width_u32,
                output_offset: segment * hidden_u32,
            })
            .collect::<Vec<_>>();
        let copy_param_stride = u64::try_from(std::mem::size_of::<
            PolarProductSegmentCopyParamsMetal,
        >())
        .map_err(|_| "local electron copy param stride exceeds Metal u64 range".to_owned())?;

        let options = MTLResourceOptions::StorageModeShared;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;
        flatten_rows_f32_into(input_rows, linear0.input_dim, name, &mut scratch.input_f32)?;
        scratch.output_f32.clear();
        scratch.output_f32.resize(output_len, 0.0);
        scratch.trace_f32.clear();
        scratch.trace_f32.resize(trace_len, 0.0);

        let input_bytes = std::mem::size_of_val(scratch.input_f32.as_slice());
        let hidden_bytes = hidden_len
            .checked_mul(std::mem::size_of::<f32>())
            .ok_or_else(|| format!("{name}.hidden byte length overflows usize"))?;
        let output_bytes = std::mem::size_of_val(scratch.output_f32.as_slice());
        let trace_bytes = std::mem::size_of_val(scratch.trace_f32.as_slice());
        let dense_params_bytes = std::mem::size_of_val(std::slice::from_ref(&dense_input_params));
        let layer_norm_params_bytes =
            std::mem::size_of_val(std::slice::from_ref(&layer_norm_params));
        let copy_params_bytes = std::mem::size_of_val(copy_params.as_slice());

        scratch
            .input_buffer
            .ensure_capacity(&self.device, input_bytes, options)?;
        scratch
            .hidden_a_buffer
            .ensure_capacity(&self.device, hidden_bytes, options)?;
        scratch
            .hidden_b_buffer
            .ensure_capacity(&self.device, hidden_bytes, options)?;
        scratch
            .output_mask_buffer
            .ensure_capacity(&self.device, hidden_bytes, options)?;
        scratch
            .output_buffer
            .ensure_capacity(&self.device, output_bytes, options)?;
        scratch
            .trace_buffer
            .ensure_capacity(&self.device, trace_bytes, options)?;
        scratch.dense_input_params_buffer.ensure_capacity(
            &self.device,
            dense_params_bytes,
            options,
        )?;
        scratch.dense_hidden_params_buffer.ensure_capacity(
            &self.device,
            dense_params_bytes,
            options,
        )?;
        scratch.dense_output_params_buffer.ensure_capacity(
            &self.device,
            dense_params_bytes,
            options,
        )?;
        scratch.layer_norm_params_buffer.ensure_capacity(
            &self.device,
            layer_norm_params_bytes,
            options,
        )?;
        scratch
            .post_params_buffer
            .ensure_capacity(&self.device, copy_params_bytes, options)?;

        copy_slice_to_buffer(&scratch.input_f32, scratch.input_buffer.buffer()?);
        copy_slice_to_buffer(
            std::slice::from_ref(&dense_input_params),
            scratch.dense_input_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&dense_hidden_params),
            scratch.dense_hidden_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&dense_output_params),
            scratch.dense_output_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&layer_norm_params),
            scratch.layer_norm_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(&copy_params, scratch.post_params_buffer.buffer()?);

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();
        let run_dense = |input: &Buffer,
                         table_buffers: &DenseLinearStaticBuffers,
                         output: &Buffer,
                         params: &Buffer|
         -> Result<(), String> {
            encoder.set_compute_pipeline_state(&self.torch_linear_pipeline);
            encoder.set_buffer(0, Some(input), 0);
            encoder.set_buffer(1, Some(&table_buffers.weight_buffer), 0);
            encoder.set_buffer(2, Some(&table_buffers.bias_buffer), 0);
            encoder.set_buffer(3, Some(output), 0);
            encoder.set_buffer(4, Some(params), 0);
            self.dispatch_1d(&encoder, &self.torch_linear_pipeline, hidden_len)
        };
        let run_output_dense = |input: &Buffer| -> Result<(), String> {
            encoder.set_compute_pipeline_state(&self.torch_linear_pipeline);
            encoder.set_buffer(0, Some(input), 0);
            encoder.set_buffer(1, Some(&linear9_buffers.weight_buffer), 0);
            encoder.set_buffer(2, Some(&linear9_buffers.bias_buffer), 0);
            encoder.set_buffer(3, Some(scratch.output_buffer.buffer()?), 0);
            encoder.set_buffer(4, Some(scratch.dense_output_params_buffer.buffer()?), 0);
            self.dispatch_1d(&encoder, &self.torch_linear_pipeline, output_len)
        };
        let run_norm_pair =
            |input: &Buffer, table_buffers: &LayerNormStaticBuffers| -> Result<(), String> {
                encoder.set_compute_pipeline_state(&self.layer_norm_silu_pair_pipeline);
                encoder.set_buffer(0, Some(input), 0);
                encoder.set_buffer(1, Some(&table_buffers.weight_buffer), 0);
                encoder.set_buffer(2, Some(&table_buffers.bias_buffer), 0);
                encoder.set_buffer(3, Some(scratch.hidden_b_buffer.buffer()?), 0);
                encoder.set_buffer(4, Some(scratch.output_mask_buffer.buffer()?), 0);
                encoder.set_buffer(5, Some(scratch.layer_norm_params_buffer.buffer()?), 0);
                self.dispatch_1d(&encoder, &self.layer_norm_silu_pair_pipeline, row_count)
            };
        let copy_trace = |source: &Buffer, segment: u64| -> Result<(), String> {
            encoder.set_compute_pipeline_state(&self.product_segment_copy_pipeline);
            encoder.set_buffer(0, Some(source), 0);
            encoder.set_buffer(1, Some(scratch.trace_buffer.buffer()?), 0);
            encoder.set_buffer(
                2,
                Some(scratch.post_params_buffer.buffer()?),
                copy_param_stride * segment,
            );
            self.dispatch_1d(&encoder, &self.product_segment_copy_pipeline, hidden_len)
        };

        run_dense(
            scratch.input_buffer.buffer()?,
            linear0_buffers,
            scratch.hidden_a_buffer.buffer()?,
            scratch.dense_input_params_buffer.buffer()?,
        )?;
        if retain_rows {
            copy_trace(scratch.hidden_a_buffer.buffer()?, 0)?;
        }
        run_norm_pair(scratch.hidden_a_buffer.buffer()?, norm1_buffers)?;
        if retain_rows {
            copy_trace(scratch.hidden_b_buffer.buffer()?, 1)?;
            copy_trace(scratch.output_mask_buffer.buffer()?, 2)?;
        }

        run_dense(
            scratch.output_mask_buffer.buffer()?,
            linear3_buffers,
            scratch.hidden_a_buffer.buffer()?,
            scratch.dense_hidden_params_buffer.buffer()?,
        )?;
        if retain_rows {
            copy_trace(scratch.hidden_a_buffer.buffer()?, 3)?;
        }
        run_norm_pair(scratch.hidden_a_buffer.buffer()?, norm4_buffers)?;
        if retain_rows {
            copy_trace(scratch.hidden_b_buffer.buffer()?, 4)?;
            copy_trace(scratch.output_mask_buffer.buffer()?, 5)?;
        }

        run_dense(
            scratch.output_mask_buffer.buffer()?,
            linear6_buffers,
            scratch.hidden_a_buffer.buffer()?,
            scratch.dense_hidden_params_buffer.buffer()?,
        )?;
        if retain_rows {
            copy_trace(scratch.hidden_a_buffer.buffer()?, 6)?;
        }
        run_norm_pair(scratch.hidden_a_buffer.buffer()?, norm7_buffers)?;
        if retain_rows {
            copy_trace(scratch.hidden_b_buffer.buffer()?, 7)?;
            copy_trace(scratch.output_mask_buffer.buffer()?, 8)?;
        }
        run_output_dense(scratch.output_mask_buffer.buffer()?)?;

        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }

        let output_ptr = scratch.output_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(output_ptr, &mut scratch.output_f32);
        let output_rows = scratch
            .output_f32
            .chunks_exact(linear9.output_dim)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect();
        if !retain_rows {
            return Ok(LocalElectronMlpRows {
                z0_rows: Vec::new(),
                ln1_rows: Vec::new(),
                a1_rows: Vec::new(),
                z3_rows: Vec::new(),
                ln4_rows: Vec::new(),
                a4_rows: Vec::new(),
                z6_rows: Vec::new(),
                ln7_rows: Vec::new(),
                a7_rows: Vec::new(),
                output_rows,
            });
        }

        let trace_ptr = scratch.trace_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(trace_ptr, &mut scratch.trace_f32);
        let trace_rows = |trace: &[f32], offset: usize| -> MacePolarRows {
            trace
                .chunks_exact(trace_width)
                .map(|row| {
                    row[offset..offset + hidden]
                        .iter()
                        .map(|value| f64::from(*value))
                        .collect()
                })
                .collect()
        };

        Ok(LocalElectronMlpRows {
            z0_rows: trace_rows(&scratch.trace_f32, 0),
            ln1_rows: trace_rows(&scratch.trace_f32, hidden),
            a1_rows: trace_rows(&scratch.trace_f32, hidden * 2),
            z3_rows: trace_rows(&scratch.trace_f32, hidden * 3),
            ln4_rows: trace_rows(&scratch.trace_f32, hidden * 4),
            a4_rows: trace_rows(&scratch.trace_f32, hidden * 5),
            z6_rows: trace_rows(&scratch.trace_f32, hidden * 6),
            ln7_rows: trace_rows(&scratch.trace_f32, hidden * 7),
            a7_rows: trace_rows(&scratch.trace_f32, hidden * 8),
            output_rows,
        })
    }

    #[allow(clippy::too_many_arguments)]
    fn edge_aug_conv_tp_weights_mlp_cutoff_rows_f32_with_static_tables(
        &self,
        edge_feats: &[Vec<f64>],
        edge_index: &[[usize; 2]],
        source_embedding: &[Vec<f64>],
        target_embedding: &[Vec<f64>],
        cutoffs: &[f64],
        dense_tables: [&DenseLinearStaticTable; 4],
        norm_tables: [&LayerNormStaticTable; 3],
        conv_tp_scatter: Option<ConvTpScatterInputs<'_>>,
        density_mlp: Option<DensityMlpInputs<'_>>,
        read_edge_aug_rows: bool,
        read_conv_weight_rows: bool,
        retain_conv_weight_mlp_inputs: bool,
        read_density_rows: bool,
        name: &str,
    ) -> Result<FusedEdgeConvDensityBackendRows, String> {
        let edge_count = edge_index.len();
        if edge_count == 0 {
            let scatter = conv_tp_scatter.map(|inputs| ConvTpScatterOutput {
                scatter_rows: Vec::new(),
                post_scatter_block_linear_rows: inputs
                    .post_scatter_block_linear
                    .map(|_| Vec::new()),
            });
            let density_rows = density_mlp
                .as_ref()
                .and_then(|_| read_density_rows.then(Vec::new));
            return Ok((
                Vec::new(),
                Vec::new(),
                None,
                None,
                None,
                density_rows,
                None,
                scatter,
            ));
        }
        let trace_timings = mace_polar_trace_timings_enabled();
        let mut stage_start = trace_timings.then(Instant::now);
        if edge_feats.len() != edge_count {
            return Err(format!(
                "{name}.edge_feats length mismatch: expected {edge_count}, got {}",
                edge_feats.len()
            ));
        }
        if cutoffs.len() != edge_count {
            return Err(format!(
                "{name}.cutoffs length mismatch: expected {edge_count}, got {}",
                cutoffs.len()
            ));
        }
        if source_embedding.len() != target_embedding.len() {
            return Err(format!(
                "{name}.source/target embedding row count mismatch: source={} target={}",
                source_embedding.len(),
                target_embedding.len()
            ));
        }
        let node_count = source_embedding.len();
        let edge_feat_dim = edge_feats
            .first()
            .map(Vec::len)
            .ok_or_else(|| format!("{name}.edge_feats must not be empty"))?;
        let hidden_dim = source_embedding
            .first()
            .map(Vec::len)
            .ok_or_else(|| format!("{name}.source_embedding must not be empty"))?;
        if target_embedding.first().map(Vec::len) != Some(hidden_dim) {
            return Err(format!(
                "{name}.target_embedding width mismatch: expected {hidden_dim}, got {:?}",
                target_embedding.first().map(Vec::len)
            ));
        }
        let edge_aug_dim = edge_feat_dim
            .checked_add(hidden_dim.checked_mul(2).ok_or_else(|| {
                format!("{name}.edge_aug hidden output dimension overflows usize")
            })?)
            .ok_or_else(|| format!("{name}.edge_aug output dimension overflows usize"))?;

        let [linear0, linear3, linear6, linear9] = dense_tables;
        let [norm1, norm4, norm7] = norm_tables;
        validate_conv_weight_mlp_tables(linear0, norm1, linear3, norm4, linear6, norm7, linear9)?;
        if linear0.input_dim != edge_aug_dim {
            return Err(format!(
                "{name}.linear0 input mismatch: edge_aug_dim={edge_aug_dim}, linear0.input_dim={}",
                linear0.input_dim
            ));
        }

        let conv_hidden = linear0.output_dim;
        let conv_output_dim = linear9.output_dim;
        let edge_aug_len = edge_count
            .checked_mul(edge_aug_dim)
            .ok_or_else(|| format!("{name}.edge_aug output length overflows usize"))?;
        let hidden_len = edge_count
            .checked_mul(conv_hidden)
            .ok_or_else(|| format!("{name}.conv hidden buffer length overflows usize"))?;
        let conv_output_len = edge_count
            .checked_mul(conv_output_dim)
            .ok_or_else(|| format!("{name}.conv output length overflows usize"))?;

        let edge_index_buffers = self.edge_index_buffers(edge_index, node_count, name)?;
        let linear0_buffers = linear0.metal_buffers(&self.device)?;
        let linear3_buffers = linear3.metal_buffers(&self.device)?;
        let linear6_buffers = linear6.metal_buffers(&self.device)?;
        let linear9_buffers = linear9.metal_buffers(&self.device)?;
        let norm1_buffers = norm1.metal_buffers(&self.device)?;
        let norm4_buffers = norm4.metal_buffers(&self.device)?;
        let norm7_buffers = norm7.metal_buffers(&self.device)?;
        let conv_tp_prepared = if let Some(inputs) = conv_tp_scatter {
            if inputs.node_count != node_count {
                return Err(format!(
                    "{name}.conv_tp node_count mismatch: embeddings have {node_count}, conv-TP requested {}",
                    inputs.node_count
                ));
            }
            if inputs.linear_up.len() != inputs.node_count {
                return Err(format!(
                    "{name}.conv_tp.linear_up row count mismatch: expected {}, got {}",
                    inputs.node_count,
                    inputs.linear_up.len()
                ));
            }
            if inputs.edge_attrs.len() != edge_count {
                return Err(format!(
                    "{name}.conv_tp.edge_attrs row count mismatch: expected {edge_count}, got {}",
                    inputs.edge_attrs.len()
                ));
            }
            let scatter_output_len = inputs
                .node_count
                .checked_mul(inputs.table.output_dim)
                .ok_or_else(|| format!("{name}.conv_tp scatter output length overflows usize"))?;
            let params = inputs.table.params(inputs.node_count, edge_count)?;
            let table_buffers = inputs.table.metal_buffers(&self.device)?;
            let post_scatter_block = if let Some(table) = inputs.post_scatter_block_linear {
                if table.input_dim != inputs.table.output_dim {
                    return Err(format!(
                        "{name}.post_scatter_block input mismatch: scatter output={} block input={}",
                        inputs.table.output_dim, table.input_dim
                    ));
                }
                let output_len =
                    inputs
                        .node_count
                        .checked_mul(table.output_dim)
                        .ok_or_else(|| {
                            format!("{name}.post_scatter_block output length overflows usize")
                        })?;
                let params = PolarBlockLinearParamsMetal {
                    row_count: u32::try_from(inputs.node_count).map_err(|_| {
                        "post-scatter block row count exceeds Metal u32 range".to_owned()
                    })?,
                    input_dim: u32::try_from(table.input_dim).map_err(|_| {
                        "post-scatter block input dim exceeds Metal u32 range".to_owned()
                    })?,
                    output_dim: u32::try_from(table.output_dim).map_err(|_| {
                        "post-scatter block output dim exceeds Metal u32 range".to_owned()
                    })?,
                    instruction_count: u32::try_from(table.instructions.len()).map_err(|_| {
                        "post-scatter block instruction count exceeds Metal u32 range".to_owned()
                    })?,
                };
                let buffers = table.metal_buffers(&self.device)?;
                Some((table, output_len, params, buffers))
            } else {
                None
            };
            Some((
                inputs,
                scatter_output_len,
                params,
                table_buffers,
                post_scatter_block,
            ))
        } else {
            None
        };
        let density_prepared = if let Some(inputs) = density_mlp {
            validate_density_mlp_tables(inputs.linear0, inputs.norm1, inputs.linear3)?;
            if inputs.linear0.input_dim != edge_aug_dim {
                return Err(format!(
                    "{name}.density_mlp.linear0 input mismatch: edge_aug_dim={edge_aug_dim}, linear0.input_dim={}",
                    inputs.linear0.input_dim
                ));
            }
            let hidden = inputs.linear0.output_dim;
            let hidden_len = edge_count.checked_mul(hidden).ok_or_else(|| {
                format!("{name}.density MLP hidden buffer length overflows usize")
            })?;
            let output_len = edge_count;
            let dense_input_params = PolarTorchLinearParamsMetal {
                row_count: u32::try_from(edge_count)
                    .map_err(|_| "density MLP row count exceeds Metal u32 range".to_owned())?,
                input_dim: u32::try_from(inputs.linear0.input_dim)
                    .map_err(|_| "density MLP input dim exceeds Metal u32 range".to_owned())?,
                output_dim: u32::try_from(hidden)
                    .map_err(|_| "density MLP hidden dim exceeds Metal u32 range".to_owned())?,
            };
            let dense_output_params = PolarTorchLinearParamsMetal {
                row_count: dense_input_params.row_count,
                input_dim: dense_input_params.output_dim,
                output_dim: 1,
            };
            let layer_norm_params = PolarLayerNormSiluParamsMetal {
                row_count: dense_input_params.row_count,
                width: dense_input_params.output_dim,
                eps: inputs.norm1.eps_f32,
            };
            let post_params = PolarCutoffRowsParamsMetal {
                row_count: dense_input_params.row_count,
                row_dim: 1,
            };
            let linear0_buffers = inputs.linear0.metal_buffers(&self.device)?;
            let linear3_buffers = inputs.linear3.metal_buffers(&self.device)?;
            let norm1_buffers = inputs.norm1.metal_buffers(&self.device)?;
            Some((
                hidden_len,
                output_len,
                dense_input_params,
                dense_output_params,
                layer_norm_params,
                post_params,
                linear0_buffers,
                linear3_buffers,
                norm1_buffers,
            ))
        } else {
            None
        };
        let density_node_scatter_prepared = if density_prepared.is_some() {
            conv_tp_prepared
                .as_ref()
                .map(|(inputs, _, _, _, _)| {
                    let output_len = inputs.node_count;
                    let params = PolarScatterRowsParamsMetal {
                        node_count: u32::try_from(inputs.node_count).map_err(|_| {
                            "density node scatter node count exceeds Metal u32 range".to_owned()
                        })?,
                        edge_count: u32::try_from(edge_count).map_err(|_| {
                            "density node scatter edge count exceeds Metal u32 range".to_owned()
                        })?,
                        row_dim: 1,
                    };
                    Ok::<_, String>((output_len, params))
                })
                .transpose()?
        } else {
            None
        };
        mace_polar_trace_stage(
            "metal.edge_aug_conv_tp_weights_mlp_scatter.prepare_tables",
            stage_start,
        );
        stage_start = trace_timings.then(Instant::now);

        let edge_aug_params = PolarEdgeAugParamsMetal {
            edge_count: u32::try_from(edge_count)
                .map_err(|_| "edge count exceeds Metal u32 range".to_owned())?,
            edge_feat_dim: u32::try_from(edge_feat_dim)
                .map_err(|_| "edge feature dimension exceeds Metal u32 range".to_owned())?,
            hidden_dim: u32::try_from(hidden_dim)
                .map_err(|_| "hidden dimension exceeds Metal u32 range".to_owned())?,
            output_dim: u32::try_from(edge_aug_dim).map_err(|_| {
                "edge augmentation output dimension exceeds Metal u32 range".to_owned()
            })?,
        };
        let dense_input_params = PolarTorchLinearParamsMetal {
            row_count: edge_aug_params.edge_count,
            input_dim: edge_aug_params.output_dim,
            output_dim: u32::try_from(conv_hidden)
                .map_err(|_| "edge MLP hidden dim exceeds Metal u32 range".to_owned())?,
        };
        let dense_hidden_params = PolarTorchLinearParamsMetal {
            row_count: dense_input_params.row_count,
            input_dim: dense_input_params.output_dim,
            output_dim: dense_input_params.output_dim,
        };
        let dense_output_params = PolarTorchLinearParamsMetal {
            row_count: dense_input_params.row_count,
            input_dim: dense_input_params.output_dim,
            output_dim: u32::try_from(conv_output_dim)
                .map_err(|_| "edge MLP output dim exceeds Metal u32 range".to_owned())?,
        };
        let layer_norm_params = PolarLayerNormSiluParamsMetal {
            row_count: dense_input_params.row_count,
            width: dense_input_params.output_dim,
            eps: norm1.eps_f32,
        };
        let post_params = PolarCutoffRowsParamsMetal {
            row_count: dense_input_params.row_count,
            row_dim: dense_output_params.output_dim,
        };
        let conv_trace_width = conv_hidden
            .checked_mul(3)
            .ok_or_else(|| format!("{name}.conv MLP trace width overflows usize"))?;
        let conv_trace_len = edge_count
            .checked_mul(conv_trace_width)
            .ok_or_else(|| format!("{name}.conv MLP trace length overflows usize"))?;
        let conv_hidden_u32 = u32::try_from(conv_hidden)
            .map_err(|_| "edge MLP hidden dim exceeds Metal u32 range".to_owned())?;
        let conv_trace_width_u32 = u32::try_from(conv_trace_width)
            .map_err(|_| "edge MLP trace width exceeds Metal u32 range".to_owned())?;
        let conv_trace_copy_params = if retain_conv_weight_mlp_inputs {
            (0..3_u32)
                .map(|segment| PolarProductSegmentCopyParamsMetal {
                    row_count: dense_input_params.row_count,
                    segment_dim: conv_hidden_u32,
                    output_dim: conv_trace_width_u32,
                    output_offset: segment * conv_hidden_u32,
                })
                .collect::<Vec<_>>()
        } else {
            Vec::new()
        };
        let conv_trace_copy_param_stride = u64::try_from(std::mem::size_of::<
            PolarProductSegmentCopyParamsMetal,
        >())
        .map_err(|_| "edge MLP trace copy param stride exceeds Metal u64 range".to_owned())?;

        let options = MTLResourceOptions::StorageModeShared;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;
        flatten_rows_f32_into(edge_feats, edge_feat_dim, name, &mut scratch.input_f32)?;
        flatten_rows_f32_into(
            source_embedding,
            hidden_dim,
            &format!("{name}.source_embedding"),
            &mut scratch.weight_f32,
        )?;
        flatten_rows_f32_into(
            target_embedding,
            hidden_dim,
            &format!("{name}.target_embedding"),
            &mut scratch.bias_f32,
        )?;
        f64_to_f32_vec_into(cutoffs, &mut scratch.cutoff_f32);
        scratch.edge_aug_f32.clear();
        scratch.edge_aug_f32.resize(edge_aug_len, 0.0);
        scratch.output_f32.clear();
        scratch.output_f32.resize(conv_output_len, 0.0);
        if retain_conv_weight_mlp_inputs {
            scratch.trace_f32.clear();
            scratch.trace_f32.resize(conv_trace_len, 0.0);
        }

        let edge_feat_bytes = std::mem::size_of_val(scratch.input_f32.as_slice());
        let source_bytes = std::mem::size_of_val(scratch.weight_f32.as_slice());
        let target_bytes = std::mem::size_of_val(scratch.bias_f32.as_slice());
        let edge_aug_bytes = std::mem::size_of_val(scratch.edge_aug_f32.as_slice());
        let density_hidden_len = density_prepared
            .as_ref()
            .map(|(hidden_len, _, _, _, _, _, _, _, _)| *hidden_len)
            .unwrap_or(0);
        let hidden_bytes = hidden_len
            .max(density_hidden_len)
            .checked_mul(std::mem::size_of::<f32>())
            .ok_or_else(|| format!("{name}.hidden byte length overflows usize"))?;
        let conv_output_bytes = std::mem::size_of_val(scratch.output_f32.as_slice());
        let conv_trace_bytes = if retain_conv_weight_mlp_inputs {
            conv_trace_len
                .checked_mul(std::mem::size_of::<f32>())
                .ok_or_else(|| format!("{name}.conv MLP trace byte length overflows usize"))?
        } else {
            0
        };
        let conv_trace_copy_params_bytes = std::mem::size_of_val(conv_trace_copy_params.as_slice());
        let cutoff_bytes = std::mem::size_of_val(scratch.cutoff_f32.as_slice());
        let edge_aug_params_bytes = std::mem::size_of_val(std::slice::from_ref(&edge_aug_params));
        let dense_params_bytes = std::mem::size_of_val(std::slice::from_ref(&dense_input_params));
        let layer_norm_params_bytes =
            std::mem::size_of_val(std::slice::from_ref(&layer_norm_params));
        let post_params_bytes = std::mem::size_of_val(std::slice::from_ref(&post_params));
        let density_output_bytes = density_prepared
            .as_ref()
            .map(|(_, output_len, _, _, _, _, _, _, _)| {
                output_len
                    .checked_mul(std::mem::size_of::<f32>())
                    .ok_or_else(|| format!("{name}.density output byte length overflows usize"))
            })
            .transpose()?
            .unwrap_or(0);
        let density_input_params_bytes = density_prepared
            .as_ref()
            .map(|(_, _, params, _, _, _, _, _, _)| {
                std::mem::size_of_val(std::slice::from_ref(params))
            })
            .unwrap_or(0);
        let density_output_params_bytes = density_prepared
            .as_ref()
            .map(|(_, _, _, params, _, _, _, _, _)| {
                std::mem::size_of_val(std::slice::from_ref(params))
            })
            .unwrap_or(0);
        let density_layer_norm_params_bytes = density_prepared
            .as_ref()
            .map(|(_, _, _, _, params, _, _, _, _)| {
                std::mem::size_of_val(std::slice::from_ref(params))
            })
            .unwrap_or(0);
        let density_post_params_bytes = density_prepared
            .as_ref()
            .map(|(_, _, _, _, _, params, _, _, _)| {
                std::mem::size_of_val(std::slice::from_ref(params))
            })
            .unwrap_or(0);
        let density_node_output_bytes = density_node_scatter_prepared
            .as_ref()
            .map(|(output_len, _)| {
                output_len
                    .checked_mul(std::mem::size_of::<f32>())
                    .ok_or_else(|| {
                        format!("{name}.density node output byte length overflows usize")
                    })
            })
            .transpose()?
            .unwrap_or(0);
        let density_node_params_bytes = density_node_scatter_prepared
            .as_ref()
            .map(|(_, params)| std::mem::size_of_val(std::slice::from_ref(params)))
            .unwrap_or(0);

        scratch.input_buffer.ensure_capacity(
            &self.device,
            edge_feat_bytes.max(conv_output_bytes),
            options,
        )?;
        scratch
            .weight_buffer
            .ensure_capacity(&self.device, source_bytes, options)?;
        scratch
            .bias_buffer
            .ensure_capacity(&self.device, target_bytes, options)?;
        scratch
            .output_buffer
            .ensure_capacity(&self.device, edge_aug_bytes, options)?;
        scratch
            .hidden_a_buffer
            .ensure_capacity(&self.device, hidden_bytes, options)?;
        scratch
            .hidden_b_buffer
            .ensure_capacity(&self.device, hidden_bytes, options)?;
        scratch
            .cutoff_buffer
            .ensure_capacity(&self.device, cutoff_bytes, options)?;
        if retain_conv_weight_mlp_inputs {
            scratch
                .dot_buffer
                .ensure_capacity(&self.device, conv_trace_bytes, options)?;
            scratch.node_attr_buffer.ensure_capacity(
                &self.device,
                conv_trace_copy_params_bytes,
                options,
            )?;
        }
        scratch
            .params_buffer
            .ensure_capacity(&self.device, edge_aug_params_bytes, options)?;
        scratch.dense_input_params_buffer.ensure_capacity(
            &self.device,
            dense_params_bytes,
            options,
        )?;
        scratch.dense_hidden_params_buffer.ensure_capacity(
            &self.device,
            dense_params_bytes,
            options,
        )?;
        scratch.dense_output_params_buffer.ensure_capacity(
            &self.device,
            dense_params_bytes,
            options,
        )?;
        scratch.layer_norm_params_buffer.ensure_capacity(
            &self.device,
            layer_norm_params_bytes,
            options,
        )?;
        scratch
            .post_params_buffer
            .ensure_capacity(&self.device, post_params_bytes, options)?;
        if density_prepared.is_some() {
            scratch
                .aux_buffer
                .ensure_capacity(&self.device, density_output_bytes, options)?;
            scratch.aux_params_buffer.ensure_capacity(
                &self.device,
                density_input_params_bytes,
                options,
            )?;
            scratch.add_params_buffer.ensure_capacity(
                &self.device,
                density_output_params_bytes,
                options,
            )?;
            scratch.concat_params_buffer.ensure_capacity(
                &self.device,
                density_layer_norm_params_bytes,
                options,
            )?;
            scratch.block_params_buffer.ensure_capacity(
                &self.device,
                density_post_params_bytes,
                options,
            )?;
        }
        if density_node_scatter_prepared.is_some() {
            scratch.trace_buffer.ensure_capacity(
                &self.device,
                density_node_output_bytes,
                options,
            )?;
            scratch.descriptor_buffer.ensure_capacity(
                &self.device,
                density_node_params_bytes,
                options,
            )?;
        }

        copy_slice_to_buffer(&scratch.input_f32, scratch.input_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.weight_f32, scratch.weight_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.bias_f32, scratch.bias_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.cutoff_f32, scratch.cutoff_buffer.buffer()?);
        copy_slice_to_buffer(
            std::slice::from_ref(&edge_aug_params),
            scratch.params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&dense_input_params),
            scratch.dense_input_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&dense_hidden_params),
            scratch.dense_hidden_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&dense_output_params),
            scratch.dense_output_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&layer_norm_params),
            scratch.layer_norm_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&post_params),
            scratch.post_params_buffer.buffer()?,
        );
        if retain_conv_weight_mlp_inputs {
            copy_slice_to_buffer(&conv_trace_copy_params, scratch.node_attr_buffer.buffer()?);
        }
        if let Some((
            _,
            _,
            density_input_params,
            density_output_params,
            density_layer_norm_params,
            density_post_params,
            _,
            _,
            _,
        )) = density_prepared.as_ref()
        {
            copy_slice_to_buffer(
                std::slice::from_ref(density_input_params),
                scratch.aux_params_buffer.buffer()?,
            );
            copy_slice_to_buffer(
                std::slice::from_ref(density_output_params),
                scratch.add_params_buffer.buffer()?,
            );
            copy_slice_to_buffer(
                std::slice::from_ref(density_layer_norm_params),
                scratch.concat_params_buffer.buffer()?,
            );
            copy_slice_to_buffer(
                std::slice::from_ref(density_post_params),
                scratch.block_params_buffer.buffer()?,
            );
        }
        if let Some((_, params)) = density_node_scatter_prepared.as_ref() {
            copy_slice_to_buffer(
                std::slice::from_ref(params),
                scratch.descriptor_buffer.buffer()?,
            );
        }
        mace_polar_trace_stage(
            "metal.edge_aug_conv_tp_weights_mlp_scatter.edge_mlp_cpu_upload",
            stage_start,
        );
        stage_start = trace_timings.then(Instant::now);

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();

        encoder.set_compute_pipeline_state(&self.edge_aug_pipeline);
        encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&edge_index_buffers.senders_buffer), 0);
        encoder.set_buffer(2, Some(&edge_index_buffers.receivers_buffer), 0);
        encoder.set_buffer(3, Some(scratch.weight_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(scratch.bias_buffer.buffer()?), 0);
        encoder.set_buffer(5, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(6, Some(scratch.params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.edge_aug_pipeline, edge_aug_len)?;

        encoder.set_compute_pipeline_state(&self.torch_linear_pipeline);
        encoder.set_buffer(0, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&linear0_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(&linear0_buffers.bias_buffer), 0);
        encoder.set_buffer(3, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(scratch.dense_input_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.torch_linear_pipeline, hidden_len)?;
        if retain_conv_weight_mlp_inputs {
            encoder.set_compute_pipeline_state(&self.product_segment_copy_pipeline);
            encoder.set_buffer(0, Some(scratch.hidden_a_buffer.buffer()?), 0);
            encoder.set_buffer(1, Some(scratch.dot_buffer.buffer()?), 0);
            encoder.set_buffer(2, Some(scratch.node_attr_buffer.buffer()?), 0);
            self.dispatch_1d(&encoder, &self.product_segment_copy_pipeline, hidden_len)?;
        }

        encoder.set_compute_pipeline_state(&self.layer_norm_silu_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&norm1_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(&norm1_buffers.bias_buffer), 0);
        encoder.set_buffer(3, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(scratch.layer_norm_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.layer_norm_silu_pipeline, edge_count)?;

        encoder.set_compute_pipeline_state(&self.torch_linear_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&linear3_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(&linear3_buffers.bias_buffer), 0);
        encoder.set_buffer(3, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(scratch.dense_hidden_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.torch_linear_pipeline, hidden_len)?;
        if retain_conv_weight_mlp_inputs {
            encoder.set_compute_pipeline_state(&self.product_segment_copy_pipeline);
            encoder.set_buffer(0, Some(scratch.hidden_a_buffer.buffer()?), 0);
            encoder.set_buffer(1, Some(scratch.dot_buffer.buffer()?), 0);
            encoder.set_buffer(
                2,
                Some(scratch.node_attr_buffer.buffer()?),
                conv_trace_copy_param_stride,
            );
            self.dispatch_1d(&encoder, &self.product_segment_copy_pipeline, hidden_len)?;
        }

        encoder.set_compute_pipeline_state(&self.layer_norm_silu_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&norm4_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(&norm4_buffers.bias_buffer), 0);
        encoder.set_buffer(3, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(scratch.layer_norm_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.layer_norm_silu_pipeline, edge_count)?;

        encoder.set_compute_pipeline_state(&self.torch_linear_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&linear6_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(&linear6_buffers.bias_buffer), 0);
        encoder.set_buffer(3, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(scratch.dense_hidden_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.torch_linear_pipeline, hidden_len)?;
        if retain_conv_weight_mlp_inputs {
            encoder.set_compute_pipeline_state(&self.product_segment_copy_pipeline);
            encoder.set_buffer(0, Some(scratch.hidden_a_buffer.buffer()?), 0);
            encoder.set_buffer(1, Some(scratch.dot_buffer.buffer()?), 0);
            encoder.set_buffer(
                2,
                Some(scratch.node_attr_buffer.buffer()?),
                conv_trace_copy_param_stride * 2,
            );
            self.dispatch_1d(&encoder, &self.product_segment_copy_pipeline, hidden_len)?;
        }

        encoder.set_compute_pipeline_state(&self.layer_norm_silu_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&norm7_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(&norm7_buffers.bias_buffer), 0);
        encoder.set_buffer(3, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(scratch.layer_norm_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.layer_norm_silu_pipeline, edge_count)?;

        encoder.set_compute_pipeline_state(&self.torch_linear_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&linear9_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(&linear9_buffers.bias_buffer), 0);
        encoder.set_buffer(3, Some(scratch.input_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(scratch.dense_output_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.torch_linear_pipeline, conv_output_len)?;

        encoder.set_compute_pipeline_state(&self.apply_cutoff_pipeline);
        encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(scratch.cutoff_buffer.buffer()?), 0);
        encoder.set_buffer(2, Some(scratch.post_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.apply_cutoff_pipeline, conv_output_len)?;

        if let Some((
            density_hidden_len,
            density_output_len,
            _,
            _,
            _,
            _,
            density_linear0_buffers,
            density_linear3_buffers,
            density_norm1_buffers,
        )) = density_prepared.as_ref()
        {
            encoder.set_compute_pipeline_state(&self.torch_linear_pipeline);
            encoder.set_buffer(0, Some(scratch.output_buffer.buffer()?), 0);
            encoder.set_buffer(1, Some(&density_linear0_buffers.weight_buffer), 0);
            encoder.set_buffer(2, Some(&density_linear0_buffers.bias_buffer), 0);
            encoder.set_buffer(3, Some(scratch.hidden_a_buffer.buffer()?), 0);
            encoder.set_buffer(4, Some(scratch.aux_params_buffer.buffer()?), 0);
            self.dispatch_1d(&encoder, &self.torch_linear_pipeline, *density_hidden_len)?;

            encoder.set_compute_pipeline_state(&self.layer_norm_silu_pipeline);
            encoder.set_buffer(0, Some(scratch.hidden_a_buffer.buffer()?), 0);
            encoder.set_buffer(1, Some(&density_norm1_buffers.weight_buffer), 0);
            encoder.set_buffer(2, Some(&density_norm1_buffers.bias_buffer), 0);
            encoder.set_buffer(3, Some(scratch.hidden_b_buffer.buffer()?), 0);
            encoder.set_buffer(4, Some(scratch.concat_params_buffer.buffer()?), 0);
            self.dispatch_1d(&encoder, &self.layer_norm_silu_pipeline, edge_count)?;

            encoder.set_compute_pipeline_state(&self.torch_linear_pipeline);
            encoder.set_buffer(0, Some(scratch.hidden_b_buffer.buffer()?), 0);
            encoder.set_buffer(1, Some(&density_linear3_buffers.weight_buffer), 0);
            encoder.set_buffer(2, Some(&density_linear3_buffers.bias_buffer), 0);
            encoder.set_buffer(3, Some(scratch.aux_buffer.buffer()?), 0);
            encoder.set_buffer(4, Some(scratch.add_params_buffer.buffer()?), 0);
            self.dispatch_1d(&encoder, &self.torch_linear_pipeline, *density_output_len)?;

            encoder.set_compute_pipeline_state(&self.density_tanh_square_cutoff_pipeline);
            encoder.set_buffer(0, Some(scratch.aux_buffer.buffer()?), 0);
            encoder.set_buffer(1, Some(scratch.cutoff_buffer.buffer()?), 0);
            encoder.set_buffer(2, Some(scratch.block_params_buffer.buffer()?), 0);
            self.dispatch_1d(
                &encoder,
                &self.density_tanh_square_cutoff_pipeline,
                edge_count,
            )?;

            if let Some((density_node_output_len, _)) = density_node_scatter_prepared.as_ref() {
                encoder.set_compute_pipeline_state(&self.scatter_rows_pipeline);
                encoder.set_buffer(0, Some(scratch.aux_buffer.buffer()?), 0);
                encoder.set_buffer(1, Some(&edge_index_buffers.receiver_offsets_buffer), 0);
                encoder.set_buffer(2, Some(&edge_index_buffers.receiver_edges_buffer), 0);
                encoder.set_buffer(3, Some(scratch.trace_buffer.buffer()?), 0);
                encoder.set_buffer(4, Some(scratch.descriptor_buffer.buffer()?), 0);
                self.dispatch_1d(
                    &encoder,
                    &self.scatter_rows_pipeline,
                    *density_node_output_len,
                )?;
            }
        }

        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }
        mace_polar_trace_stage(
            "metal.edge_aug_conv_tp_weights_mlp_scatter.edge_mlp_command_buffer",
            stage_start,
        );
        stage_start = trace_timings.then(Instant::now);

        let conv_rows_f32_metal = if read_conv_weight_rows {
            Some(self.clone_flat_rows_f32_buffer(
                scratch.input_buffer.buffer()?,
                edge_count,
                conv_output_dim,
                name,
            )?)
        } else {
            None
        };
        if read_edge_aug_rows {
            let edge_aug_ptr = scratch.output_buffer.buffer()?.contents().cast::<f32>();
            copy_ptr_to_slice(edge_aug_ptr, &mut scratch.edge_aug_f32);
        }
        if read_conv_weight_rows {
            let conv_output_ptr = scratch.input_buffer.buffer()?.contents().cast::<f32>();
            copy_ptr_to_slice(conv_output_ptr, &mut scratch.output_f32);
        }
        let density_rows = if let (true, Some((_, output_len, _, _, _, _, _, _, _))) =
            (read_density_rows, density_prepared.as_ref())
        {
            scratch.gate_f32.clear();
            scratch.gate_f32.resize(*output_len, 0.0);
            let density_ptr = scratch.aux_buffer.buffer()?.contents().cast::<f32>();
            copy_ptr_to_slice(density_ptr, &mut scratch.gate_f32);
            Some(
                scratch
                    .gate_f32
                    .iter()
                    .map(|value| vec![f64::from(*value)])
                    .collect(),
            )
        } else {
            None
        };
        let density_node_rows =
            if let Some((density_node_output_len, _)) = density_node_scatter_prepared.as_ref() {
                scratch.trace_f32.clear();
                scratch.trace_f32.resize(*density_node_output_len, 0.0);
                let density_node_ptr = scratch.trace_buffer.buffer()?.contents().cast::<f32>();
                copy_ptr_to_slice(density_node_ptr, &mut scratch.trace_f32);
                Some(
                    scratch
                        .trace_f32
                        .iter()
                        .map(|value| vec![f64::from(*value)])
                        .collect(),
                )
            } else {
                None
            };

        let edge_aug_rows = if read_edge_aug_rows {
            scratch
                .edge_aug_f32
                .chunks_exact(edge_aug_dim)
                .map(|row| row.iter().map(|value| f64::from(*value)).collect())
                .collect()
        } else {
            Vec::new()
        };
        let conv_rows = if read_conv_weight_rows {
            scratch
                .output_f32
                .chunks_exact(conv_output_dim)
                .map(|row| row.iter().map(|value| f64::from(*value)).collect())
                .collect()
        } else {
            Vec::new()
        };
        let retain_conv_rows_f32 = read_conv_weight_rows && edge_count <= 64 * 1024;
        let conv_rows_f32 = if retain_conv_rows_f32 {
            Some(MacePolarFlatRowsF32 {
                values: scratch.output_f32.clone(),
                row_count: edge_count,
                width: conv_output_dim,
            })
        } else {
            None
        };
        let conv_mlp_inputs = if retain_conv_weight_mlp_inputs {
            if scratch.trace_f32.len() != conv_trace_len {
                scratch.trace_f32.resize(conv_trace_len, 0.0);
            }
            let trace_ptr = scratch.dot_buffer.buffer()?.contents().cast::<f32>();
            copy_ptr_to_slice(trace_ptr, &mut scratch.trace_f32);
            let trace_rows = |trace: &[f32], offset: usize| -> MacePolarRows {
                trace
                    .chunks_exact(conv_trace_width)
                    .map(|row| {
                        row[offset..offset + conv_hidden]
                            .iter()
                            .map(|value| f64::from(*value))
                            .collect()
                    })
                    .collect()
            };
            Some(MacePolarConvWeightMlpInputRows {
                z0: trace_rows(&scratch.trace_f32, 0),
                z3: trace_rows(&scratch.trace_f32, conv_hidden),
                z6: trace_rows(&scratch.trace_f32, conv_hidden * 2),
            })
        } else {
            None
        };
        mace_polar_trace_stage(
            "metal.edge_aug_conv_tp_weights_mlp_scatter.edge_mlp_readback_rows",
            stage_start,
        );
        stage_start = trace_timings.then(Instant::now);
        let scatter_rows = if let Some((
            inputs,
            scatter_output_len,
            conv_tp_params,
            table_buffers,
            post_scatter_block,
        )) = conv_tp_prepared
        {
            let (post_scatter_output_len, post_scatter_params, post_scatter_buffers) =
                if let Some((_, output_len, params, buffers)) = post_scatter_block {
                    scratch.gate_f32.clear();
                    scratch.gate_f32.resize(output_len, 0.0);
                    (Some(output_len), Some(params), Some(buffers))
                } else {
                    scratch.gate_f32.clear();
                    (None, None, None)
                };
            flatten_rows_f32_into(
                inputs.linear_up,
                inputs.table.input1_dim,
                &format!("{name}.conv_tp.linear_up"),
                &mut scratch.weight_f32,
            )?;
            flatten_rows_f32_into(
                inputs.edge_attrs,
                inputs.table.input2_dim,
                &format!("{name}.conv_tp.edge_attrs"),
                &mut scratch.bias_f32,
            )?;
            scratch.scatter_f32.clear();
            scratch.scatter_f32.resize(scatter_output_len, 0.0);

            let linear_up_bytes = std::mem::size_of_val(scratch.weight_f32.as_slice());
            let edge_attrs_bytes = std::mem::size_of_val(scratch.bias_f32.as_slice());
            let scatter_output_bytes = std::mem::size_of_val(scratch.scatter_f32.as_slice());
            let conv_tp_params_bytes = std::mem::size_of_val(std::slice::from_ref(&conv_tp_params));
            let post_scatter_output_bytes = std::mem::size_of_val(scratch.gate_f32.as_slice());
            let post_scatter_params_bytes = post_scatter_params
                .as_ref()
                .map(|params| std::mem::size_of_val(std::slice::from_ref(params)))
                .unwrap_or(0);
            scratch
                .weight_buffer
                .ensure_capacity(&self.device, linear_up_bytes, options)?;
            scratch
                .bias_buffer
                .ensure_capacity(&self.device, edge_attrs_bytes, options)?;
            scratch
                .output_buffer
                .ensure_capacity(&self.device, scatter_output_bytes, options)?;
            scratch
                .params_buffer
                .ensure_capacity(&self.device, conv_tp_params_bytes, options)?;
            if post_scatter_output_len.is_some() {
                scratch.hidden_a_buffer.ensure_capacity(
                    &self.device,
                    post_scatter_output_bytes,
                    options,
                )?;
                scratch.dense_input_params_buffer.ensure_capacity(
                    &self.device,
                    post_scatter_params_bytes,
                    options,
                )?;
            }

            copy_slice_to_buffer(&scratch.weight_f32, scratch.weight_buffer.buffer()?);
            copy_slice_to_buffer(&scratch.bias_f32, scratch.bias_buffer.buffer()?);
            copy_slice_to_buffer(
                std::slice::from_ref(&conv_tp_params),
                scratch.params_buffer.buffer()?,
            );
            if let Some(params) = post_scatter_params.as_ref() {
                copy_slice_to_buffer(
                    std::slice::from_ref(params),
                    scratch.dense_input_params_buffer.buffer()?,
                );
            }
            mace_polar_trace_stage(
                "metal.edge_aug_conv_tp_weights_mlp_scatter.conv_tp_linear1_cpu_upload",
                stage_start,
            );
            stage_start = trace_timings.then(Instant::now);

            let command_buffer = self.queue.new_command_buffer();
            let encoder = command_buffer.new_compute_command_encoder();
            let conv_tp_scatter_pipeline = if inputs.table.output_mask_all_one {
                &self.conv_tp_scatter_nomask_pipeline
            } else {
                &self.conv_tp_scatter_pipeline
            };
            encoder.set_compute_pipeline_state(conv_tp_scatter_pipeline);
            encoder.set_buffer(0, Some(scratch.weight_buffer.buffer()?), 0);
            encoder.set_buffer(1, Some(scratch.bias_buffer.buffer()?), 0);
            encoder.set_buffer(2, Some(scratch.input_buffer.buffer()?), 0);
            encoder.set_buffer(3, Some(&edge_index_buffers.receiver_offsets_buffer), 0);
            encoder.set_buffer(4, Some(&edge_index_buffers.receiver_edges_buffer), 0);
            encoder.set_buffer(5, Some(&edge_index_buffers.senders_buffer), 0);
            encoder.set_buffer(6, Some(&table_buffers.lane_offsets_buffer), 0);
            encoder.set_buffer(7, Some(&table_buffers.lane_entries_buffer), 0);
            if inputs.table.output_mask_all_one {
                encoder.set_buffer(8, Some(scratch.output_buffer.buffer()?), 0);
                encoder.set_buffer(9, Some(scratch.params_buffer.buffer()?), 0);
            } else {
                encoder.set_buffer(8, Some(&table_buffers.output_mask_buffer), 0);
                encoder.set_buffer(9, Some(scratch.output_buffer.buffer()?), 0);
                encoder.set_buffer(10, Some(scratch.params_buffer.buffer()?), 0);
            }
            self.dispatch_1d(&encoder, conv_tp_scatter_pipeline, scatter_output_len)?;
            if let (Some(output_len), Some(params), Some(buffers)) = (
                post_scatter_output_len,
                post_scatter_params.as_ref(),
                post_scatter_buffers,
            ) {
                encoder.set_compute_pipeline_state(&self.block_linear_pipeline);
                encoder.set_buffer(0, Some(scratch.output_buffer.buffer()?), 0);
                encoder.set_buffer(1, Some(&buffers.weight_buffer), 0);
                encoder.set_buffer(2, Some(&buffers.bias_buffer), 0);
                encoder.set_buffer(3, Some(&buffers.output_mask_buffer), 0);
                encoder.set_buffer(4, Some(&buffers.instructions_buffer), 0);
                encoder.set_buffer(5, Some(scratch.hidden_a_buffer.buffer()?), 0);
                encoder.set_buffer(6, Some(scratch.dense_input_params_buffer.buffer()?), 0);
                self.dispatch_1d(&encoder, &self.block_linear_pipeline, output_len)?;
                debug_assert_eq!(
                    usize::try_from(params.output_dim).ok(),
                    inputs
                        .post_scatter_block_linear
                        .map(|table| table.output_dim)
                );
            }
            encoder.end_encoding();
            command_buffer.commit();
            command_buffer.wait_until_completed();

            let status = command_buffer.status();
            if status != metal::MTLCommandBufferStatus::Completed {
                return Err(format!("Metal command buffer did not complete: {status:?}"));
            }
            mace_polar_trace_stage(
                "metal.edge_aug_conv_tp_weights_mlp_scatter.conv_tp_linear1_command_buffer",
                stage_start,
            );
            stage_start = trace_timings.then(Instant::now);

            let scatter_ptr = scratch.output_buffer.buffer()?.contents().cast::<f32>();
            copy_ptr_to_slice(scatter_ptr, &mut scratch.scatter_f32);
            let post_scatter_block_linear_rows =
                if let Some(table) = inputs.post_scatter_block_linear {
                    let linear_ptr = scratch.hidden_a_buffer.buffer()?.contents().cast::<f32>();
                    copy_ptr_to_slice(linear_ptr, &mut scratch.gate_f32);
                    Some(
                        scratch
                            .gate_f32
                            .chunks_exact(table.output_dim)
                            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
                            .collect(),
                    )
                } else {
                    None
                };
            let output = Some(ConvTpScatterOutput {
                scatter_rows: scratch
                    .scatter_f32
                    .chunks_exact(inputs.table.output_dim)
                    .map(|row| row.iter().map(|value| f64::from(*value)).collect())
                    .collect(),
                post_scatter_block_linear_rows,
            });
            mace_polar_trace_stage(
                "metal.edge_aug_conv_tp_weights_mlp_scatter.conv_tp_linear1_readback_rows",
                stage_start,
            );
            output
        } else {
            None
        };

        Ok((
            edge_aug_rows,
            conv_rows,
            conv_rows_f32,
            conv_rows_f32_metal,
            conv_mlp_inputs,
            density_rows,
            density_node_rows,
            scatter_rows,
        ))
    }

    fn density_mlp_cutoff_rows_f32_with_static_tables_impl(
        &self,
        edge_aug_rows: &[Vec<f64>],
        cutoffs: &[f64],
        dense_tables: [&DenseLinearStaticTable; 2],
        norm1: &LayerNormStaticTable,
        name: &str,
        retain_intermediates: bool,
    ) -> Result<(MacePolarRows, Option<MacePolarDensityFnMlpInputRows>), String> {
        let row_count = edge_aug_rows.len();
        if row_count == 0 {
            let retained = retain_intermediates.then(|| MacePolarDensityFnMlpInputRows {
                z0: Vec::new(),
                z1: Vec::new(),
                raw: Vec::new(),
            });
            return Ok((Vec::new(), retained));
        }
        if cutoffs.len() != row_count {
            return Err(format!(
                "{name}.cutoffs length mismatch: expected {row_count}, got {}",
                cutoffs.len()
            ));
        }
        let [linear0, linear3] = dense_tables;
        validate_density_mlp_tables(linear0, norm1, linear3)?;

        let hidden = linear0.output_dim;
        let hidden_len = row_count
            .checked_mul(hidden)
            .ok_or_else(|| "density MLP hidden buffer length overflows usize".to_owned())?;
        let output_len = row_count;

        let linear0_buffers = linear0.metal_buffers(&self.device)?;
        let linear3_buffers = linear3.metal_buffers(&self.device)?;
        let norm1_buffers = norm1.metal_buffers(&self.device)?;

        let dense_input_params = PolarTorchLinearParamsMetal {
            row_count: u32::try_from(row_count)
                .map_err(|_| "row count exceeds Metal u32 range".to_owned())?,
            input_dim: u32::try_from(linear0.input_dim)
                .map_err(|_| "density MLP input dim exceeds Metal u32 range".to_owned())?,
            output_dim: u32::try_from(hidden)
                .map_err(|_| "density MLP hidden dim exceeds Metal u32 range".to_owned())?,
        };
        let dense_output_params = PolarTorchLinearParamsMetal {
            row_count: dense_input_params.row_count,
            input_dim: dense_input_params.output_dim,
            output_dim: 1,
        };
        let layer_norm_params = PolarLayerNormSiluParamsMetal {
            row_count: dense_input_params.row_count,
            width: dense_input_params.output_dim,
            eps: norm1.eps_f32,
        };
        let post_params = PolarCutoffRowsParamsMetal {
            row_count: dense_input_params.row_count,
            row_dim: 1,
        };

        let options = MTLResourceOptions::StorageModeShared;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;
        flatten_rows_f32_into(
            edge_aug_rows,
            linear0.input_dim,
            name,
            &mut scratch.input_f32,
        )?;
        f64_to_f32_vec_into(cutoffs, &mut scratch.cutoff_f32);
        scratch.output_f32.clear();
        scratch.output_f32.resize(output_len, 0.0);

        let input_bytes = std::mem::size_of_val(scratch.input_f32.as_slice());
        let hidden_bytes = hidden_len
            .checked_mul(std::mem::size_of::<f32>())
            .ok_or_else(|| "density MLP hidden byte length overflows usize".to_owned())?;
        let output_bytes = std::mem::size_of_val(scratch.output_f32.as_slice());
        let cutoff_bytes = std::mem::size_of_val(scratch.cutoff_f32.as_slice());
        let dense_params_bytes = std::mem::size_of_val(std::slice::from_ref(&dense_input_params));
        let layer_norm_params_bytes =
            std::mem::size_of_val(std::slice::from_ref(&layer_norm_params));
        let post_params_bytes = std::mem::size_of_val(std::slice::from_ref(&post_params));

        scratch
            .input_buffer
            .ensure_capacity(&self.device, input_bytes, options)?;
        scratch
            .hidden_a_buffer
            .ensure_capacity(&self.device, hidden_bytes, options)?;
        scratch
            .hidden_b_buffer
            .ensure_capacity(&self.device, hidden_bytes, options)?;
        scratch
            .output_buffer
            .ensure_capacity(&self.device, output_bytes, options)?;
        if retain_intermediates {
            scratch
                .trace_buffer
                .ensure_capacity(&self.device, hidden_bytes, options)?;
            scratch
                .aux_buffer
                .ensure_capacity(&self.device, output_bytes, options)?;
        }
        scratch
            .cutoff_buffer
            .ensure_capacity(&self.device, cutoff_bytes, options)?;
        scratch.dense_input_params_buffer.ensure_capacity(
            &self.device,
            dense_params_bytes,
            options,
        )?;
        scratch.dense_output_params_buffer.ensure_capacity(
            &self.device,
            dense_params_bytes,
            options,
        )?;
        scratch.layer_norm_params_buffer.ensure_capacity(
            &self.device,
            layer_norm_params_bytes,
            options,
        )?;
        scratch
            .post_params_buffer
            .ensure_capacity(&self.device, post_params_bytes, options)?;

        copy_slice_to_buffer(&scratch.input_f32, scratch.input_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.cutoff_f32, scratch.cutoff_buffer.buffer()?);
        copy_slice_to_buffer(
            std::slice::from_ref(&dense_input_params),
            scratch.dense_input_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&dense_output_params),
            scratch.dense_output_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&layer_norm_params),
            scratch.layer_norm_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&post_params),
            scratch.post_params_buffer.buffer()?,
        );

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();

        encoder.set_compute_pipeline_state(&self.torch_linear_pipeline);
        encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&linear0_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(&linear0_buffers.bias_buffer), 0);
        encoder.set_buffer(3, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(scratch.dense_input_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.torch_linear_pipeline, hidden_len)?;

        if retain_intermediates {
            encoder.set_compute_pipeline_state(&self.layer_norm_silu_pair_pipeline);
            encoder.set_buffer(0, Some(scratch.hidden_a_buffer.buffer()?), 0);
            encoder.set_buffer(1, Some(&norm1_buffers.weight_buffer), 0);
            encoder.set_buffer(2, Some(&norm1_buffers.bias_buffer), 0);
            encoder.set_buffer(3, Some(scratch.trace_buffer.buffer()?), 0);
            encoder.set_buffer(4, Some(scratch.hidden_b_buffer.buffer()?), 0);
            encoder.set_buffer(5, Some(scratch.layer_norm_params_buffer.buffer()?), 0);
            self.dispatch_1d(&encoder, &self.layer_norm_silu_pair_pipeline, row_count)?;
        } else {
            encoder.set_compute_pipeline_state(&self.layer_norm_silu_pipeline);
            encoder.set_buffer(0, Some(scratch.hidden_a_buffer.buffer()?), 0);
            encoder.set_buffer(1, Some(&norm1_buffers.weight_buffer), 0);
            encoder.set_buffer(2, Some(&norm1_buffers.bias_buffer), 0);
            encoder.set_buffer(3, Some(scratch.hidden_b_buffer.buffer()?), 0);
            encoder.set_buffer(4, Some(scratch.layer_norm_params_buffer.buffer()?), 0);
            self.dispatch_1d(&encoder, &self.layer_norm_silu_pipeline, row_count)?;
        }

        encoder.set_compute_pipeline_state(&self.torch_linear_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&linear3_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(&linear3_buffers.bias_buffer), 0);
        encoder.set_buffer(3, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(scratch.dense_output_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.torch_linear_pipeline, output_len)?;

        if retain_intermediates {
            encoder.set_compute_pipeline_state(&self.density_tanh_square_cutoff_out_pipeline);
            encoder.set_buffer(0, Some(scratch.output_buffer.buffer()?), 0);
            encoder.set_buffer(1, Some(scratch.cutoff_buffer.buffer()?), 0);
            encoder.set_buffer(2, Some(scratch.aux_buffer.buffer()?), 0);
            encoder.set_buffer(3, Some(scratch.post_params_buffer.buffer()?), 0);
            self.dispatch_1d(
                &encoder,
                &self.density_tanh_square_cutoff_out_pipeline,
                row_count,
            )?;
        } else {
            encoder.set_compute_pipeline_state(&self.density_tanh_square_cutoff_pipeline);
            encoder.set_buffer(0, Some(scratch.output_buffer.buffer()?), 0);
            encoder.set_buffer(1, Some(scratch.cutoff_buffer.buffer()?), 0);
            encoder.set_buffer(2, Some(scratch.post_params_buffer.buffer()?), 0);
            self.dispatch_1d(
                &encoder,
                &self.density_tanh_square_cutoff_pipeline,
                row_count,
            )?;
        }

        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }

        let output_ptr = if retain_intermediates {
            scratch.aux_buffer.buffer()?.contents().cast::<f32>()
        } else {
            scratch.output_buffer.buffer()?.contents().cast::<f32>()
        };
        copy_ptr_to_slice(output_ptr, &mut scratch.output_f32);

        let output_rows = scratch
            .output_f32
            .iter()
            .map(|value| vec![f64::from(*value)])
            .collect();
        let retained = if retain_intermediates {
            scratch.trace_f32.clear();
            scratch.trace_f32.resize(hidden_len, 0.0);
            let z0_ptr = scratch.hidden_a_buffer.buffer()?.contents().cast::<f32>();
            copy_ptr_to_slice(z0_ptr, &mut scratch.trace_f32);
            let z0 = scratch
                .trace_f32
                .chunks_exact(hidden)
                .map(|row| row.iter().map(|value| f64::from(*value)).collect())
                .collect();

            let z1_ptr = scratch.trace_buffer.buffer()?.contents().cast::<f32>();
            copy_ptr_to_slice(z1_ptr, &mut scratch.trace_f32);
            let z1 = scratch
                .trace_f32
                .chunks_exact(hidden)
                .map(|row| row.iter().map(|value| f64::from(*value)).collect())
                .collect();

            scratch.trace_f32.clear();
            scratch.trace_f32.resize(output_len, 0.0);
            let raw_ptr = scratch.output_buffer.buffer()?.contents().cast::<f32>();
            copy_ptr_to_slice(raw_ptr, &mut scratch.trace_f32);
            let raw = scratch
                .trace_f32
                .iter()
                .map(|value| vec![f64::from(*value)])
                .collect();

            Some(MacePolarDensityFnMlpInputRows { z0, z1, raw })
        } else {
            None
        };

        Ok((output_rows, retained))
    }

    fn density_mlp_cutoff_rows_f32_with_static_tables(
        &self,
        edge_aug_rows: &[Vec<f64>],
        cutoffs: &[f64],
        dense_tables: [&DenseLinearStaticTable; 2],
        norm1: &LayerNormStaticTable,
        name: &str,
    ) -> Result<MacePolarRows, String> {
        self.density_mlp_cutoff_rows_f32_with_static_tables_impl(
            edge_aug_rows,
            cutoffs,
            dense_tables,
            norm1,
            name,
            false,
        )
        .map(|(rows, _)| rows)
    }

    fn density_mlp_cutoff_rows_with_retained_f32_with_static_tables(
        &self,
        edge_aug_rows: &[Vec<f64>],
        cutoffs: &[f64],
        dense_tables: [&DenseLinearStaticTable; 2],
        norm1: &LayerNormStaticTable,
        name: &str,
    ) -> Result<(MacePolarRows, MacePolarDensityFnMlpInputRows), String> {
        let (rows, retained) = self.density_mlp_cutoff_rows_f32_with_static_tables_impl(
            edge_aug_rows,
            cutoffs,
            dense_tables,
            norm1,
            name,
            true,
        )?;
        let retained = retained.ok_or_else(|| {
            format!("{name}.retained density MLP intermediates were not produced")
        })?;
        Ok((rows, retained))
    }

    fn gate_rows_f32_with_static_table(
        &self,
        input_rows: &[Vec<f64>],
        table: &GateStaticTable,
        name: &str,
    ) -> Result<MacePolarRows, String> {
        let row_count = input_rows.len();
        if row_count == 0 {
            return Ok(Vec::new());
        }
        let output_len = row_count
            .checked_mul(table.output_dim)
            .ok_or_else(|| format!("{name} output length overflows usize"))?;
        let params = PolarGateParamsMetal {
            row_count: u32::try_from(row_count)
                .map_err(|_| "gate row count exceeds Metal u32 range".to_owned())?,
            input_dim: u32::try_from(table.input_dim)
                .map_err(|_| "gate input dimension exceeds Metal u32 range".to_owned())?,
            output_dim: u32::try_from(table.output_dim)
                .map_err(|_| "gate output dimension exceeds Metal u32 range".to_owned())?,
        };
        let table_buffers = table.metal_buffers(&self.device)?;

        let options = MTLResourceOptions::StorageModeShared;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;
        flatten_rows_f32_into(input_rows, table.input_dim, name, &mut scratch.input_f32)?;
        scratch.output_f32.clear();
        scratch.output_f32.resize(output_len, 0.0);

        let input_bytes = std::mem::size_of_val(scratch.input_f32.as_slice());
        let output_bytes = std::mem::size_of_val(scratch.output_f32.as_slice());
        let params_bytes = std::mem::size_of_val(std::slice::from_ref(&params));
        scratch
            .input_buffer
            .ensure_capacity(&self.device, input_bytes, options)?;
        scratch
            .output_buffer
            .ensure_capacity(&self.device, output_bytes, options)?;
        scratch
            .params_buffer
            .ensure_capacity(&self.device, params_bytes, options)?;

        copy_slice_to_buffer(&scratch.input_f32, scratch.input_buffer.buffer()?);
        copy_slice_to_buffer(
            std::slice::from_ref(&params),
            scratch.params_buffer.buffer()?,
        );

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();
        encoder.set_compute_pipeline_state(&self.gate_pipeline);
        encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&table_buffers.entries_buffer), 0);
        encoder.set_buffer(2, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(3, Some(scratch.params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.gate_pipeline, output_len)?;
        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }

        let output_ptr = scratch.output_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(output_ptr, &mut scratch.output_f32);
        Ok(scratch
            .output_f32
            .chunks_exact(table.output_dim)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect())
    }

    fn gate_block_linear_rows_f32_with_static_tables(
        &self,
        input_rows: &[Vec<f64>],
        gate_table: &GateStaticTable,
        linear_table: &BlockLinearStaticTable,
        name: &str,
    ) -> Result<(MacePolarRows, MacePolarRows), String> {
        let row_count = input_rows.len();
        if row_count == 0 {
            return Ok((Vec::new(), Vec::new()));
        }
        if linear_table.input_dim != gate_table.output_dim {
            return Err(format!(
                "{name} gate/block-linear dimension mismatch: gate output={} linear input={}",
                gate_table.output_dim, linear_table.input_dim
            ));
        }
        let gate_output_len = row_count
            .checked_mul(gate_table.output_dim)
            .ok_or_else(|| format!("{name} gate output length overflows usize"))?;
        let linear_output_len = row_count
            .checked_mul(linear_table.output_dim)
            .ok_or_else(|| format!("{name} linear output length overflows usize"))?;
        let gate_params = PolarGateParamsMetal {
            row_count: u32::try_from(row_count)
                .map_err(|_| "gate row count exceeds Metal u32 range".to_owned())?,
            input_dim: u32::try_from(gate_table.input_dim)
                .map_err(|_| "gate input dimension exceeds Metal u32 range".to_owned())?,
            output_dim: u32::try_from(gate_table.output_dim)
                .map_err(|_| "gate output dimension exceeds Metal u32 range".to_owned())?,
        };
        let block_params = PolarBlockLinearParamsMetal {
            row_count: gate_params.row_count,
            input_dim: u32::try_from(linear_table.input_dim)
                .map_err(|_| "block-linear input dim exceeds Metal u32 range".to_owned())?,
            output_dim: u32::try_from(linear_table.output_dim)
                .map_err(|_| "block-linear output dim exceeds Metal u32 range".to_owned())?,
            instruction_count: u32::try_from(linear_table.instructions.len())
                .map_err(|_| "block-linear instruction count exceeds Metal u32 range".to_owned())?,
        };
        let gate_buffers = gate_table.metal_buffers(&self.device)?;
        let linear_buffers = linear_table.metal_buffers(&self.device)?;

        let options = MTLResourceOptions::StorageModeShared;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;
        flatten_rows_f32_into(
            input_rows,
            gate_table.input_dim,
            name,
            &mut scratch.input_f32,
        )?;
        scratch.gate_f32.clear();
        scratch.gate_f32.resize(gate_output_len, 0.0);
        scratch.output_f32.clear();
        scratch.output_f32.resize(linear_output_len, 0.0);

        let input_bytes = std::mem::size_of_val(scratch.input_f32.as_slice());
        let gate_output_bytes = std::mem::size_of_val(scratch.gate_f32.as_slice());
        let linear_output_bytes = std::mem::size_of_val(scratch.output_f32.as_slice());
        let gate_params_bytes = std::mem::size_of_val(std::slice::from_ref(&gate_params));
        let block_params_bytes = std::mem::size_of_val(std::slice::from_ref(&block_params));
        scratch
            .input_buffer
            .ensure_capacity(&self.device, input_bytes, options)?;
        scratch
            .output_buffer
            .ensure_capacity(&self.device, gate_output_bytes, options)?;
        scratch
            .hidden_a_buffer
            .ensure_capacity(&self.device, linear_output_bytes, options)?;
        scratch
            .params_buffer
            .ensure_capacity(&self.device, gate_params_bytes, options)?;
        scratch.dense_input_params_buffer.ensure_capacity(
            &self.device,
            block_params_bytes,
            options,
        )?;

        copy_slice_to_buffer(&scratch.input_f32, scratch.input_buffer.buffer()?);
        copy_slice_to_buffer(
            std::slice::from_ref(&gate_params),
            scratch.params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&block_params),
            scratch.dense_input_params_buffer.buffer()?,
        );

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();
        encoder.set_compute_pipeline_state(&self.gate_pipeline);
        encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&gate_buffers.entries_buffer), 0);
        encoder.set_buffer(2, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(3, Some(scratch.params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.gate_pipeline, gate_output_len)?;

        encoder.set_compute_pipeline_state(&self.block_linear_pipeline);
        encoder.set_buffer(0, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&linear_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(&linear_buffers.bias_buffer), 0);
        encoder.set_buffer(3, Some(&linear_buffers.output_mask_buffer), 0);
        encoder.set_buffer(4, Some(&linear_buffers.instructions_buffer), 0);
        encoder.set_buffer(5, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(6, Some(scratch.dense_input_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.block_linear_pipeline, linear_output_len)?;
        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }

        let gate_ptr = scratch.output_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(gate_ptr, &mut scratch.gate_f32);
        let linear_ptr = scratch.hidden_a_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(linear_ptr, &mut scratch.output_f32);

        let gate_rows = scratch
            .gate_f32
            .chunks_exact(gate_table.output_dim)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect();
        let linear_rows = scratch
            .output_f32
            .chunks_exact(linear_table.output_dim)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect();
        Ok((gate_rows, linear_rows))
    }

    fn feature_major_block_linear_gate_rows_vjp_f32_with_static_tables(
        &self,
        feature_major_output_cotangent: &[f64],
        linear_table: &BlockLinearStaticTable,
        gate_table: &GateStaticTable,
        gate_input_rows: &[Vec<f64>],
        name: &str,
    ) -> Result<MacePolarRows, String> {
        const SH_DIM: usize = 16;
        let row_count = gate_input_rows.len();
        if row_count == 0 {
            if feature_major_output_cotangent.is_empty() {
                return Ok(Vec::new());
            }
            return Err(format!(
                "{name} feature-major cotangent must be empty when row count is zero"
            ));
        }
        if linear_table.input_dim != gate_table.output_dim {
            return Err(format!(
                "{name} block-linear/gate dimension mismatch: linear input={} gate output={}",
                linear_table.input_dim, gate_table.output_dim
            ));
        }
        if linear_table.output_dim != gate_table.output_dim {
            return Err(format!(
                "{name} expected square linear_2 table over gate output dim {}, got {}x{}",
                gate_table.output_dim, linear_table.input_dim, linear_table.output_dim
            ));
        }
        if !linear_table.output_dim.is_multiple_of(SH_DIM) {
            return Err(format!(
                "{name} linear output dim {} is not divisible by {SH_DIM}",
                linear_table.output_dim
            ));
        }
        let feature_major_len = row_count
            .checked_mul(linear_table.output_dim)
            .ok_or_else(|| format!("{name} feature-major cotangent length overflows usize"))?;
        if feature_major_output_cotangent.len() != feature_major_len {
            return Err(format!(
                "{name} feature-major cotangent length mismatch: expected {feature_major_len}, got {}",
                feature_major_output_cotangent.len()
            ));
        }
        let gate_output_len = row_count
            .checked_mul(gate_table.output_dim)
            .ok_or_else(|| format!("{name} gate output cotangent length overflows usize"))?;
        let gate_input_len = row_count
            .checked_mul(gate_table.input_dim)
            .ok_or_else(|| format!("{name} gate input cotangent length overflows usize"))?;
        let feature_params = PolarHiddenFeatureMajorParamsMetal {
            row_count: u32::try_from(row_count)
                .map_err(|_| "row count exceeds Metal u32 range".to_owned())?,
            hidden_dim: u32::try_from(linear_table.output_dim / SH_DIM)
                .map_err(|_| "hidden dim exceeds Metal u32 range".to_owned())?,
            row_dim: u32::try_from(linear_table.output_dim)
                .map_err(|_| "row dim exceeds Metal u32 range".to_owned())?,
            sh_dim: SH_DIM as u32,
        };
        let block_params = PolarBlockLinearParamsMetal {
            row_count: feature_params.row_count,
            input_dim: u32::try_from(linear_table.input_dim)
                .map_err(|_| "block-linear input dim exceeds Metal u32 range".to_owned())?,
            output_dim: u32::try_from(linear_table.output_dim)
                .map_err(|_| "block-linear output dim exceeds Metal u32 range".to_owned())?,
            instruction_count: u32::try_from(linear_table.instructions.len())
                .map_err(|_| "block-linear instruction count exceeds Metal u32 range".to_owned())?,
        };
        let gate_params = PolarGateParamsMetal {
            row_count: feature_params.row_count,
            input_dim: u32::try_from(gate_table.input_dim)
                .map_err(|_| "gate input dimension exceeds Metal u32 range".to_owned())?,
            output_dim: u32::try_from(gate_table.output_dim)
                .map_err(|_| "gate output dimension exceeds Metal u32 range".to_owned())?,
        };
        let linear_buffers = linear_table.metal_buffers(&self.device)?;
        let gate_buffers = gate_table.metal_buffers(&self.device)?;

        let options = MTLResourceOptions::StorageModeShared;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;
        scratch.input_f32.clear();
        scratch.input_f32.extend(
            feature_major_output_cotangent
                .iter()
                .map(|value| *value as f32),
        );
        flatten_rows_f32_into(
            gate_input_rows,
            gate_table.input_dim,
            &format!("{name}.gate_input"),
            &mut scratch.edge_aug_f32,
        )?;
        scratch.gate_f32.clear();
        scratch.gate_f32.resize(feature_major_len, 0.0);
        scratch.trace_f32.clear();
        scratch.trace_f32.resize(gate_output_len, 0.0);
        scratch.output_f32.clear();
        scratch.output_f32.resize(gate_input_len, 0.0);

        let feature_major_bytes = std::mem::size_of_val(scratch.input_f32.as_slice());
        let gate_input_bytes = std::mem::size_of_val(scratch.edge_aug_f32.as_slice());
        let reshaped_bytes = std::mem::size_of_val(scratch.gate_f32.as_slice());
        let gate_output_bytes = std::mem::size_of_val(scratch.trace_f32.as_slice());
        let gate_input_cotangent_bytes = std::mem::size_of_val(scratch.output_f32.as_slice());
        let feature_params_bytes = std::mem::size_of_val(std::slice::from_ref(&feature_params));
        let block_params_bytes = std::mem::size_of_val(std::slice::from_ref(&block_params));
        let gate_params_bytes = std::mem::size_of_val(std::slice::from_ref(&gate_params));

        scratch
            .input_buffer
            .ensure_capacity(&self.device, feature_major_bytes, options)?;
        scratch
            .aux_buffer
            .ensure_capacity(&self.device, gate_input_bytes, options)?;
        scratch
            .hidden_a_buffer
            .ensure_capacity(&self.device, reshaped_bytes, options)?;
        scratch
            .hidden_b_buffer
            .ensure_capacity(&self.device, gate_output_bytes, options)?;
        scratch
            .output_buffer
            .ensure_capacity(&self.device, gate_input_cotangent_bytes, options)?;
        scratch
            .params_buffer
            .ensure_capacity(&self.device, feature_params_bytes, options)?;
        scratch.dense_input_params_buffer.ensure_capacity(
            &self.device,
            block_params_bytes,
            options,
        )?;
        scratch
            .post_params_buffer
            .ensure_capacity(&self.device, gate_params_bytes, options)?;

        copy_slice_to_buffer(&scratch.input_f32, scratch.input_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.edge_aug_f32, scratch.aux_buffer.buffer()?);
        copy_slice_to_buffer(
            std::slice::from_ref(&feature_params),
            scratch.params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&block_params),
            scratch.dense_input_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&gate_params),
            scratch.post_params_buffer.buffer()?,
        );

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();
        encoder.set_compute_pipeline_state(&self.hidden_feature_major_to_irrep_vjp_pipeline);
        encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(2, Some(scratch.params_buffer.buffer()?), 0);
        self.dispatch_1d(
            &encoder,
            &self.hidden_feature_major_to_irrep_vjp_pipeline,
            feature_major_len,
        )?;

        encoder.set_compute_pipeline_state(&self.block_linear_vjp_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&linear_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(&linear_buffers.output_mask_buffer), 0);
        encoder.set_buffer(3, Some(&linear_buffers.instructions_buffer), 0);
        encoder.set_buffer(4, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(5, Some(scratch.dense_input_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.block_linear_vjp_pipeline, gate_output_len)?;

        encoder.set_compute_pipeline_state(&self.gate_vjp_pipeline);
        encoder.set_buffer(0, Some(scratch.aux_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(2, Some(&gate_buffers.vjp_offsets_buffer), 0);
        encoder.set_buffer(3, Some(&gate_buffers.vjp_entries_buffer), 0);
        encoder.set_buffer(4, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(5, Some(scratch.post_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.gate_vjp_pipeline, gate_input_len)?;
        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }

        let output_ptr = scratch.output_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(output_ptr, &mut scratch.output_f32);

        Ok(scratch
            .output_f32
            .chunks_exact(gate_table.input_dim)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect())
    }

    #[allow(clippy::too_many_arguments)]
    fn feature_major_gate_density_pair_rows_vjp_f32_with_static_tables(
        &self,
        feature_major_output_cotangent: &[f64],
        linear_2_table: &BlockLinearStaticTable,
        gate_table: &GateStaticTable,
        gate_input_rows: &[Vec<f64>],
        density_rows: &[Vec<f64>],
        denominator_rows: &[Vec<f64>],
        linear_res_table: &BlockLinearStaticTable,
        linear_1_table: &BlockLinearStaticTable,
        name: &str,
    ) -> Result<(MacePolarRows, MacePolarRows, MacePolarRows), String> {
        const SH_DIM: usize = 16;
        let row_count = gate_input_rows.len();
        if row_count == 0 {
            if feature_major_output_cotangent.is_empty()
                && density_rows.is_empty()
                && denominator_rows.is_empty()
            {
                return Ok((Vec::new(), Vec::new(), Vec::new()));
            }
            return Err(format!(
                "{name} inputs must be empty when gate input row count is zero"
            ));
        }
        if density_rows.len() != row_count || denominator_rows.len() != row_count {
            return Err(format!(
                "{name} row count mismatch: gate_input={} density_rows={} denominator={}",
                row_count,
                density_rows.len(),
                denominator_rows.len()
            ));
        }
        if linear_2_table.input_dim != gate_table.output_dim {
            return Err(format!(
                "{name} linear_2/gate dimension mismatch: linear input={} gate output={}",
                linear_2_table.input_dim, gate_table.output_dim
            ));
        }
        if linear_2_table.output_dim != gate_table.output_dim {
            return Err(format!(
                "{name} expected square linear_2 over gate output dim {}, got {}x{}",
                gate_table.output_dim, linear_2_table.input_dim, linear_2_table.output_dim
            ));
        }
        if !linear_2_table.output_dim.is_multiple_of(SH_DIM) {
            return Err(format!(
                "{name} linear_2 output dim {} is not divisible by {SH_DIM}",
                linear_2_table.output_dim
            ));
        }
        let row_dim = gate_table.input_dim;
        if linear_res_table.output_dim != row_dim || linear_1_table.output_dim != row_dim {
            return Err(format!(
                "{name} downstream output dim mismatch: row_dim={row_dim} linear_res={} linear_1={}",
                linear_res_table.output_dim, linear_1_table.output_dim
            ));
        }
        let feature_major_len = row_count
            .checked_mul(linear_2_table.output_dim)
            .ok_or_else(|| format!("{name} feature-major cotangent length overflows usize"))?;
        if feature_major_output_cotangent.len() != feature_major_len {
            return Err(format!(
                "{name} feature-major cotangent length mismatch: expected {feature_major_len}, got {}",
                feature_major_output_cotangent.len()
            ));
        }
        let message_len = row_count
            .checked_mul(row_dim)
            .ok_or_else(|| format!("{name} message cotangent length overflows usize"))?;
        let gate_output_len = row_count
            .checked_mul(gate_table.output_dim)
            .ok_or_else(|| format!("{name} gate output cotangent length overflows usize"))?;
        let linear_up_len = row_count
            .checked_mul(linear_res_table.input_dim)
            .ok_or_else(|| format!("{name} linear_res input cotangent length overflows usize"))?;
        let conv_len = row_count
            .checked_mul(linear_1_table.input_dim)
            .ok_or_else(|| format!("{name} linear_1 input cotangent length overflows usize"))?;
        let feature_params = PolarHiddenFeatureMajorParamsMetal {
            row_count: u32::try_from(row_count)
                .map_err(|_| "row count exceeds Metal u32 range".to_owned())?,
            hidden_dim: u32::try_from(linear_2_table.output_dim / SH_DIM)
                .map_err(|_| "hidden dim exceeds Metal u32 range".to_owned())?,
            row_dim: u32::try_from(linear_2_table.output_dim)
                .map_err(|_| "row dim exceeds Metal u32 range".to_owned())?,
            sh_dim: SH_DIM as u32,
        };
        let linear_2_params = PolarBlockLinearParamsMetal {
            row_count: feature_params.row_count,
            input_dim: u32::try_from(linear_2_table.input_dim)
                .map_err(|_| "linear_2 input dim exceeds Metal u32 range".to_owned())?,
            output_dim: u32::try_from(linear_2_table.output_dim)
                .map_err(|_| "linear_2 output dim exceeds Metal u32 range".to_owned())?,
            instruction_count: u32::try_from(linear_2_table.instructions.len())
                .map_err(|_| "linear_2 instruction count exceeds Metal u32 range".to_owned())?,
        };
        let gate_params = PolarGateParamsMetal {
            row_count: feature_params.row_count,
            input_dim: u32::try_from(gate_table.input_dim)
                .map_err(|_| "gate input dimension exceeds Metal u32 range".to_owned())?,
            output_dim: u32::try_from(gate_table.output_dim)
                .map_err(|_| "gate output dimension exceeds Metal u32 range".to_owned())?,
        };
        let density_params = PolarDensityNormalizeResidualParamsMetal {
            row_count: feature_params.row_count,
            row_dim: gate_params.input_dim,
        };
        let linear_res_params = PolarBlockLinearParamsMetal {
            row_count: feature_params.row_count,
            input_dim: u32::try_from(linear_res_table.input_dim)
                .map_err(|_| "linear_res input dim exceeds Metal u32 range".to_owned())?,
            output_dim: u32::try_from(linear_res_table.output_dim)
                .map_err(|_| "linear_res output dim exceeds Metal u32 range".to_owned())?,
            instruction_count: u32::try_from(linear_res_table.instructions.len())
                .map_err(|_| "linear_res instruction count exceeds Metal u32 range".to_owned())?,
        };
        let linear_1_params = PolarBlockLinearParamsMetal {
            row_count: feature_params.row_count,
            input_dim: u32::try_from(linear_1_table.input_dim)
                .map_err(|_| "linear_1 input dim exceeds Metal u32 range".to_owned())?,
            output_dim: u32::try_from(linear_1_table.output_dim)
                .map_err(|_| "linear_1 output dim exceeds Metal u32 range".to_owned())?,
            instruction_count: u32::try_from(linear_1_table.instructions.len())
                .map_err(|_| "linear_1 instruction count exceeds Metal u32 range".to_owned())?,
        };

        let linear_2_buffers = linear_2_table.metal_buffers(&self.device)?;
        let gate_buffers = gate_table.metal_buffers(&self.device)?;
        let linear_res_buffers = linear_res_table.metal_buffers(&self.device)?;
        let linear_1_buffers = linear_1_table.metal_buffers(&self.device)?;

        let options = MTLResourceOptions::StorageModeShared;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;
        scratch.input_f32.clear();
        scratch.input_f32.extend(
            feature_major_output_cotangent
                .iter()
                .map(|value| *value as f32),
        );
        flatten_rows_f32_into(
            gate_input_rows,
            gate_table.input_dim,
            &format!("{name}.gate_input"),
            &mut scratch.scatter_f32,
        )?;
        flatten_rows_f32_into(
            density_rows,
            row_dim,
            &format!("{name}.density_rows"),
            &mut scratch.weight_f32,
        )?;
        flatten_rows_f32_into(
            denominator_rows,
            1,
            &format!("{name}.denominator"),
            &mut scratch.bias_f32,
        )?;
        scratch.gate_f32.clear();
        scratch.gate_f32.resize(feature_major_len, 0.0);
        scratch.trace_f32.clear();
        scratch.trace_f32.resize(message_len, 0.0);
        scratch.output_mask_f32.clear();
        scratch.output_mask_f32.resize(message_len, 0.0);
        scratch.cutoff_f32.clear();
        scratch.cutoff_f32.resize(row_count, 0.0);
        scratch.output_f32.clear();
        scratch.output_f32.resize(linear_up_len, 0.0);
        scratch.edge_aug_f32.clear();
        scratch.edge_aug_f32.resize(conv_len, 0.0);

        let feature_major_bytes = std::mem::size_of_val(scratch.input_f32.as_slice());
        let gate_input_bytes = std::mem::size_of_val(scratch.scatter_f32.as_slice());
        let density_bytes = std::mem::size_of_val(scratch.weight_f32.as_slice());
        let denominator_bytes = std::mem::size_of_val(scratch.bias_f32.as_slice());
        let reshaped_bytes = std::mem::size_of_val(scratch.gate_f32.as_slice());
        let gate_output_bytes = gate_output_len
            .checked_mul(std::mem::size_of::<f32>())
            .ok_or_else(|| format!("{name} gate output byte length overflows usize"))?;
        let message_bytes = std::mem::size_of_val(scratch.trace_f32.as_slice());
        let linear_1_output_bytes = std::mem::size_of_val(scratch.output_mask_f32.as_slice());
        let denominator_cotangent_bytes = std::mem::size_of_val(scratch.cutoff_f32.as_slice());
        let linear_up_bytes = std::mem::size_of_val(scratch.output_f32.as_slice());
        let conv_bytes = std::mem::size_of_val(scratch.edge_aug_f32.as_slice());
        let feature_params_bytes = std::mem::size_of_val(std::slice::from_ref(&feature_params));
        let linear_2_params_bytes = std::mem::size_of_val(std::slice::from_ref(&linear_2_params));
        let gate_params_bytes = std::mem::size_of_val(std::slice::from_ref(&gate_params));
        let density_params_bytes = std::mem::size_of_val(std::slice::from_ref(&density_params));
        let linear_res_params_bytes =
            std::mem::size_of_val(std::slice::from_ref(&linear_res_params));
        let linear_1_params_bytes = std::mem::size_of_val(std::slice::from_ref(&linear_1_params));

        scratch
            .input_buffer
            .ensure_capacity(&self.device, feature_major_bytes, options)?;
        scratch
            .descriptor_buffer
            .ensure_capacity(&self.device, gate_input_bytes, options)?;
        scratch
            .weight_buffer
            .ensure_capacity(&self.device, density_bytes, options)?;
        scratch
            .bias_buffer
            .ensure_capacity(&self.device, denominator_bytes, options)?;
        scratch
            .hidden_a_buffer
            .ensure_capacity(&self.device, reshaped_bytes, options)?;
        scratch
            .hidden_b_buffer
            .ensure_capacity(&self.device, gate_output_bytes, options)?;
        scratch
            .trace_buffer
            .ensure_capacity(&self.device, message_bytes, options)?;
        scratch
            .output_mask_buffer
            .ensure_capacity(&self.device, linear_1_output_bytes, options)?;
        scratch.cutoff_buffer.ensure_capacity(
            &self.device,
            denominator_cotangent_bytes,
            options,
        )?;
        scratch
            .output_buffer
            .ensure_capacity(&self.device, linear_up_bytes, options)?;
        scratch
            .aux_buffer
            .ensure_capacity(&self.device, conv_bytes, options)?;
        scratch
            .params_buffer
            .ensure_capacity(&self.device, feature_params_bytes, options)?;
        scratch.dense_input_params_buffer.ensure_capacity(
            &self.device,
            linear_2_params_bytes,
            options,
        )?;
        scratch
            .post_params_buffer
            .ensure_capacity(&self.device, gate_params_bytes, options)?;
        scratch.layer_norm_params_buffer.ensure_capacity(
            &self.device,
            density_params_bytes,
            options,
        )?;
        scratch.block_params_buffer.ensure_capacity(
            &self.device,
            linear_res_params_bytes,
            options,
        )?;
        scratch
            .aux_params_buffer
            .ensure_capacity(&self.device, linear_1_params_bytes, options)?;

        copy_slice_to_buffer(&scratch.input_f32, scratch.input_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.scatter_f32, scratch.descriptor_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.weight_f32, scratch.weight_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.bias_f32, scratch.bias_buffer.buffer()?);
        copy_slice_to_buffer(
            std::slice::from_ref(&feature_params),
            scratch.params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&linear_2_params),
            scratch.dense_input_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&gate_params),
            scratch.post_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&density_params),
            scratch.layer_norm_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&linear_res_params),
            scratch.block_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&linear_1_params),
            scratch.aux_params_buffer.buffer()?,
        );

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();
        encoder.set_compute_pipeline_state(&self.hidden_feature_major_to_irrep_vjp_pipeline);
        encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(2, Some(scratch.params_buffer.buffer()?), 0);
        self.dispatch_1d(
            &encoder,
            &self.hidden_feature_major_to_irrep_vjp_pipeline,
            feature_major_len,
        )?;

        encoder.set_compute_pipeline_state(&self.block_linear_vjp_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&linear_2_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(&linear_2_buffers.output_mask_buffer), 0);
        encoder.set_buffer(3, Some(&linear_2_buffers.instructions_buffer), 0);
        encoder.set_buffer(4, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(5, Some(scratch.dense_input_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.block_linear_vjp_pipeline, gate_output_len)?;

        encoder.set_compute_pipeline_state(&self.gate_vjp_pipeline);
        encoder.set_buffer(0, Some(scratch.descriptor_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(2, Some(&gate_buffers.vjp_offsets_buffer), 0);
        encoder.set_buffer(3, Some(&gate_buffers.vjp_entries_buffer), 0);
        encoder.set_buffer(4, Some(scratch.trace_buffer.buffer()?), 0);
        encoder.set_buffer(5, Some(scratch.post_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.gate_vjp_pipeline, message_len)?;

        encoder.set_compute_pipeline_state(&self.density_normalize_vjp_pipeline);
        encoder.set_buffer(0, Some(scratch.trace_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(scratch.bias_buffer.buffer()?), 0);
        encoder.set_buffer(2, Some(scratch.output_mask_buffer.buffer()?), 0);
        encoder.set_buffer(3, Some(scratch.layer_norm_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.density_normalize_vjp_pipeline, message_len)?;

        encoder.set_compute_pipeline_state(&self.density_normalize_denominator_vjp_pipeline);
        encoder.set_buffer(0, Some(scratch.trace_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(scratch.weight_buffer.buffer()?), 0);
        encoder.set_buffer(2, Some(scratch.bias_buffer.buffer()?), 0);
        encoder.set_buffer(3, Some(scratch.cutoff_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(scratch.layer_norm_params_buffer.buffer()?), 0);
        self.dispatch_1d(
            &encoder,
            &self.density_normalize_denominator_vjp_pipeline,
            row_count,
        )?;

        encoder.set_compute_pipeline_state(&self.block_linear_vjp_pipeline);
        encoder.set_buffer(0, Some(scratch.trace_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&linear_res_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(&linear_res_buffers.output_mask_buffer), 0);
        encoder.set_buffer(3, Some(&linear_res_buffers.instructions_buffer), 0);
        encoder.set_buffer(4, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(5, Some(scratch.block_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.block_linear_vjp_pipeline, linear_up_len)?;

        encoder.set_compute_pipeline_state(&self.block_linear_vjp_pipeline);
        encoder.set_buffer(0, Some(scratch.output_mask_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&linear_1_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(&linear_1_buffers.output_mask_buffer), 0);
        encoder.set_buffer(3, Some(&linear_1_buffers.instructions_buffer), 0);
        encoder.set_buffer(4, Some(scratch.aux_buffer.buffer()?), 0);
        encoder.set_buffer(5, Some(scratch.aux_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.block_linear_vjp_pipeline, conv_len)?;
        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }

        let linear_up_ptr = scratch.output_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(linear_up_ptr, &mut scratch.output_f32);
        let conv_ptr = scratch.aux_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(conv_ptr, &mut scratch.edge_aug_f32);
        let denominator_ptr = scratch.cutoff_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(denominator_ptr, &mut scratch.cutoff_f32);

        let linear_up_rows = scratch
            .output_f32
            .chunks_exact(linear_res_table.input_dim)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect();
        let conv_rows = scratch
            .edge_aug_f32
            .chunks_exact(linear_1_table.input_dim)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect();
        let denominator_cotangent = scratch
            .cutoff_f32
            .iter()
            .map(|value| vec![f64::from(*value)])
            .collect();
        Ok((linear_up_rows, conv_rows, denominator_cotangent))
    }

    fn density_gate_block_linear_rows_f32_with_static_tables(
        &self,
        linear_1_rows: &[Vec<f64>],
        linear_res_rows: &[Vec<f64>],
        denominator_rows: &[Vec<f64>],
        gate_table: &GateStaticTable,
        linear_table: &BlockLinearStaticTable,
        name: &str,
    ) -> Result<(MacePolarRows, MacePolarRows, MacePolarRows, MacePolarRows), String> {
        let row_count = linear_1_rows.len();
        if row_count == 0 {
            return Ok((Vec::new(), Vec::new(), Vec::new(), Vec::new()));
        }
        if linear_res_rows.len() != row_count || denominator_rows.len() != row_count {
            return Err(format!(
                "{name} row count mismatch: linear_1={} linear_res={} denominator={}",
                row_count,
                linear_res_rows.len(),
                denominator_rows.len()
            ));
        }
        let row_dim = linear_1_rows
            .first()
            .map(Vec::len)
            .ok_or_else(|| format!("{name}.linear_1 rows must not be empty"))?;
        if row_dim != gate_table.input_dim {
            return Err(format!(
                "{name} row/gate dimension mismatch: row_dim={row_dim} gate input={}",
                gate_table.input_dim
            ));
        }
        if linear_table.input_dim != gate_table.output_dim {
            return Err(format!(
                "{name} gate/block-linear dimension mismatch: gate output={} linear input={}",
                gate_table.output_dim, linear_table.input_dim
            ));
        }
        let residual_len = row_count
            .checked_mul(row_dim)
            .ok_or_else(|| format!("{name} residual length overflows usize"))?;
        let gate_output_len = row_count
            .checked_mul(gate_table.output_dim)
            .ok_or_else(|| format!("{name} gate output length overflows usize"))?;
        let linear_output_len = row_count
            .checked_mul(linear_table.output_dim)
            .ok_or_else(|| format!("{name} linear output length overflows usize"))?;
        let density_params = PolarDensityNormalizeResidualParamsMetal {
            row_count: u32::try_from(row_count)
                .map_err(|_| "density row count exceeds Metal u32 range".to_owned())?,
            row_dim: u32::try_from(row_dim)
                .map_err(|_| "density row dimension exceeds Metal u32 range".to_owned())?,
        };
        let gate_params = PolarGateParamsMetal {
            row_count: density_params.row_count,
            input_dim: density_params.row_dim,
            output_dim: u32::try_from(gate_table.output_dim)
                .map_err(|_| "gate output dimension exceeds Metal u32 range".to_owned())?,
        };
        let block_params = PolarBlockLinearParamsMetal {
            row_count: density_params.row_count,
            input_dim: u32::try_from(linear_table.input_dim)
                .map_err(|_| "block-linear input dim exceeds Metal u32 range".to_owned())?,
            output_dim: u32::try_from(linear_table.output_dim)
                .map_err(|_| "block-linear output dim exceeds Metal u32 range".to_owned())?,
            instruction_count: u32::try_from(linear_table.instructions.len())
                .map_err(|_| "block-linear instruction count exceeds Metal u32 range".to_owned())?,
        };
        let gate_buffers = gate_table.metal_buffers(&self.device)?;
        let linear_buffers = linear_table.metal_buffers(&self.device)?;

        let options = MTLResourceOptions::StorageModeShared;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;
        for (row_index, row) in denominator_rows.iter().enumerate() {
            if row.len() != 1 {
                return Err(format!(
                    "{name}.denominator[{row_index}] expected length 1, got {}",
                    row.len()
                ));
            }
            if row[0] == 0.0 {
                return Err(format!("{name}.denominator[{row_index}] is zero"));
            }
        }
        flatten_rows_f32_into(linear_1_rows, row_dim, name, &mut scratch.input_f32)?;
        flatten_rows_f32_into(
            linear_res_rows,
            row_dim,
            &format!("{name}.linear_res"),
            &mut scratch.weight_f32,
        )?;
        flatten_rows_f32_into(
            denominator_rows,
            1,
            &format!("{name}.denominator"),
            &mut scratch.bias_f32,
        )?;
        scratch.output_f32.clear();
        scratch.output_f32.resize(residual_len, 0.0);
        scratch.gate_f32.clear();
        scratch.gate_f32.resize(gate_output_len, 0.0);
        scratch.scatter_f32.clear();
        scratch.scatter_f32.resize(linear_output_len, 0.0);

        let linear_1_bytes = std::mem::size_of_val(scratch.input_f32.as_slice());
        let linear_res_bytes = std::mem::size_of_val(scratch.weight_f32.as_slice());
        let denominator_bytes = std::mem::size_of_val(scratch.bias_f32.as_slice());
        let residual_bytes = std::mem::size_of_val(scratch.output_f32.as_slice());
        let gate_output_bytes = std::mem::size_of_val(scratch.gate_f32.as_slice());
        let linear_output_bytes = std::mem::size_of_val(scratch.scatter_f32.as_slice());
        let density_params_bytes = std::mem::size_of_val(std::slice::from_ref(&density_params));
        let gate_params_bytes = std::mem::size_of_val(std::slice::from_ref(&gate_params));
        let block_params_bytes = std::mem::size_of_val(std::slice::from_ref(&block_params));
        scratch
            .input_buffer
            .ensure_capacity(&self.device, linear_1_bytes, options)?;
        scratch
            .weight_buffer
            .ensure_capacity(&self.device, linear_res_bytes, options)?;
        scratch
            .bias_buffer
            .ensure_capacity(&self.device, denominator_bytes, options)?;
        scratch
            .hidden_b_buffer
            .ensure_capacity(&self.device, residual_bytes, options)?;
        scratch.hidden_a_buffer.ensure_capacity(
            &self.device,
            residual_bytes.max(linear_output_bytes),
            options,
        )?;
        scratch
            .output_buffer
            .ensure_capacity(&self.device, gate_output_bytes, options)?;
        scratch
            .params_buffer
            .ensure_capacity(&self.device, density_params_bytes, options)?;
        scratch.dense_input_params_buffer.ensure_capacity(
            &self.device,
            gate_params_bytes,
            options,
        )?;
        scratch.dense_output_params_buffer.ensure_capacity(
            &self.device,
            block_params_bytes,
            options,
        )?;

        copy_slice_to_buffer(&scratch.input_f32, scratch.input_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.weight_f32, scratch.weight_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.bias_f32, scratch.bias_buffer.buffer()?);
        copy_slice_to_buffer(
            std::slice::from_ref(&density_params),
            scratch.params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&gate_params),
            scratch.dense_input_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&block_params),
            scratch.dense_output_params_buffer.buffer()?,
        );

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();
        encoder.set_compute_pipeline_state(&self.density_normalize_residual_pipeline);
        encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(scratch.bias_buffer.buffer()?), 0);
        encoder.set_buffer(2, Some(scratch.weight_buffer.buffer()?), 0);
        encoder.set_buffer(3, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(5, Some(scratch.params_buffer.buffer()?), 0);
        self.dispatch_1d(
            &encoder,
            &self.density_normalize_residual_pipeline,
            residual_len,
        )?;

        encoder.set_compute_pipeline_state(&self.gate_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&gate_buffers.entries_buffer), 0);
        encoder.set_buffer(2, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(3, Some(scratch.dense_input_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.gate_pipeline, gate_output_len)?;

        encoder.set_compute_pipeline_state(&self.block_linear_pipeline);
        encoder.set_buffer(0, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&linear_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(&linear_buffers.bias_buffer), 0);
        encoder.set_buffer(3, Some(&linear_buffers.output_mask_buffer), 0);
        encoder.set_buffer(4, Some(&linear_buffers.instructions_buffer), 0);
        encoder.set_buffer(5, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(6, Some(scratch.dense_output_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.block_linear_pipeline, linear_output_len)?;
        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }

        let density_ptr = scratch.hidden_b_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(density_ptr, &mut scratch.output_f32);
        let gate_ptr = scratch.output_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(gate_ptr, &mut scratch.gate_f32);
        let linear_ptr = scratch.hidden_a_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(linear_ptr, &mut scratch.scatter_f32);

        let density_rows = scratch
            .output_f32
            .chunks_exact(row_dim)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect::<MacePolarRows>();
        let residual_rows = linear_1_rows
            .iter()
            .enumerate()
            .map(|(row_index, _)| {
                let start = row_index * row_dim;
                let end = start + row_dim;
                let density_row = &scratch.output_f32[start..end];
                let residual_row = &scratch.weight_f32[start..end];
                density_row
                    .iter()
                    .zip(residual_row)
                    .map(|(density, residual)| f64::from(*density + *residual))
                    .collect()
            })
            .collect::<MacePolarRows>();
        let gate_rows = scratch
            .gate_f32
            .chunks_exact(gate_table.output_dim)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect::<MacePolarRows>();
        let linear_rows = scratch
            .scatter_f32
            .chunks_exact(linear_table.output_dim)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect::<MacePolarRows>();
        Ok((density_rows, residual_rows, gate_rows, linear_rows))
    }

    fn density_linear_res_gate_block_linear_rows_f32_with_static_tables(
        &self,
        linear_1_rows: &[Vec<f64>],
        linear_up_rows: &[Vec<f64>],
        denominator_rows: &[Vec<f64>],
        linear_res_table: &BlockLinearStaticTable,
        gate_table: &GateStaticTable,
        linear_table: &BlockLinearStaticTable,
        name: &str,
    ) -> Result<DensityLinearResGateBlockLinearRows, String> {
        let row_count = linear_1_rows.len();
        if row_count == 0 {
            return Ok(DensityLinearResGateBlockLinearRows {
                linear_res_rows: Vec::new(),
                density_normalized_rows: Vec::new(),
                residual_added_rows: Vec::new(),
                gate_rows: Vec::new(),
                linear_rows: Vec::new(),
            });
        }
        if linear_up_rows.len() != row_count || denominator_rows.len() != row_count {
            return Err(format!(
                "{name} row count mismatch: linear_1={} linear_up={} denominator={}",
                row_count,
                linear_up_rows.len(),
                denominator_rows.len()
            ));
        }
        let row_dim = linear_1_rows
            .first()
            .map(Vec::len)
            .ok_or_else(|| format!("{name}.linear_1 rows must not be empty"))?;
        let linear_up_dim = linear_up_rows
            .first()
            .map(Vec::len)
            .ok_or_else(|| format!("{name}.linear_up rows must not be empty"))?;
        if linear_res_table.input_dim != linear_up_dim {
            return Err(format!(
                "{name} linear_res input mismatch: row_dim={linear_up_dim} table input={}",
                linear_res_table.input_dim
            ));
        }
        if linear_res_table.output_dim != row_dim {
            return Err(format!(
                "{name} linear_res output mismatch: linear_1 row_dim={row_dim} table output={}",
                linear_res_table.output_dim
            ));
        }
        if row_dim != gate_table.input_dim {
            return Err(format!(
                "{name} row/gate dimension mismatch: row_dim={row_dim} gate input={}",
                gate_table.input_dim
            ));
        }
        if linear_table.input_dim != gate_table.output_dim {
            return Err(format!(
                "{name} gate/block-linear dimension mismatch: gate output={} linear input={}",
                gate_table.output_dim, linear_table.input_dim
            ));
        }

        let residual_len = row_count
            .checked_mul(row_dim)
            .ok_or_else(|| format!("{name} residual length overflows usize"))?;
        let linear_up_len = row_count
            .checked_mul(linear_up_dim)
            .ok_or_else(|| format!("{name} linear_up length overflows usize"))?;
        let gate_output_len = row_count
            .checked_mul(gate_table.output_dim)
            .ok_or_else(|| format!("{name} gate output length overflows usize"))?;
        let linear_output_len = row_count
            .checked_mul(linear_table.output_dim)
            .ok_or_else(|| format!("{name} linear output length overflows usize"))?;

        let linear_res_params = PolarBlockLinearParamsMetal {
            row_count: u32::try_from(row_count)
                .map_err(|_| "linear_res row count exceeds Metal u32 range".to_owned())?,
            input_dim: u32::try_from(linear_res_table.input_dim)
                .map_err(|_| "linear_res input dim exceeds Metal u32 range".to_owned())?,
            output_dim: u32::try_from(linear_res_table.output_dim)
                .map_err(|_| "linear_res output dim exceeds Metal u32 range".to_owned())?,
            instruction_count: u32::try_from(linear_res_table.instructions.len())
                .map_err(|_| "linear_res instruction count exceeds Metal u32 range".to_owned())?,
        };
        let density_params = PolarDensityNormalizeResidualParamsMetal {
            row_count: linear_res_params.row_count,
            row_dim: linear_res_params.output_dim,
        };
        let gate_params = PolarGateParamsMetal {
            row_count: density_params.row_count,
            input_dim: density_params.row_dim,
            output_dim: u32::try_from(gate_table.output_dim)
                .map_err(|_| "gate output dimension exceeds Metal u32 range".to_owned())?,
        };
        let block_params = PolarBlockLinearParamsMetal {
            row_count: density_params.row_count,
            input_dim: u32::try_from(linear_table.input_dim)
                .map_err(|_| "block-linear input dim exceeds Metal u32 range".to_owned())?,
            output_dim: u32::try_from(linear_table.output_dim)
                .map_err(|_| "block-linear output dim exceeds Metal u32 range".to_owned())?,
            instruction_count: u32::try_from(linear_table.instructions.len())
                .map_err(|_| "block-linear instruction count exceeds Metal u32 range".to_owned())?,
        };

        let linear_res_buffers = linear_res_table.metal_buffers(&self.device)?;
        let gate_buffers = gate_table.metal_buffers(&self.device)?;
        let linear_buffers = linear_table.metal_buffers(&self.device)?;

        let options = MTLResourceOptions::StorageModeShared;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;
        for (row_index, row) in denominator_rows.iter().enumerate() {
            if row.len() != 1 {
                return Err(format!(
                    "{name}.denominator[{row_index}] expected length 1, got {}",
                    row.len()
                ));
            }
            if row[0] == 0.0 {
                return Err(format!("{name}.denominator[{row_index}] is zero"));
            }
        }
        flatten_rows_f32_into(linear_1_rows, row_dim, name, &mut scratch.input_f32)?;
        flatten_rows_f32_into(
            linear_up_rows,
            linear_up_dim,
            &format!("{name}.linear_up"),
            &mut scratch.weight_f32,
        )?;
        flatten_rows_f32_into(
            denominator_rows,
            1,
            &format!("{name}.denominator"),
            &mut scratch.bias_f32,
        )?;
        scratch.output_f32.clear();
        scratch.output_f32.resize(residual_len, 0.0);
        scratch.gate_f32.clear();
        scratch.gate_f32.resize(gate_output_len, 0.0);
        scratch.scatter_f32.clear();
        scratch.scatter_f32.resize(linear_output_len, 0.0);

        let linear_1_bytes = std::mem::size_of_val(scratch.input_f32.as_slice());
        let linear_up_bytes = linear_up_len
            .checked_mul(std::mem::size_of::<f32>())
            .ok_or_else(|| format!("{name} linear_up byte length overflows usize"))?;
        let denominator_bytes = std::mem::size_of_val(scratch.bias_f32.as_slice());
        let residual_bytes = std::mem::size_of_val(scratch.output_f32.as_slice());
        let gate_output_bytes = std::mem::size_of_val(scratch.gate_f32.as_slice());
        let linear_output_bytes = std::mem::size_of_val(scratch.scatter_f32.as_slice());
        let linear_res_params_bytes =
            std::mem::size_of_val(std::slice::from_ref(&linear_res_params));
        let density_params_bytes = std::mem::size_of_val(std::slice::from_ref(&density_params));
        let gate_params_bytes = std::mem::size_of_val(std::slice::from_ref(&gate_params));
        let block_params_bytes = std::mem::size_of_val(std::slice::from_ref(&block_params));

        scratch
            .input_buffer
            .ensure_capacity(&self.device, linear_1_bytes, options)?;
        scratch
            .weight_buffer
            .ensure_capacity(&self.device, linear_up_bytes, options)?;
        scratch
            .bias_buffer
            .ensure_capacity(&self.device, denominator_bytes, options)?;
        scratch
            .hidden_b_buffer
            .ensure_capacity(&self.device, residual_bytes, options)?;
        scratch.hidden_a_buffer.ensure_capacity(
            &self.device,
            residual_bytes.max(linear_output_bytes),
            options,
        )?;
        scratch
            .output_mask_buffer
            .ensure_capacity(&self.device, residual_bytes, options)?;
        scratch
            .output_buffer
            .ensure_capacity(&self.device, gate_output_bytes, options)?;
        scratch.dense_hidden_params_buffer.ensure_capacity(
            &self.device,
            linear_res_params_bytes,
            options,
        )?;
        scratch
            .params_buffer
            .ensure_capacity(&self.device, density_params_bytes, options)?;
        scratch.dense_input_params_buffer.ensure_capacity(
            &self.device,
            gate_params_bytes,
            options,
        )?;
        scratch.dense_output_params_buffer.ensure_capacity(
            &self.device,
            block_params_bytes,
            options,
        )?;

        copy_slice_to_buffer(&scratch.input_f32, scratch.input_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.weight_f32, scratch.weight_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.bias_f32, scratch.bias_buffer.buffer()?);
        copy_slice_to_buffer(
            std::slice::from_ref(&linear_res_params),
            scratch.dense_hidden_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&density_params),
            scratch.params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&gate_params),
            scratch.dense_input_params_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&block_params),
            scratch.dense_output_params_buffer.buffer()?,
        );

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();

        encoder.set_compute_pipeline_state(&self.block_linear_pipeline);
        encoder.set_buffer(0, Some(scratch.weight_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&linear_res_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(&linear_res_buffers.bias_buffer), 0);
        encoder.set_buffer(3, Some(&linear_res_buffers.output_mask_buffer), 0);
        encoder.set_buffer(4, Some(&linear_res_buffers.instructions_buffer), 0);
        encoder.set_buffer(5, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(6, Some(scratch.dense_hidden_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.block_linear_pipeline, residual_len)?;

        encoder.set_compute_pipeline_state(&self.density_normalize_residual_pipeline);
        encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(scratch.bias_buffer.buffer()?), 0);
        encoder.set_buffer(2, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(3, Some(scratch.output_mask_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(5, Some(scratch.params_buffer.buffer()?), 0);
        self.dispatch_1d(
            &encoder,
            &self.density_normalize_residual_pipeline,
            residual_len,
        )?;

        encoder.set_compute_pipeline_state(&self.gate_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&gate_buffers.entries_buffer), 0);
        encoder.set_buffer(2, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(3, Some(scratch.dense_input_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.gate_pipeline, gate_output_len)?;

        encoder.set_compute_pipeline_state(&self.block_linear_pipeline);
        encoder.set_buffer(0, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&linear_buffers.weight_buffer), 0);
        encoder.set_buffer(2, Some(&linear_buffers.bias_buffer), 0);
        encoder.set_buffer(3, Some(&linear_buffers.output_mask_buffer), 0);
        encoder.set_buffer(4, Some(&linear_buffers.instructions_buffer), 0);
        encoder.set_buffer(5, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(6, Some(scratch.dense_output_params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.block_linear_pipeline, linear_output_len)?;
        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }

        let linear_res_ptr = scratch.hidden_b_buffer.buffer()?.contents().cast::<f32>();
        scratch.weight_f32.clear();
        scratch.weight_f32.resize(residual_len, 0.0);
        copy_ptr_to_slice(linear_res_ptr, &mut scratch.weight_f32);
        let density_ptr = scratch
            .output_mask_buffer
            .buffer()?
            .contents()
            .cast::<f32>();
        copy_ptr_to_slice(density_ptr, &mut scratch.output_f32);
        let gate_ptr = scratch.output_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(gate_ptr, &mut scratch.gate_f32);
        let linear_ptr = scratch.hidden_a_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(linear_ptr, &mut scratch.scatter_f32);

        let linear_res_rows = scratch
            .weight_f32
            .chunks_exact(row_dim)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect::<MacePolarRows>();
        let density_rows = scratch
            .output_f32
            .chunks_exact(row_dim)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect::<MacePolarRows>();
        let residual_rows = scratch
            .output_f32
            .chunks_exact(row_dim)
            .zip(scratch.weight_f32.chunks_exact(row_dim))
            .map(|(density_row, linear_res_row)| {
                density_row
                    .iter()
                    .zip(linear_res_row)
                    .map(|(density, residual)| f64::from(*density + *residual))
                    .collect()
            })
            .collect::<MacePolarRows>();
        let gate_rows = scratch
            .gate_f32
            .chunks_exact(gate_table.output_dim)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect::<MacePolarRows>();
        let linear_rows = scratch
            .scatter_f32
            .chunks_exact(linear_table.output_dim)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect::<MacePolarRows>();
        Ok(DensityLinearResGateBlockLinearRows {
            linear_res_rows,
            density_normalized_rows: density_rows,
            residual_added_rows: residual_rows,
            gate_rows,
            linear_rows,
        })
    }

    fn node_embedding_rows_f32_with_static_table(
        &self,
        atomic_numbers: &[u8],
        table: &NodeEmbeddingStaticTable,
        name: &str,
    ) -> Result<MacePolarRows, String> {
        let node_count = atomic_numbers.len();
        if node_count == 0 {
            return Ok(Vec::new());
        }
        let output_len = node_count
            .checked_mul(table.hidden_dim)
            .ok_or_else(|| "node embedding output length overflows usize".to_owned())?;
        let params = PolarNodeEmbeddingParamsMetal {
            node_count: u32::try_from(node_count)
                .map_err(|_| "node count exceeds Metal u32 range".to_owned())?,
            hidden_dim: u32::try_from(table.hidden_dim)
                .map_err(|_| "hidden dim exceeds Metal u32 range".to_owned())?,
        };

        let table_buffers = table.metal_buffers(&self.device)?;
        let type_id_buffer = self.node_type_id_buffer(atomic_numbers, table.type_count, name)?;

        let options = MTLResourceOptions::StorageModeShared;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;
        scratch.output_f32.clear();
        scratch.output_f32.resize(output_len, 0.0);

        let output_bytes = std::mem::size_of_val(scratch.output_f32.as_slice());
        let params_bytes = std::mem::size_of_val(std::slice::from_ref(&params));
        scratch
            .output_buffer
            .ensure_capacity(&self.device, output_bytes, options)?;
        scratch
            .params_buffer
            .ensure_capacity(&self.device, params_bytes, options)?;

        copy_slice_to_buffer(
            std::slice::from_ref(&params),
            scratch.params_buffer.buffer()?,
        );

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();
        encoder.set_compute_pipeline_state(&self.node_embedding_pipeline);
        encoder.set_buffer(0, Some(&type_id_buffer), 0);
        encoder.set_buffer(1, Some(&table_buffers.embeddings_buffer), 0);
        encoder.set_buffer(2, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(3, Some(scratch.params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.node_embedding_pipeline, output_len)?;
        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }

        let output_ptr = scratch.output_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(output_ptr, &mut scratch.output_f32);

        Ok(scratch
            .output_f32
            .chunks_exact(table.hidden_dim)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect())
    }

    fn radial_cutoff_rows_f32_from_weights(
        &self,
        lengths: &[f64],
        r_max: f64,
        cutoff_p: i32,
        prefactor: f64,
        bessel_weights: &[f64],
    ) -> Result<(Vec<f64>, MacePolarRows), String> {
        let edge_count = lengths.len();
        if edge_count == 0 {
            return Ok((Vec::new(), Vec::new()));
        }
        if bessel_weights.is_empty() {
            return Err("radial cutoff requires nonzero bessel weights".to_owned());
        }
        if cutoff_p < 0 {
            return Err(format!(
                "radial cutoff p must be nonnegative, got {cutoff_p}"
            ));
        }
        let output_len = edge_count
            .checked_mul(bessel_weights.len())
            .ok_or_else(|| "radial edge feature length overflows usize".to_owned())?;
        let params = PolarRadialCutoffParamsMetal {
            edge_count: u32::try_from(edge_count)
                .map_err(|_| "edge count exceeds Metal u32 range".to_owned())?,
            num_bessel: u32::try_from(bessel_weights.len())
                .map_err(|_| "bessel dimension exceeds Metal u32 range".to_owned())?,
            cutoff_p: u32::try_from(cutoff_p)
                .map_err(|_| "cutoff p exceeds Metal u32 range".to_owned())?,
            r_max: r_max as f32,
            prefactor: prefactor as f32,
        };

        let options = MTLResourceOptions::StorageModeShared;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;
        f64_to_f32_vec_into(lengths, &mut scratch.input_f32);
        f64_to_f32_vec_into(bessel_weights, &mut scratch.weight_f32);
        scratch.cutoff_f32.clear();
        scratch.cutoff_f32.resize(edge_count, 0.0);
        scratch.output_f32.clear();
        scratch.output_f32.resize(output_len, 0.0);

        let length_bytes = std::mem::size_of_val(scratch.input_f32.as_slice());
        let weight_bytes = std::mem::size_of_val(scratch.weight_f32.as_slice());
        let cutoff_bytes = std::mem::size_of_val(scratch.cutoff_f32.as_slice());
        let output_bytes = std::mem::size_of_val(scratch.output_f32.as_slice());
        let params_bytes = std::mem::size_of_val(std::slice::from_ref(&params));

        scratch
            .input_buffer
            .ensure_capacity(&self.device, length_bytes, options)?;
        scratch
            .weight_buffer
            .ensure_capacity(&self.device, weight_bytes, options)?;
        scratch
            .cutoff_buffer
            .ensure_capacity(&self.device, cutoff_bytes, options)?;
        scratch
            .output_buffer
            .ensure_capacity(&self.device, output_bytes, options)?;
        scratch
            .params_buffer
            .ensure_capacity(&self.device, params_bytes, options)?;

        copy_slice_to_buffer(&scratch.input_f32, scratch.input_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.weight_f32, scratch.weight_buffer.buffer()?);
        copy_slice_to_buffer(
            std::slice::from_ref(&params),
            scratch.params_buffer.buffer()?,
        );

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();
        encoder.set_compute_pipeline_state(&self.radial_cutoff_pipeline);
        encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(scratch.weight_buffer.buffer()?), 0);
        encoder.set_buffer(2, Some(scratch.cutoff_buffer.buffer()?), 0);
        encoder.set_buffer(3, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(scratch.params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.radial_cutoff_pipeline, output_len)?;
        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }

        let cutoff_ptr = scratch.cutoff_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(cutoff_ptr, &mut scratch.cutoff_f32);
        let output_ptr = scratch.output_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(output_ptr, &mut scratch.output_f32);

        let cutoffs = scratch
            .cutoff_f32
            .iter()
            .map(|value| f64::from(*value))
            .collect();
        let edge_feats = scratch
            .output_f32
            .chunks_exact(bessel_weights.len())
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect();
        Ok((cutoffs, edge_feats))
    }

    fn radial_cutoff_rows_f32_with_static_table(
        &self,
        lengths: &[f64],
        table: &RadialCutoffStaticTable,
    ) -> Result<(Vec<f64>, MacePolarRows), String> {
        let edge_count = lengths.len();
        if edge_count == 0 {
            return Ok((Vec::new(), Vec::new()));
        }
        let output_len = edge_count
            .checked_mul(table.num_bessel)
            .ok_or_else(|| "radial edge feature length overflows usize".to_owned())?;
        let params = table.params(edge_count)?;
        let table_buffers = table.metal_buffers(&self.device)?;

        let options = MTLResourceOptions::StorageModeShared;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;
        f64_to_f32_vec_into(lengths, &mut scratch.input_f32);
        scratch.cutoff_f32.clear();
        scratch.cutoff_f32.resize(edge_count, 0.0);
        scratch.output_f32.clear();
        scratch.output_f32.resize(output_len, 0.0);

        let length_bytes = std::mem::size_of_val(scratch.input_f32.as_slice());
        let cutoff_bytes = std::mem::size_of_val(scratch.cutoff_f32.as_slice());
        let output_bytes = std::mem::size_of_val(scratch.output_f32.as_slice());
        let params_bytes = std::mem::size_of_val(std::slice::from_ref(&params));

        scratch
            .input_buffer
            .ensure_capacity(&self.device, length_bytes, options)?;
        scratch
            .cutoff_buffer
            .ensure_capacity(&self.device, cutoff_bytes, options)?;
        scratch
            .output_buffer
            .ensure_capacity(&self.device, output_bytes, options)?;
        scratch
            .params_buffer
            .ensure_capacity(&self.device, params_bytes, options)?;

        copy_slice_to_buffer(&scratch.input_f32, scratch.input_buffer.buffer()?);
        copy_slice_to_buffer(
            std::slice::from_ref(&params),
            scratch.params_buffer.buffer()?,
        );

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();
        encoder.set_compute_pipeline_state(&self.radial_cutoff_pipeline);
        encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&table_buffers.bessel_weights_buffer), 0);
        encoder.set_buffer(2, Some(scratch.cutoff_buffer.buffer()?), 0);
        encoder.set_buffer(3, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(scratch.params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.radial_cutoff_pipeline, output_len)?;
        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }

        let cutoff_ptr = scratch.cutoff_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(cutoff_ptr, &mut scratch.cutoff_f32);
        let output_ptr = scratch.output_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(output_ptr, &mut scratch.output_f32);

        let cutoffs = scratch
            .cutoff_f32
            .iter()
            .map(|value| f64::from(*value))
            .collect();
        let edge_feats = scratch
            .output_f32
            .chunks_exact(table.num_bessel)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect();
        Ok((cutoffs, edge_feats))
    }

    fn edge_aug_rows_f32(
        &self,
        edge_feats: &[Vec<f64>],
        edge_index: &[[usize; 2]],
        source_embedding: &[Vec<f64>],
        target_embedding: &[Vec<f64>],
        edge_feat_dim: usize,
        hidden_dim: usize,
        name: &str,
    ) -> Result<MacePolarRows, String> {
        let edge_count = edge_index.len();
        if edge_count == 0 {
            return Ok(Vec::new());
        }
        if edge_feats.len() != edge_count {
            return Err(format!(
                "{name}.edge_feats length mismatch: expected {edge_count}, got {}",
                edge_feats.len()
            ));
        }
        if source_embedding.len() != target_embedding.len() {
            return Err(format!(
                "{name}.source/target embedding row count mismatch: source={} target={}",
                source_embedding.len(),
                target_embedding.len()
            ));
        }
        let node_count = source_embedding.len();
        let output_dim = edge_feat_dim
            .checked_add(hidden_dim.checked_mul(2).ok_or_else(|| {
                format!("{name}.edge_aug hidden output dimension overflows usize")
            })?)
            .ok_or_else(|| format!("{name}.edge_aug output dimension overflows usize"))?;
        let output_len = edge_count
            .checked_mul(output_dim)
            .ok_or_else(|| format!("{name}.edge_aug output length overflows usize"))?;
        let params = PolarEdgeAugParamsMetal {
            edge_count: u32::try_from(edge_count)
                .map_err(|_| "edge count exceeds Metal u32 range".to_owned())?,
            edge_feat_dim: u32::try_from(edge_feat_dim)
                .map_err(|_| "edge feature dimension exceeds Metal u32 range".to_owned())?,
            hidden_dim: u32::try_from(hidden_dim)
                .map_err(|_| "hidden dimension exceeds Metal u32 range".to_owned())?,
            output_dim: u32::try_from(output_dim)
                .map_err(|_| "output dimension exceeds Metal u32 range".to_owned())?,
        };
        let edge_index_buffers = self.edge_index_buffers(edge_index, node_count, name)?;

        let options = MTLResourceOptions::StorageModeShared;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;
        flatten_rows_f32_into(edge_feats, edge_feat_dim, name, &mut scratch.input_f32)?;
        flatten_rows_f32_into(
            source_embedding,
            hidden_dim,
            &format!("{name}.source_embedding"),
            &mut scratch.weight_f32,
        )?;
        flatten_rows_f32_into(
            target_embedding,
            hidden_dim,
            &format!("{name}.target_embedding"),
            &mut scratch.bias_f32,
        )?;
        scratch.output_f32.clear();
        scratch.output_f32.resize(output_len, 0.0);

        let edge_feat_bytes = std::mem::size_of_val(scratch.input_f32.as_slice());
        let source_bytes = std::mem::size_of_val(scratch.weight_f32.as_slice());
        let target_bytes = std::mem::size_of_val(scratch.bias_f32.as_slice());
        let output_bytes = std::mem::size_of_val(scratch.output_f32.as_slice());
        let params_bytes = std::mem::size_of_val(std::slice::from_ref(&params));

        scratch
            .input_buffer
            .ensure_capacity(&self.device, edge_feat_bytes, options)?;
        scratch
            .weight_buffer
            .ensure_capacity(&self.device, source_bytes, options)?;
        scratch
            .bias_buffer
            .ensure_capacity(&self.device, target_bytes, options)?;
        scratch
            .output_buffer
            .ensure_capacity(&self.device, output_bytes, options)?;
        scratch
            .params_buffer
            .ensure_capacity(&self.device, params_bytes, options)?;

        copy_slice_to_buffer(&scratch.input_f32, scratch.input_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.weight_f32, scratch.weight_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.bias_f32, scratch.bias_buffer.buffer()?);
        copy_slice_to_buffer(
            std::slice::from_ref(&params),
            scratch.params_buffer.buffer()?,
        );

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();
        encoder.set_compute_pipeline_state(&self.edge_aug_pipeline);
        encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&edge_index_buffers.senders_buffer), 0);
        encoder.set_buffer(2, Some(&edge_index_buffers.receivers_buffer), 0);
        encoder.set_buffer(3, Some(scratch.weight_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(scratch.bias_buffer.buffer()?), 0);
        encoder.set_buffer(5, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(6, Some(scratch.params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.edge_aug_pipeline, output_len)?;
        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }

        let output_ptr = scratch.output_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(output_ptr, &mut scratch.output_f32);

        Ok(scratch
            .output_f32
            .chunks_exact(output_dim)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect())
    }

    fn scatter_rows_to_targets_f32(
        &self,
        edge_index: &[[usize; 2]],
        edge_rows: &[Vec<f64>],
        node_count: usize,
        row_dim: usize,
        name: &str,
    ) -> Result<MacePolarRows, String> {
        let edge_count = edge_index.len();
        if edge_rows.len() != edge_count {
            return Err(format!(
                "{name}.edge_rows length mismatch: expected {edge_count}, got {}",
                edge_rows.len()
            ));
        }
        if node_count == 0 {
            return Ok(Vec::new());
        }
        if row_dim == 0 {
            return Err(format!("{name}.row_dim must be nonzero"));
        }
        let output_len = node_count
            .checked_mul(row_dim)
            .ok_or_else(|| format!("{name} scatter output length overflows usize"))?;
        if edge_count == 0 {
            return Ok(vec![vec![0.0_f64; row_dim]; node_count]);
        }
        let params = PolarScatterRowsParamsMetal {
            node_count: u32::try_from(node_count)
                .map_err(|_| "node count exceeds Metal u32 range".to_owned())?,
            edge_count: u32::try_from(edge_count)
                .map_err(|_| "edge count exceeds Metal u32 range".to_owned())?,
            row_dim: u32::try_from(row_dim)
                .map_err(|_| "scatter row dimension exceeds Metal u32 range".to_owned())?,
        };
        let edge_index_buffers = self.edge_index_buffers(edge_index, node_count, name)?;

        let options = MTLResourceOptions::StorageModeShared;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;
        flatten_rows_f32_into(edge_rows, row_dim, name, &mut scratch.input_f32)?;
        scratch.output_f32.clear();
        scratch.output_f32.resize(output_len, 0.0);

        let input_bytes = std::mem::size_of_val(scratch.input_f32.as_slice());
        let output_bytes = std::mem::size_of_val(scratch.output_f32.as_slice());
        let params_bytes = std::mem::size_of_val(std::slice::from_ref(&params));

        scratch
            .input_buffer
            .ensure_capacity(&self.device, input_bytes, options)?;
        scratch
            .output_buffer
            .ensure_capacity(&self.device, output_bytes, options)?;
        scratch
            .params_buffer
            .ensure_capacity(&self.device, params_bytes, options)?;

        copy_slice_to_buffer(&scratch.input_f32, scratch.input_buffer.buffer()?);
        copy_slice_to_buffer(
            std::slice::from_ref(&params),
            scratch.params_buffer.buffer()?,
        );

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();
        encoder.set_compute_pipeline_state(&self.scatter_rows_pipeline);
        encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&edge_index_buffers.receiver_offsets_buffer), 0);
        encoder.set_buffer(2, Some(&edge_index_buffers.receiver_edges_buffer), 0);
        encoder.set_buffer(3, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(scratch.params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.scatter_rows_pipeline, output_len)?;
        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }

        let output_ptr = scratch.output_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(output_ptr, &mut scratch.output_f32);

        Ok(scratch
            .output_f32
            .chunks_exact(row_dim)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect())
    }

    #[allow(clippy::too_many_arguments)]
    fn conv_tp_scatter_rows_f32_with_static_table(
        &self,
        edge_index: &[[usize; 2]],
        linear_up: &[Vec<f64>],
        edge_attrs: &[Vec<f64>],
        weights: &[Vec<f64>],
        node_count: usize,
        table: &ConvTpStaticTable,
        name: &str,
    ) -> Result<MacePolarRows, String> {
        let edge_count = edge_index.len();
        if node_count == 0 {
            return Ok(Vec::new());
        }
        if linear_up.len() != node_count {
            return Err(format!(
                "{name}.linear_up row count mismatch: expected {node_count}, got {}",
                linear_up.len()
            ));
        }
        if edge_attrs.len() != edge_count {
            return Err(format!(
                "{name}.edge_attrs row count mismatch: expected {edge_count}, got {}",
                edge_attrs.len()
            ));
        }
        if weights.len() != edge_count {
            return Err(format!(
                "{name}.weights row count mismatch: expected {edge_count}, got {}",
                weights.len()
            ));
        }
        let output_len = node_count
            .checked_mul(table.output_dim)
            .ok_or_else(|| format!("{name} conv-TP output length overflows usize"))?;
        let params = table.params(node_count, edge_count)?;
        let table_buffers = table.metal_buffers(&self.device)?;
        let edge_index_buffers = self.edge_index_buffers(edge_index, node_count, name)?;

        let options = MTLResourceOptions::StorageModeShared;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;
        flatten_rows_f32_into(
            linear_up,
            table.input1_dim,
            &format!("{name}.linear_up"),
            &mut scratch.input_f32,
        )?;
        flatten_rows_f32_into(
            edge_attrs,
            table.input2_dim,
            &format!("{name}.edge_attrs"),
            &mut scratch.weight_f32,
        )?;
        flatten_rows_f32_into(
            weights,
            table.weight_dim,
            &format!("{name}.weights"),
            &mut scratch.bias_f32,
        )?;
        scratch.output_f32.clear();
        scratch.output_f32.resize(output_len, 0.0);

        let linear_up_bytes = std::mem::size_of_val(scratch.input_f32.as_slice());
        let edge_attrs_bytes = std::mem::size_of_val(scratch.weight_f32.as_slice());
        let weights_bytes = std::mem::size_of_val(scratch.bias_f32.as_slice());
        let output_bytes = std::mem::size_of_val(scratch.output_f32.as_slice());
        let params_bytes = std::mem::size_of_val(std::slice::from_ref(&params));

        scratch
            .input_buffer
            .ensure_capacity(&self.device, linear_up_bytes, options)?;
        scratch
            .weight_buffer
            .ensure_capacity(&self.device, edge_attrs_bytes, options)?;
        scratch
            .bias_buffer
            .ensure_capacity(&self.device, weights_bytes, options)?;
        scratch
            .output_buffer
            .ensure_capacity(&self.device, output_bytes, options)?;
        scratch
            .params_buffer
            .ensure_capacity(&self.device, params_bytes, options)?;

        copy_slice_to_buffer(&scratch.input_f32, scratch.input_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.weight_f32, scratch.weight_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.bias_f32, scratch.bias_buffer.buffer()?);
        copy_slice_to_buffer(
            std::slice::from_ref(&params),
            scratch.params_buffer.buffer()?,
        );

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();
        let conv_tp_scatter_pipeline = if table.output_mask_all_one {
            &self.conv_tp_scatter_nomask_pipeline
        } else {
            &self.conv_tp_scatter_pipeline
        };
        encoder.set_compute_pipeline_state(conv_tp_scatter_pipeline);
        encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(scratch.weight_buffer.buffer()?), 0);
        encoder.set_buffer(2, Some(scratch.bias_buffer.buffer()?), 0);
        encoder.set_buffer(3, Some(&edge_index_buffers.receiver_offsets_buffer), 0);
        encoder.set_buffer(4, Some(&edge_index_buffers.receiver_edges_buffer), 0);
        encoder.set_buffer(5, Some(&edge_index_buffers.senders_buffer), 0);
        encoder.set_buffer(6, Some(&table_buffers.lane_offsets_buffer), 0);
        encoder.set_buffer(7, Some(&table_buffers.lane_entries_buffer), 0);
        if table.output_mask_all_one {
            encoder.set_buffer(8, Some(scratch.output_buffer.buffer()?), 0);
            encoder.set_buffer(9, Some(scratch.params_buffer.buffer()?), 0);
        } else {
            encoder.set_buffer(8, Some(&table_buffers.output_mask_buffer), 0);
            encoder.set_buffer(9, Some(scratch.output_buffer.buffer()?), 0);
            encoder.set_buffer(10, Some(scratch.params_buffer.buffer()?), 0);
        }
        self.dispatch_1d(&encoder, conv_tp_scatter_pipeline, output_len)?;
        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }

        let output_ptr = scratch.output_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(output_ptr, &mut scratch.output_f32);

        Ok(scratch
            .output_f32
            .chunks_exact(table.output_dim)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect())
    }

    #[allow(clippy::too_many_arguments)]
    fn realspace_descriptor_pair_vjp_f32(
        &self,
        first_output_cotangent: &[Vec<f64>],
        first_source_rows: &[Vec<f64>],
        first_source_start: usize,
        second_output_cotangent: &[Vec<f64>],
        second_source_rows: &[Vec<f64>],
        second_source_start: usize,
        edge_index: &[[usize; 2]],
        smooth_by_edge_radial_f32: &[f32],
        smooth_derivative_by_edge_radial_f32: &[f32],
        vectors_sender_minus_receiver_f32: &[f32],
        distances_f32: &[f32],
        geometry_cache_key: Option<u64>,
        num_radial: usize,
        l0_factors: &[f64],
        l1_factors: &[f64],
        offset: f64,
        field_factor: f64,
        name: &str,
    ) -> Result<(MacePolarRows, MacePolarRows, Vec<[f64; 3]>), String> {
        let node_count = first_source_rows.len();
        if node_count == 0 {
            return Ok((Vec::new(), Vec::new(), Vec::new()));
        }
        require_usize_string(
            &format!("{name}.second_source_rows.len"),
            second_source_rows.len(),
            node_count,
        )?;
        require_usize_string(
            &format!("{name}.first_output_cotangent.len"),
            first_output_cotangent.len(),
            node_count,
        )?;
        require_usize_string(
            &format!("{name}.second_output_cotangent.len"),
            second_output_cotangent.len(),
            node_count,
        )?;
        if num_radial == 0 {
            return Err(format!("{name}.num_radial must be positive"));
        }
        let output_dim = num_radial
            .checked_mul(4)
            .ok_or_else(|| format!("{name}.output_dim overflows usize"))?;
        require_usize_string(
            &format!("{name}.l0_factors.len"),
            l0_factors.len(),
            num_radial,
        )?;
        require_usize_string(
            &format!("{name}.l1_factors.len"),
            l1_factors.len(),
            num_radial,
        )?;
        let first_source_width = first_source_rows
            .first()
            .map(Vec::len)
            .ok_or_else(|| format!("{name}.first_source_rows expected at least one row"))?;
        let second_source_width = second_source_rows
            .first()
            .map(Vec::len)
            .ok_or_else(|| format!("{name}.second_source_rows expected at least one row"))?;
        require_usize_string(
            &format!("{name}.second_source_width"),
            second_source_width,
            first_source_width,
        )?;
        let first_source_end = first_source_start
            .checked_add(4)
            .ok_or_else(|| format!("{name}.first source slice overflows usize"))?;
        let second_source_end = second_source_start
            .checked_add(4)
            .ok_or_else(|| format!("{name}.second source slice overflows usize"))?;
        if first_source_end > first_source_width || second_source_end > first_source_width {
            return Err(format!(
                "{name}.source slices exceed source width {first_source_width}: first_end={first_source_end} second_end={second_source_end}"
            ));
        }
        if !offset.is_finite() || offset == 0.0 {
            return Err(format!("{name}.offset must be finite and non-zero"));
        }
        if !field_factor.is_finite() {
            return Err(format!("{name}.field_factor must be finite"));
        }
        let extended_count = node_count
            .checked_mul(4)
            .ok_or_else(|| format!("{name}.extended count overflows usize"))?;
        let expected_smooth_len = edge_index
            .len()
            .checked_mul(num_radial)
            .ok_or_else(|| format!("{name}.smooth length overflows usize"))?;
        require_usize_string(
            &format!("{name}.smooth_by_edge_radial.len"),
            smooth_by_edge_radial_f32.len(),
            expected_smooth_len,
        )?;
        require_usize_string(
            &format!("{name}.smooth_derivative_by_edge_radial.len"),
            smooth_derivative_by_edge_radial_f32.len(),
            expected_smooth_len,
        )?;
        require_usize_string(
            &format!("{name}.vectors_sender_minus_receiver.len"),
            vectors_sender_minus_receiver_f32.len(),
            edge_index.len().saturating_mul(3),
        )?;
        require_usize_string(
            &format!("{name}.distances.len"),
            distances_f32.len(),
            edge_index.len(),
        )?;

        let node_count_u32 = u32::try_from(node_count)
            .map_err(|_| format!("{name}.node_count exceeds Metal u32 range"))?;
        let extended_count_u32 = u32::try_from(extended_count)
            .map_err(|_| format!("{name}.extended_count exceeds Metal u32 range"))?;
        let edge_count_u32 = u32::try_from(edge_index.len())
            .map_err(|_| format!("{name}.edge_count exceeds Metal u32 range"))?;
        let num_radial_u32 = u32::try_from(num_radial)
            .map_err(|_| format!("{name}.num_radial exceeds Metal u32 range"))?;
        let compact_source_width = 4_usize;
        let compact_source_width_u32 = u32::try_from(compact_source_width)
            .map_err(|_| format!("{name}.source_width exceeds Metal u32 range"))?;
        let params = PolarRealspaceDescriptorPairParamsMetal {
            node_count: node_count_u32,
            extended_count: extended_count_u32,
            edge_count: edge_count_u32,
            num_radial: num_radial_u32,
            source_width: compact_source_width_u32,
            first_source_start: 0,
            second_source_start: 0,
            offset: offset as f32,
            field_factor: field_factor as f32,
        };

        let edge_buffers = self.edge_index_buffers_with_cache_key(
            edge_index,
            extended_count,
            geometry_cache_key,
            name,
        )?;
        let smooth_buffer = self.realspace_descriptor_smooth_buffer(
            edge_index,
            smooth_by_edge_radial_f32,
            geometry_cache_key,
            num_radial,
            name,
        )?;
        let (smooth_derivative_buffer, vectors_buffer, distances_buffer) = self
            .realspace_descriptor_vjp_geometry_buffers(
                edge_index,
                smooth_derivative_by_edge_radial_f32,
                vectors_sender_minus_receiver_f32,
                distances_f32,
                geometry_cache_key,
                num_radial,
                name,
            )?;

        let trace_timings = mace_polar_trace_timings_enabled();
        let mut stage_start = trace_timings.then(Instant::now);
        let options = MTLResourceOptions::StorageModeShared;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;
        flatten_row_slices_f32_into(
            first_source_rows,
            first_source_start,
            compact_source_width,
            &format!("{name}.first_source"),
            &mut scratch.input_f32,
        )?;
        flatten_row_slices_f32_into(
            second_source_rows,
            second_source_start,
            compact_source_width,
            &format!("{name}.second_source"),
            &mut scratch.weight_f32,
        )?;
        flatten_rows_f32_into(
            first_output_cotangent,
            output_dim,
            &format!("{name}.first_output_cotangent"),
            &mut scratch.output_f32,
        )?;
        flatten_rows_f32_into(
            second_output_cotangent,
            output_dim,
            &format!("{name}.second_output_cotangent"),
            &mut scratch.edge_aug_f32,
        )?;
        f64_to_f32_vec_into(l0_factors, &mut scratch.bias_f32);
        f64_to_f32_vec_into(l1_factors, &mut scratch.output_mask_f32);
        scratch.scatter_f32.clear();
        scratch.scatter_f32.resize(extended_count, 0.0);
        scratch.gate_f32.clear();
        scratch.gate_f32.resize(extended_count, 0.0);
        scratch.cutoff_f32.clear();
        scratch.cutoff_f32.resize(extended_count * 3, 0.0);
        scratch.trace_f32.clear();
        scratch.trace_f32.resize(node_count * 4, 0.0);
        scratch.aux_f32.clear();
        scratch.aux_f32.resize(node_count * 4, 0.0);
        scratch.descriptor_f32.clear();
        scratch.descriptor_f32.resize(node_count * 3, 0.0);

        let first_source_bytes = std::mem::size_of_val(scratch.input_f32.as_slice());
        let second_source_bytes = std::mem::size_of_val(scratch.weight_f32.as_slice());
        let first_output_bytes = std::mem::size_of_val(scratch.output_f32.as_slice());
        let second_output_bytes = std::mem::size_of_val(scratch.edge_aug_f32.as_slice());
        let l0_bytes = std::mem::size_of_val(scratch.bias_f32.as_slice());
        let l1_bytes = std::mem::size_of_val(scratch.output_mask_f32.as_slice());
        let extended_charge_bytes = extended_count
            .checked_mul(std::mem::size_of::<f32>())
            .ok_or_else(|| format!("{name}.extended charge bytes overflow usize"))?;
        let extended_position_bytes = extended_count
            .checked_mul(3)
            .and_then(|len| len.checked_mul(std::mem::size_of::<f32>()))
            .ok_or_else(|| format!("{name}.extended position bytes overflow usize"))?;
        let source_output_bytes = node_count
            .checked_mul(4)
            .and_then(|len| len.checked_mul(std::mem::size_of::<f32>()))
            .ok_or_else(|| format!("{name}.source output bytes overflow usize"))?;
        let position_output_bytes = node_count
            .checked_mul(3)
            .and_then(|len| len.checked_mul(std::mem::size_of::<f32>()))
            .ok_or_else(|| format!("{name}.position output bytes overflow usize"))?;
        let params_bytes = std::mem::size_of_val(std::slice::from_ref(&params));

        scratch
            .input_buffer
            .ensure_capacity(&self.device, first_source_bytes, options)?;
        scratch
            .weight_buffer
            .ensure_capacity(&self.device, second_source_bytes, options)?;
        scratch
            .output_buffer
            .ensure_capacity(&self.device, first_output_bytes, options)?;
        scratch
            .hidden_b_buffer
            .ensure_capacity(&self.device, second_output_bytes, options)?;
        scratch
            .bias_buffer
            .ensure_capacity(&self.device, l0_bytes, options)?;
        scratch
            .output_mask_buffer
            .ensure_capacity(&self.device, l1_bytes, options)?;
        scratch
            .hidden_a_buffer
            .ensure_capacity(&self.device, extended_charge_bytes, options)?;
        scratch
            .gate_mask_buffer
            .ensure_capacity(&self.device, extended_charge_bytes, options)?;
        scratch
            .cutoff_buffer
            .ensure_capacity(&self.device, extended_position_bytes, options)?;
        scratch
            .trace_buffer
            .ensure_capacity(&self.device, source_output_bytes, options)?;
        scratch
            .aux_buffer
            .ensure_capacity(&self.device, source_output_bytes, options)?;
        scratch
            .descriptor_buffer
            .ensure_capacity(&self.device, position_output_bytes, options)?;
        scratch
            .params_buffer
            .ensure_capacity(&self.device, params_bytes, options)?;

        copy_slice_to_buffer(&scratch.input_f32, scratch.input_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.weight_f32, scratch.weight_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.output_f32, scratch.output_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.edge_aug_f32, scratch.hidden_b_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.bias_f32, scratch.bias_buffer.buffer()?);
        copy_slice_to_buffer(
            &scratch.output_mask_f32,
            scratch.output_mask_buffer.buffer()?,
        );
        copy_slice_to_buffer(
            std::slice::from_ref(&params),
            scratch.params_buffer.buffer()?,
        );
        mace_polar_trace_stage(&format!("metal.{name}.descriptor_vjp_upload"), stage_start);
        stage_start = trace_timings.then(Instant::now);

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();
        encoder.set_compute_pipeline_state(
            &self.realspace_descriptor_pair_vjp_extended_charge_pipeline,
        );
        encoder.set_buffer(0, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(2, Some(&edge_buffers.receivers_buffer), 0);
        encoder.set_buffer(3, Some(&edge_buffers.sender_offsets_buffer), 0);
        encoder.set_buffer(4, Some(&edge_buffers.sender_edges_buffer), 0);
        encoder.set_buffer(5, Some(&smooth_buffer), 0);
        encoder.set_buffer(6, Some(scratch.bias_buffer.buffer()?), 0);
        encoder.set_buffer(7, Some(scratch.output_mask_buffer.buffer()?), 0);
        encoder.set_buffer(8, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(9, Some(scratch.gate_mask_buffer.buffer()?), 0);
        encoder.set_buffer(10, Some(scratch.params_buffer.buffer()?), 0);
        self.dispatch_1d(
            &encoder,
            &self.realspace_descriptor_pair_vjp_extended_charge_pipeline,
            extended_count,
        )?;

        encoder.set_compute_pipeline_state(&self.realspace_descriptor_pair_vjp_position_pipeline);
        encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(scratch.weight_buffer.buffer()?), 0);
        encoder.set_buffer(2, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(3, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(&edge_buffers.senders_buffer), 0);
        encoder.set_buffer(5, Some(&edge_buffers.receivers_buffer), 0);
        encoder.set_buffer(6, Some(&edge_buffers.sender_offsets_buffer), 0);
        encoder.set_buffer(7, Some(&edge_buffers.sender_edges_buffer), 0);
        encoder.set_buffer(8, Some(&edge_buffers.receiver_offsets_buffer), 0);
        encoder.set_buffer(9, Some(&edge_buffers.receiver_edges_buffer), 0);
        encoder.set_buffer(10, Some(&smooth_derivative_buffer), 0);
        encoder.set_buffer(11, Some(&vectors_buffer), 0);
        encoder.set_buffer(12, Some(&distances_buffer), 0);
        encoder.set_buffer(13, Some(scratch.bias_buffer.buffer()?), 0);
        encoder.set_buffer(14, Some(scratch.output_mask_buffer.buffer()?), 0);
        encoder.set_buffer(15, Some(scratch.cutoff_buffer.buffer()?), 0);
        encoder.set_buffer(16, Some(scratch.params_buffer.buffer()?), 0);
        self.dispatch_1d(
            &encoder,
            &self.realspace_descriptor_pair_vjp_position_pipeline,
            extended_count * 3,
        )?;

        encoder.set_compute_pipeline_state(&self.realspace_descriptor_pair_vjp_finalize_pipeline);
        encoder.set_buffer(0, Some(scratch.hidden_a_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(scratch.gate_mask_buffer.buffer()?), 0);
        encoder.set_buffer(2, Some(scratch.cutoff_buffer.buffer()?), 0);
        encoder.set_buffer(3, Some(scratch.trace_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(scratch.aux_buffer.buffer()?), 0);
        encoder.set_buffer(5, Some(scratch.descriptor_buffer.buffer()?), 0);
        encoder.set_buffer(6, Some(scratch.params_buffer.buffer()?), 0);
        self.dispatch_1d(
            &encoder,
            &self.realspace_descriptor_pair_vjp_finalize_pipeline,
            node_count,
        )?;
        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }
        mace_polar_trace_stage(
            &format!("metal.{name}.descriptor_vjp_command_buffer"),
            stage_start,
        );
        stage_start = trace_timings.then(Instant::now);

        let first_ptr = scratch.trace_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(first_ptr, &mut scratch.trace_f32);
        let second_ptr = scratch.aux_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(second_ptr, &mut scratch.aux_f32);
        let positions_ptr = scratch.descriptor_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(positions_ptr, &mut scratch.descriptor_f32);
        mace_polar_trace_stage(
            &format!("metal.{name}.descriptor_vjp_readback"),
            stage_start,
        );

        let first_source_cotangent = scratch
            .trace_f32
            .chunks_exact(4)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect();
        let second_source_cotangent = scratch
            .aux_f32
            .chunks_exact(4)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect();
        let positions = scratch
            .descriptor_f32
            .chunks_exact(3)
            .map(|row| [f64::from(row[0]), f64::from(row[1]), f64::from(row[2])])
            .collect();

        Ok((first_source_cotangent, second_source_cotangent, positions))
    }

    #[allow(clippy::too_many_arguments)]
    fn geometry_vjp_lmax3_f32(
        &self,
        edge_index: &[[usize; 2]],
        length_cotangents: &[f64],
        edge_attr_cotangents: Option<&MacePolarFlatRows>,
        edge_attr_cotangents_metal: Option<&MacePolarFlatRowsF32Metal>,
        vectors: &[[f64; 3]],
        lengths: &[f64],
        node_count: usize,
        geometry_cache_key: Option<u64>,
        name: &str,
    ) -> Result<Vec<[f64; 3]>, String> {
        let edge_count = edge_index.len();
        if edge_count == 0 {
            return Ok(vec![[0.0; 3]; node_count]);
        }
        if length_cotangents.len() != edge_count {
            return Err(format!(
                "{name}.length_cotangents length mismatch: expected {edge_count}, got {}",
                length_cotangents.len()
            ));
        }
        if vectors.len() != edge_count {
            return Err(format!(
                "{name}.vectors length mismatch: expected {edge_count}, got {}",
                vectors.len()
            ));
        }
        if lengths.len() != edge_count {
            return Err(format!(
                "{name}.lengths length mismatch: expected {edge_count}, got {}",
                lengths.len()
            ));
        }
        let (edge_attr_width, edge_attr_len) = match (
            edge_attr_cotangents,
            edge_attr_cotangents_metal,
        ) {
            (Some(rows), None) => {
                rows.validate(&format!("{name}.edge_attr_cotangents"))
                    .map_err(|err| err.to_string())?;
                if rows.row_count != edge_count {
                    return Err(format!(
                            "{name}.edge_attr_cotangents row count mismatch: expected {edge_count}, got {}",
                            rows.row_count
                        ));
                }
                (rows.width, rows.values.len())
            }
            (None, Some(rows)) => {
                if rows.row_count != edge_count {
                    return Err(format!(
                            "{name}.edge_attr_cotangents_metal row count mismatch: expected {edge_count}, got {}",
                            rows.row_count
                        ));
                }
                (rows.width, rows.len)
            }
            (Some(_), Some(_)) => {
                return Err(format!(
                    "{name} expected either CPU or Metal edge attrs, got both"
                ));
            }
            (None, None) => {
                return Err(format!(
                    "{name} expected either CPU or Metal edge attrs, got neither"
                ));
            }
        };
        if edge_attr_width != 16 {
            return Err(format!(
                "{name}.edge_attr_cotangents width mismatch: expected 16, got {edge_attr_width}",
            ));
        }
        if edge_attr_len != edge_count * edge_attr_width {
            return Err(format!(
                "{name}.edge_attr_cotangents length mismatch: expected {}, got {edge_attr_len}",
                edge_count * edge_attr_width
            ));
        }
        let params = PolarGeometryVjpParamsMetal {
            node_count: u32::try_from(node_count)
                .map_err(|_| format!("{name}.node_count exceeds Metal u32 range"))?,
            edge_count: u32::try_from(edge_count)
                .map_err(|_| format!("{name}.edge_count exceeds Metal u32 range"))?,
            edge_attr_width: u32::try_from(edge_attr_width)
                .map_err(|_| format!("{name}.edge_attr_width exceeds Metal u32 range"))?,
            eps: 1.0e-12_f32,
        };
        let edge_buffers = self.edge_index_buffers_with_cache_key(
            edge_index,
            node_count,
            geometry_cache_key,
            name,
        )?;
        let trace_timings = mace_polar_trace_timings_enabled();
        let mut stage_start = trace_timings.then(Instant::now);
        let options = MTLResourceOptions::StorageModeShared;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;
        f64_to_f32_vec_into(length_cotangents, &mut scratch.input_f32);
        if let Some(edge_attr_cotangents) = edge_attr_cotangents {
            f64_to_f32_vec_into(&edge_attr_cotangents.values, &mut scratch.output_f32);
        }
        scratch.edge_aug_f32.clear();
        scratch.edge_aug_f32.reserve(edge_count.saturating_mul(3));
        for vector in vectors {
            scratch.edge_aug_f32.push(vector[0] as f32);
            scratch.edge_aug_f32.push(vector[1] as f32);
            scratch.edge_aug_f32.push(vector[2] as f32);
        }
        f64_to_f32_vec_into(lengths, &mut scratch.weight_f32);
        scratch.descriptor_f32.clear();
        scratch.descriptor_f32.resize(node_count * 3, 0.0);

        let length_bytes = std::mem::size_of_val(scratch.input_f32.as_slice());
        let edge_attr_bytes = edge_attr_len
            .checked_mul(std::mem::size_of::<f32>())
            .ok_or_else(|| format!("{name}.edge attr bytes overflow usize"))?;
        let vector_bytes = std::mem::size_of_val(scratch.edge_aug_f32.as_slice());
        let lengths_bytes = std::mem::size_of_val(scratch.weight_f32.as_slice());
        let position_bytes = node_count
            .checked_mul(3)
            .and_then(|len| len.checked_mul(std::mem::size_of::<f32>()))
            .ok_or_else(|| format!("{name}.position output bytes overflow usize"))?;
        let params_bytes = std::mem::size_of_val(std::slice::from_ref(&params));
        scratch
            .input_buffer
            .ensure_capacity(&self.device, length_bytes, options)?;
        if edge_attr_cotangents.is_some() {
            scratch
                .output_buffer
                .ensure_capacity(&self.device, edge_attr_bytes, options)?;
        }
        scratch
            .hidden_b_buffer
            .ensure_capacity(&self.device, vector_bytes, options)?;
        scratch
            .weight_buffer
            .ensure_capacity(&self.device, lengths_bytes, options)?;
        scratch
            .descriptor_buffer
            .ensure_capacity(&self.device, position_bytes, options)?;
        scratch
            .params_buffer
            .ensure_capacity(&self.device, params_bytes, options)?;

        copy_slice_to_buffer(&scratch.input_f32, scratch.input_buffer.buffer()?);
        if edge_attr_cotangents.is_some() {
            copy_slice_to_buffer(&scratch.output_f32, scratch.output_buffer.buffer()?);
        }
        copy_slice_to_buffer(&scratch.edge_aug_f32, scratch.hidden_b_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.weight_f32, scratch.weight_buffer.buffer()?);
        copy_slice_to_buffer(
            std::slice::from_ref(&params),
            scratch.params_buffer.buffer()?,
        );
        mace_polar_trace_stage(&format!("metal.{name}.geometry_vjp_upload"), stage_start);
        stage_start = trace_timings.then(Instant::now);

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();
        encoder.set_compute_pipeline_state(&self.geometry_vjp_lmax3_pipeline);
        encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
        if let Some(rows) = edge_attr_cotangents_metal {
            encoder.set_buffer(1, Some(&rows.buffer), 0);
        } else {
            encoder.set_buffer(1, Some(scratch.output_buffer.buffer()?), 0);
        }
        encoder.set_buffer(2, Some(scratch.hidden_b_buffer.buffer()?), 0);
        encoder.set_buffer(3, Some(scratch.weight_buffer.buffer()?), 0);
        encoder.set_buffer(4, Some(&edge_buffers.sender_offsets_buffer), 0);
        encoder.set_buffer(5, Some(&edge_buffers.sender_edges_buffer), 0);
        encoder.set_buffer(6, Some(&edge_buffers.receiver_offsets_buffer), 0);
        encoder.set_buffer(7, Some(&edge_buffers.receiver_edges_buffer), 0);
        encoder.set_buffer(8, Some(scratch.descriptor_buffer.buffer()?), 0);
        encoder.set_buffer(9, Some(scratch.params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.geometry_vjp_lmax3_pipeline, node_count)?;
        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }
        mace_polar_trace_stage(
            &format!("metal.{name}.geometry_vjp_command_buffer"),
            stage_start,
        );
        stage_start = trace_timings.then(Instant::now);

        let output_ptr = scratch.descriptor_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(output_ptr, &mut scratch.descriptor_f32);
        mace_polar_trace_stage(&format!("metal.{name}.geometry_vjp_readback"), stage_start);
        Ok(scratch
            .descriptor_f32
            .chunks_exact(3)
            .map(|row| [f64::from(row[0]), f64::from(row[1]), f64::from(row[2])])
            .collect())
    }

    #[allow(clippy::too_many_arguments)]
    fn conv_tp_vjp_flat_f32_with_static_table_impl(
        &self,
        edge_index: &[[usize; 2]],
        linear_up: &[Vec<f64>],
        edge_attrs: &[Vec<f64>],
        weights: FlatF32RowsSource<'_>,
        scatter_cotangent: &[Vec<f64>],
        node_count: usize,
        table: &ConvTpStaticTable,
        read_linear_up_cotangent: bool,
        read_edge_attr_cotangent: bool,
        read_weight_cotangent: bool,
        name: &str,
    ) -> Result<ConvTpVjpFlatF32Output, String> {
        let edge_count = edge_index.len();
        if node_count == 0 {
            return Ok((
                Some(Vec::new()),
                Some(MacePolarFlatRows {
                    values: Vec::new(),
                    row_count: 0,
                    width: table.input2_dim,
                }),
                Some(MacePolarFlatRowsF32 {
                    values: Vec::new(),
                    row_count: 0,
                    width: table.weight_dim,
                }),
                MacePolarFlatRowsF32Metal {
                    row_count: 0,
                    width: table.input1_dim,
                    len: 0,
                    buffer: self
                        .device
                        .new_buffer(1, MTLResourceOptions::StorageModeShared),
                },
                MacePolarFlatRowsF32Metal {
                    row_count: 0,
                    width: table.input2_dim,
                    len: 0,
                    buffer: self
                        .device
                        .new_buffer(1, MTLResourceOptions::StorageModeShared),
                },
                MacePolarFlatRowsF32Metal {
                    row_count: 0,
                    width: table.weight_dim,
                    len: 0,
                    buffer: self
                        .device
                        .new_buffer(1, MTLResourceOptions::StorageModeShared),
                },
            ));
        }
        if linear_up.len() != node_count {
            return Err(format!(
                "{name}.linear_up row count mismatch: expected {node_count}, got {}",
                linear_up.len()
            ));
        }
        if edge_attrs.len() != edge_count {
            return Err(format!(
                "{name}.edge_attrs row count mismatch: expected {edge_count}, got {}",
                edge_attrs.len()
            ));
        }
        if weights.row_count() != edge_count || weights.width() != table.weight_dim {
            return Err(format!(
                "{name}.weights shape mismatch: expected {edge_count}x{}, got {}x{}",
                table.weight_dim,
                weights.row_count(),
                weights.width()
            ));
        }
        if weights.len() != edge_count.saturating_mul(table.weight_dim) {
            return Err(format!(
                "{name}.weights length mismatch: expected {}, got {}",
                edge_count.saturating_mul(table.weight_dim),
                weights.len()
            ));
        }
        if scatter_cotangent.len() != node_count {
            return Err(format!(
                "{name}.scatter_cotangent row count mismatch: expected {node_count}, got {}",
                scatter_cotangent.len()
            ));
        }
        let linear_len = node_count
            .checked_mul(table.input1_dim)
            .ok_or_else(|| format!("{name} linear-up cotangent length overflows usize"))?;
        let edge_attr_len = edge_count
            .checked_mul(table.input2_dim)
            .ok_or_else(|| format!("{name} edge-attrs cotangent length overflows usize"))?;
        let weight_len = edge_count
            .checked_mul(table.weight_dim)
            .ok_or_else(|| format!("{name} weights cotangent length overflows usize"))?;
        let scatter_len = node_count
            .checked_mul(table.output_dim)
            .ok_or_else(|| format!("{name} scatter cotangent length overflows usize"))?;
        let params = table.params(node_count, edge_count)?;
        let table_buffers = table.metal_buffers(&self.device)?;
        let edge_index_buffers = self.edge_index_buffers(edge_index, node_count, name)?;

        let options = MTLResourceOptions::StorageModeShared;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;
        flatten_rows_f32_into(
            linear_up,
            table.input1_dim,
            &format!("{name}.linear_up"),
            &mut scratch.input_f32,
        )?;
        flatten_rows_f32_into(
            edge_attrs,
            table.input2_dim,
            &format!("{name}.edge_attrs"),
            &mut scratch.weight_f32,
        )?;
        flatten_rows_f32_into(
            scatter_cotangent,
            table.output_dim,
            &format!("{name}.scatter_cotangent"),
            &mut scratch.scatter_f32,
        )?;
        scratch.output_f32.clear();
        scratch.output_f32.resize(linear_len, 0.0);
        scratch.edge_aug_f32.clear();
        scratch.edge_aug_f32.resize(edge_attr_len, 0.0);
        scratch.gate_f32.clear();
        if read_weight_cotangent {
            scratch.gate_f32.resize(weight_len, 0.0);
        }

        let linear_up_bytes = std::mem::size_of_val(scratch.input_f32.as_slice());
        let edge_attrs_bytes = std::mem::size_of_val(scratch.weight_f32.as_slice());
        let weights_bytes = weights.byte_len();
        let scatter_bytes = std::mem::size_of_val(scratch.scatter_f32.as_slice());
        let linear_out_bytes = std::mem::size_of_val(scratch.output_f32.as_slice());
        let edge_attr_out_bytes = std::mem::size_of_val(scratch.edge_aug_f32.as_slice());
        let weight_out_bytes = weight_len
            .checked_mul(std::mem::size_of::<f32>())
            .ok_or_else(|| format!("{name} weights cotangent byte length overflows usize"))?;
        let params_bytes = std::mem::size_of_val(std::slice::from_ref(&params));

        scratch
            .input_buffer
            .ensure_capacity(&self.device, linear_up_bytes, options)?;
        scratch
            .weight_buffer
            .ensure_capacity(&self.device, edge_attrs_bytes, options)?;
        if matches!(weights, FlatF32RowsSource::Cpu(_)) {
            scratch
                .bias_buffer
                .ensure_capacity(&self.device, weights_bytes, options)?;
        }
        scratch
            .output_buffer
            .ensure_capacity(&self.device, scatter_bytes, options)?;
        scratch
            .hidden_a_buffer
            .ensure_capacity(&self.device, linear_out_bytes, options)?;
        scratch
            .hidden_b_buffer
            .ensure_capacity(&self.device, edge_attr_out_bytes, options)?;
        scratch
            .aux_buffer
            .ensure_capacity(&self.device, weight_out_bytes, options)?;
        scratch
            .params_buffer
            .ensure_capacity(&self.device, params_bytes, options)?;

        copy_slice_to_buffer(&scratch.input_f32, scratch.input_buffer.buffer()?);
        copy_slice_to_buffer(&scratch.weight_f32, scratch.weight_buffer.buffer()?);
        if let FlatF32RowsSource::Cpu(rows) = weights {
            copy_slice_to_buffer(&rows.values, scratch.bias_buffer.buffer()?);
        }
        copy_slice_to_buffer(&scratch.scatter_f32, scratch.output_buffer.buffer()?);
        copy_slice_to_buffer(
            std::slice::from_ref(&params),
            scratch.params_buffer.buffer()?,
        );

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();

        if table.output_mask_all_one {
            encoder.set_compute_pipeline_state(&self.conv_tp_vjp_linear_up_nomask_pipeline);
            encoder.set_buffer(0, Some(scratch.weight_buffer.buffer()?), 0);
            match weights {
                FlatF32RowsSource::Cpu(_) => {
                    encoder.set_buffer(1, Some(scratch.bias_buffer.buffer()?), 0);
                }
                FlatF32RowsSource::Metal(rows) => {
                    encoder.set_buffer(1, Some(&rows.buffer), 0);
                }
            }
            encoder.set_buffer(2, Some(scratch.output_buffer.buffer()?), 0);
            encoder.set_buffer(3, Some(&edge_index_buffers.sender_offsets_buffer), 0);
            encoder.set_buffer(4, Some(&edge_index_buffers.sender_edges_buffer), 0);
            encoder.set_buffer(5, Some(&edge_index_buffers.receivers_buffer), 0);
            encoder.set_buffer(6, Some(&table_buffers.vjp_input1_lane_offsets_buffer), 0);
            encoder.set_buffer(7, Some(&table_buffers.vjp_input1_lane_entries_buffer), 0);
            encoder.set_buffer(8, Some(scratch.hidden_a_buffer.buffer()?), 0);
            encoder.set_buffer(9, Some(scratch.params_buffer.buffer()?), 0);
            self.dispatch_1d(
                &encoder,
                &self.conv_tp_vjp_linear_up_nomask_pipeline,
                linear_len,
            )?;

            encoder.set_compute_pipeline_state(&self.conv_tp_vjp_edge_attrs_nomask_pipeline);
            encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
            match weights {
                FlatF32RowsSource::Cpu(_) => {
                    encoder.set_buffer(1, Some(scratch.bias_buffer.buffer()?), 0);
                }
                FlatF32RowsSource::Metal(rows) => {
                    encoder.set_buffer(1, Some(&rows.buffer), 0);
                }
            }
            encoder.set_buffer(2, Some(scratch.output_buffer.buffer()?), 0);
            encoder.set_buffer(3, Some(&edge_index_buffers.senders_buffer), 0);
            encoder.set_buffer(4, Some(&edge_index_buffers.receivers_buffer), 0);
            encoder.set_buffer(5, Some(&table_buffers.vjp_input2_lane_offsets_buffer), 0);
            encoder.set_buffer(6, Some(&table_buffers.vjp_input2_lane_entries_buffer), 0);
            encoder.set_buffer(7, Some(scratch.hidden_b_buffer.buffer()?), 0);
            encoder.set_buffer(8, Some(scratch.params_buffer.buffer()?), 0);
            self.dispatch_1d(
                &encoder,
                &self.conv_tp_vjp_edge_attrs_nomask_pipeline,
                edge_attr_len,
            )?;

            encoder.set_compute_pipeline_state(&self.conv_tp_vjp_weights_nomask_2d_pipeline);
            encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
            encoder.set_buffer(1, Some(scratch.weight_buffer.buffer()?), 0);
            encoder.set_buffer(2, Some(scratch.output_buffer.buffer()?), 0);
            encoder.set_buffer(3, Some(&edge_index_buffers.senders_buffer), 0);
            encoder.set_buffer(4, Some(&edge_index_buffers.receivers_buffer), 0);
            encoder.set_buffer(5, Some(&table_buffers.vjp_weight_lane_offsets_buffer), 0);
            encoder.set_buffer(6, Some(&table_buffers.vjp_weight_lane_entries_buffer), 0);
            encoder.set_buffer(7, Some(scratch.aux_buffer.buffer()?), 0);
            encoder.set_buffer(8, Some(scratch.params_buffer.buffer()?), 0);
            self.dispatch_2d(
                &encoder,
                &self.conv_tp_vjp_weights_nomask_2d_pipeline,
                table.weight_dim,
                edge_count,
            )?;
        } else {
            encoder.set_compute_pipeline_state(&self.conv_tp_vjp_linear_up_pipeline);
            encoder.set_buffer(0, Some(scratch.weight_buffer.buffer()?), 0);
            match weights {
                FlatF32RowsSource::Cpu(_) => {
                    encoder.set_buffer(1, Some(scratch.bias_buffer.buffer()?), 0);
                }
                FlatF32RowsSource::Metal(rows) => {
                    encoder.set_buffer(1, Some(&rows.buffer), 0);
                }
            }
            encoder.set_buffer(2, Some(scratch.output_buffer.buffer()?), 0);
            encoder.set_buffer(3, Some(&edge_index_buffers.sender_offsets_buffer), 0);
            encoder.set_buffer(4, Some(&edge_index_buffers.sender_edges_buffer), 0);
            encoder.set_buffer(5, Some(&edge_index_buffers.receivers_buffer), 0);
            encoder.set_buffer(6, Some(&table_buffers.vjp_input1_lane_offsets_buffer), 0);
            encoder.set_buffer(7, Some(&table_buffers.vjp_input1_lane_entries_buffer), 0);
            encoder.set_buffer(8, Some(&table_buffers.output_mask_buffer), 0);
            encoder.set_buffer(9, Some(scratch.hidden_a_buffer.buffer()?), 0);
            encoder.set_buffer(10, Some(scratch.params_buffer.buffer()?), 0);
            self.dispatch_1d(&encoder, &self.conv_tp_vjp_linear_up_pipeline, linear_len)?;

            encoder.set_compute_pipeline_state(&self.conv_tp_vjp_edge_attrs_pipeline);
            encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
            match weights {
                FlatF32RowsSource::Cpu(_) => {
                    encoder.set_buffer(1, Some(scratch.bias_buffer.buffer()?), 0);
                }
                FlatF32RowsSource::Metal(rows) => {
                    encoder.set_buffer(1, Some(&rows.buffer), 0);
                }
            }
            encoder.set_buffer(2, Some(scratch.output_buffer.buffer()?), 0);
            encoder.set_buffer(3, Some(&edge_index_buffers.senders_buffer), 0);
            encoder.set_buffer(4, Some(&edge_index_buffers.receivers_buffer), 0);
            encoder.set_buffer(5, Some(&table_buffers.vjp_input2_lane_offsets_buffer), 0);
            encoder.set_buffer(6, Some(&table_buffers.vjp_input2_lane_entries_buffer), 0);
            encoder.set_buffer(7, Some(&table_buffers.output_mask_buffer), 0);
            encoder.set_buffer(8, Some(scratch.hidden_b_buffer.buffer()?), 0);
            encoder.set_buffer(9, Some(scratch.params_buffer.buffer()?), 0);
            self.dispatch_1d(
                &encoder,
                &self.conv_tp_vjp_edge_attrs_pipeline,
                edge_attr_len,
            )?;

            encoder.set_compute_pipeline_state(&self.conv_tp_vjp_weights_2d_pipeline);
            encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
            encoder.set_buffer(1, Some(scratch.weight_buffer.buffer()?), 0);
            encoder.set_buffer(2, Some(scratch.output_buffer.buffer()?), 0);
            encoder.set_buffer(3, Some(&edge_index_buffers.senders_buffer), 0);
            encoder.set_buffer(4, Some(&edge_index_buffers.receivers_buffer), 0);
            encoder.set_buffer(5, Some(&table_buffers.vjp_weight_lane_offsets_buffer), 0);
            encoder.set_buffer(6, Some(&table_buffers.vjp_weight_lane_entries_buffer), 0);
            encoder.set_buffer(7, Some(&table_buffers.output_mask_buffer), 0);
            encoder.set_buffer(8, Some(scratch.aux_buffer.buffer()?), 0);
            encoder.set_buffer(9, Some(scratch.params_buffer.buffer()?), 0);
            self.dispatch_2d(
                &encoder,
                &self.conv_tp_vjp_weights_2d_pipeline,
                table.weight_dim,
                edge_count,
            )?;
        }

        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }

        if read_linear_up_cotangent {
            let linear_ptr = scratch.hidden_a_buffer.buffer()?.contents().cast::<f32>();
            copy_ptr_to_slice(linear_ptr, &mut scratch.output_f32);
        }
        if read_edge_attr_cotangent {
            let edge_attrs_ptr = scratch.hidden_b_buffer.buffer()?.contents().cast::<f32>();
            copy_ptr_to_slice(edge_attrs_ptr, &mut scratch.edge_aug_f32);
        }
        if read_weight_cotangent {
            let weights_ptr = scratch.aux_buffer.buffer()?.contents().cast::<f32>();
            copy_ptr_to_slice(weights_ptr, &mut scratch.gate_f32);
        }

        debug_assert_eq!(scratch.output_f32.len(), linear_len);
        if read_edge_attr_cotangent {
            debug_assert_eq!(scratch.edge_aug_f32.len(), edge_attr_len);
        }
        if read_weight_cotangent {
            debug_assert_eq!(scratch.gate_f32.len(), weight_len);
        }
        debug_assert_eq!(scratch.scatter_f32.len(), scatter_len);

        let linear_up = read_linear_up_cotangent.then(|| {
            scratch
                .output_f32
                .chunks_exact(table.input1_dim)
                .map(|row| row.iter().map(|value| f64::from(*value)).collect())
                .collect()
        });
        let edge_attrs = read_edge_attr_cotangent.then(|| MacePolarFlatRows {
            values: scratch
                .edge_aug_f32
                .iter()
                .map(|value| f64::from(*value))
                .collect(),
            row_count: edge_count,
            width: table.input2_dim,
        });
        let linear_up_metal = MacePolarFlatRowsF32Metal {
            row_count: node_count,
            width: table.input1_dim,
            len: linear_len,
            buffer: scratch.hidden_a_buffer.buffer()?.clone(),
        };
        let edge_attrs_metal = if read_edge_attr_cotangent {
            MacePolarFlatRowsF32Metal {
                row_count: edge_count,
                width: table.input2_dim,
                len: edge_attr_len,
                buffer: scratch.hidden_b_buffer.buffer()?.clone(),
            }
        } else {
            self.clone_flat_rows_f32_buffer(
                scratch.hidden_b_buffer.buffer()?,
                edge_count,
                table.input2_dim,
                &format!("{name}.edge_attrs"),
            )?
        };
        let weights = read_weight_cotangent.then(|| MacePolarFlatRowsF32 {
            values: scratch.gate_f32.clone(),
            row_count: edge_count,
            width: table.weight_dim,
        });
        let weights_metal = MacePolarFlatRowsF32Metal {
            row_count: edge_count,
            width: table.weight_dim,
            len: weight_len,
            buffer: scratch.aux_buffer.buffer()?.clone(),
        };

        Ok((
            linear_up,
            edge_attrs,
            weights,
            linear_up_metal,
            edge_attrs_metal,
            weights_metal,
        ))
    }

    #[allow(clippy::too_many_arguments)]
    fn conv_tp_vjp_flat_f32_with_static_table(
        &self,
        edge_index: &[[usize; 2]],
        linear_up: &[Vec<f64>],
        edge_attrs: &[Vec<f64>],
        weights: &MacePolarFlatRowsF32,
        scatter_cotangent: &[Vec<f64>],
        node_count: usize,
        table: &ConvTpStaticTable,
        name: &str,
    ) -> Result<(MacePolarRows, MacePolarFlatRows, MacePolarFlatRowsF32), String> {
        let (linear_up, edge_attrs, weights, _, _, _) = self
            .conv_tp_vjp_flat_f32_with_static_table_impl(
                edge_index,
                linear_up,
                edge_attrs,
                FlatF32RowsSource::Cpu(weights),
                scatter_cotangent,
                node_count,
                table,
                true,
                true,
                true,
                name,
            )?;
        Ok((
            linear_up.ok_or_else(|| format!("{name} missing linear-up cotangent"))?,
            edge_attrs.ok_or_else(|| format!("{name} missing edge-attr cotangent"))?,
            weights.ok_or_else(|| format!("{name} missing CPU weight cotangent"))?,
        ))
    }

