    fn product_symmetric_scalar_forward_rows_f32(
        &self,
        input: &[f64],
        node_count: usize,
        hidden_dim: usize,
        num_ell: usize,
        table: &ProductScalarForwardFeatureTable,
    ) -> Result<MacePolarRows, String> {
        if node_count == 0 {
            return Ok(Vec::new());
        }
        if table.hidden_dim != hidden_dim {
            return Err(format!(
                "product symmetric scalar feature count mismatch: expected {hidden_dim}, got {}",
                table.hidden_dim
            ));
        }
        let expected_input = node_count
            .checked_mul(hidden_dim)
            .and_then(|value| value.checked_mul(num_ell))
            .ok_or_else(|| "product symmetric scalar input length overflows usize".to_owned())?;
        if input.len() != expected_input {
            return Err(format!(
                "product symmetric scalar input length mismatch: expected {expected_input}, got {}",
                input.len()
            ));
        }
        let output_len = node_count
            .checked_mul(hidden_dim)
            .ok_or_else(|| "product symmetric scalar output length overflows usize".to_owned())?;
        let params = PolarProductScalarForwardParamsMetal {
            num_nodes: u32::try_from(node_count)
                .map_err(|_| "node count exceeds Metal u32 range".to_owned())?,
            num_features: u32::try_from(hidden_dim)
                .map_err(|_| "feature count exceeds Metal u32 range".to_owned())?,
            num_ell: u32::try_from(num_ell)
                .map_err(|_| "ell count exceeds Metal u32 range".to_owned())?,
        };

        let options = MTLResourceOptions::StorageModeShared;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;
        f64_to_f32_vec_into(input, &mut scratch.input_f32);
        scratch.output_f32.clear();
        scratch.output_f32.resize(output_len, 0.0);

        let input_bytes = std::mem::size_of_val(scratch.input_f32.as_slice());
        let output_bytes = std::mem::size_of_val(scratch.output_f32.as_slice());
        let params_bytes = std::mem::size_of_val(std::slice::from_ref(&params));
        let table_buffers = table.metal_buffers(&self.device)?;

        scratch
            .input_buffer
            .ensure_capacity(&self.device, input_bytes, options)?;
        scratch
            .output_buffer
            .ensure_capacity(&self.device, output_bytes, options)?;
        scratch
            .params_buffer
            .ensure_capacity(&self.device, params_bytes, options)?;

        copy_slice_to_buffer(&scratch.input_f32, scratch.input_buffer.buffer()?);
        copy_slice_to_buffer(
            std::slice::from_ref(&params),
            scratch.params_buffer.buffer()?,
        );

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();
        encoder.set_compute_pipeline_state(&self.product_scalar_forward_pipeline);
        encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&table_buffers.u1_offsets_buffer), 0);
        encoder.set_buffer(2, Some(&table_buffers.u2_offsets_buffer), 0);
        encoder.set_buffer(3, Some(&table_buffers.u3_offsets_buffer), 0);
        encoder.set_buffer(4, Some(&table_buffers.u1_entries_buffer), 0);
        encoder.set_buffer(5, Some(&table_buffers.u2_entries_buffer), 0);
        encoder.set_buffer(6, Some(&table_buffers.u3_entries_buffer), 0);
        encoder.set_buffer(7, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(8, Some(scratch.params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.product_scalar_forward_pipeline, output_len)?;
        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }

        let output_ptr = scratch.output_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(output_ptr, &mut scratch.output_f32);

        Ok(scratch
            .output_f32
            .chunks_exact(hidden_dim)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect())
    }

    fn product_symmetric_vector_forward_rows_f32(
        &self,
        input: &[f64],
        node_count: usize,
        hidden_dim: usize,
        num_equivariance: usize,
        num_ell: usize,
        table: &ProductVectorForwardFeatureTable,
    ) -> Result<MacePolarRows, String> {
        if node_count == 0 {
            return Ok(Vec::new());
        }
        if table.hidden_dim != hidden_dim || table.num_equivariance != num_equivariance {
            return Err(format!(
                "product symmetric vector feature shape mismatch: expected hidden_dim={hidden_dim} num_equivariance={num_equivariance}, got hidden_dim={} num_equivariance={}",
                table.hidden_dim, table.num_equivariance
            ));
        }
        let expected_input = node_count
            .checked_mul(hidden_dim)
            .and_then(|value| value.checked_mul(num_ell))
            .ok_or_else(|| "product symmetric vector input length overflows usize".to_owned())?;
        if input.len() != expected_input {
            return Err(format!(
                "product symmetric vector input length mismatch: expected {expected_input}, got {}",
                input.len()
            ));
        }
        let row_len = hidden_dim
            .checked_mul(num_equivariance)
            .ok_or_else(|| "product symmetric vector row length overflows usize".to_owned())?;
        let output_len = node_count
            .checked_mul(row_len)
            .ok_or_else(|| "product symmetric vector output length overflows usize".to_owned())?;
        let params = PolarProductVectorForwardParamsMetal {
            num_nodes: u32::try_from(node_count)
                .map_err(|_| "node count exceeds Metal u32 range".to_owned())?,
            num_features: u32::try_from(hidden_dim)
                .map_err(|_| "feature count exceeds Metal u32 range".to_owned())?,
            num_equivariance: u32::try_from(num_equivariance)
                .map_err(|_| "equivariance count exceeds Metal u32 range".to_owned())?,
            num_ell: u32::try_from(num_ell)
                .map_err(|_| "ell count exceeds Metal u32 range".to_owned())?,
        };

        let options = MTLResourceOptions::StorageModeShared;
        let mut scratch = self
            .scratch
            .lock()
            .map_err(|_| "MACE-Polar Metal scratch mutex was poisoned".to_owned())?;
        f64_to_f32_vec_into(input, &mut scratch.input_f32);
        scratch.output_f32.clear();
        scratch.output_f32.resize(output_len, 0.0);

        let input_bytes = std::mem::size_of_val(scratch.input_f32.as_slice());
        let output_bytes = std::mem::size_of_val(scratch.output_f32.as_slice());
        let params_bytes = std::mem::size_of_val(std::slice::from_ref(&params));
        let table_buffers = table.metal_buffers(&self.device)?;

        scratch
            .input_buffer
            .ensure_capacity(&self.device, input_bytes, options)?;
        scratch
            .output_buffer
            .ensure_capacity(&self.device, output_bytes, options)?;
        scratch
            .params_buffer
            .ensure_capacity(&self.device, params_bytes, options)?;

        copy_slice_to_buffer(&scratch.input_f32, scratch.input_buffer.buffer()?);
        copy_slice_to_buffer(
            std::slice::from_ref(&params),
            scratch.params_buffer.buffer()?,
        );

        let command_buffer = self.queue.new_command_buffer();
        let encoder = command_buffer.new_compute_command_encoder();
        encoder.set_compute_pipeline_state(&self.product_vector_forward_pipeline);
        encoder.set_buffer(0, Some(scratch.input_buffer.buffer()?), 0);
        encoder.set_buffer(1, Some(&table_buffers.u1_offsets_buffer), 0);
        encoder.set_buffer(2, Some(&table_buffers.u2_offsets_buffer), 0);
        encoder.set_buffer(3, Some(&table_buffers.u3_offsets_buffer), 0);
        encoder.set_buffer(4, Some(&table_buffers.u1_entries_buffer), 0);
        encoder.set_buffer(5, Some(&table_buffers.u2_entries_buffer), 0);
        encoder.set_buffer(6, Some(&table_buffers.u3_entries_buffer), 0);
        encoder.set_buffer(7, Some(scratch.output_buffer.buffer()?), 0);
        encoder.set_buffer(8, Some(scratch.params_buffer.buffer()?), 0);
        self.dispatch_1d(&encoder, &self.product_vector_forward_pipeline, output_len)?;
        encoder.end_encoding();
        command_buffer.commit();
        command_buffer.wait_until_completed();

        let status = command_buffer.status();
        if status != metal::MTLCommandBufferStatus::Completed {
            return Err(format!("Metal command buffer did not complete: {status:?}"));
        }

        let output_ptr = scratch.output_buffer.buffer()?.contents().cast::<f32>();
        copy_ptr_to_slice(output_ptr, &mut scratch.output_f32);

        Ok(scratch
            .output_f32
            .chunks_exact(row_len)
            .map(|row| row.iter().map(|value| f64::from(*value)).collect())
            .collect())
    }

    fn block_linear_instruction_buffer(
        &self,
        spec: &MacePolarBlockLinearSpec<'_>,
    ) -> Result<Buffer, String> {
        let (key, entries) = block_linear_instruction_cache_key_and_entries(spec)?;
        let mut static_cache = self
            .static_cache
            .lock()
            .map_err(|_| "MACE-Polar Metal static cache mutex was poisoned".to_owned())?;
        Ok(static_cache
            .block_instruction_buffers
            .entry(key)
            .or_insert_with(|| {
                buffer_with_slice_on_device(
                    &self.device,
                    &entries,
                    MTLResourceOptions::StorageModeShared,
                )
            })
            .clone())
    }

    fn node_type_id_buffer(
        &self,
        atomic_numbers: &[u8],
        type_count: usize,
        name: &str,
    ) -> Result<Buffer, String> {
        let mut static_cache = self
            .static_cache
            .lock()
            .map_err(|_| "MACE-Polar Metal static cache mutex was poisoned".to_owned())?;
        if let Some(entry) = static_cache.node_type_id_buffers.iter().find(|entry| {
            entry.type_count == type_count && entry.atomic_numbers.as_slice() == atomic_numbers
        }) {
            return Ok(entry.buffer.clone());
        }

        let type_ids = pack_node_type_ids(atomic_numbers, type_count, name)?;
        let buffer = buffer_with_slice_on_device(
            &self.device,
            &type_ids,
            MTLResourceOptions::StorageModeShared,
        );
        static_cache
            .node_type_id_buffers
            .push(NodeTypeIdBufferCacheEntry {
                type_count,
                atomic_numbers: atomic_numbers.to_vec(),
                buffer: buffer.clone(),
            });
        Ok(buffer)
    }

    fn edge_index_buffers(
        &self,
        edge_index: &[[usize; 2]],
        node_count: usize,
        name: &str,
    ) -> Result<EdgeIndexBuffers, String> {
        self.edge_index_buffers_with_cache_key(edge_index, node_count, None, name)
    }

    fn edge_index_buffers_with_cache_key(
        &self,
        edge_index: &[[usize; 2]],
        node_count: usize,
        cache_key: Option<u64>,
        name: &str,
    ) -> Result<EdgeIndexBuffers, String> {
        let mut static_cache = self
            .static_cache
            .lock()
            .map_err(|_| "MACE-Polar Metal static cache mutex was poisoned".to_owned())?;
        if let Some(cache_key) = cache_key {
            if let Some(entry) = static_cache.edge_index_buffers.iter().find(|entry| {
                entry.cache_key == Some(cache_key)
                    && entry.node_count == node_count
                    && entry.edge_index.len() == edge_index.len()
            }) {
                return Ok(EdgeIndexBuffers {
                    senders_buffer: entry.senders_buffer.clone(),
                    receivers_buffer: entry.receivers_buffer.clone(),
                    sender_offsets_buffer: entry.sender_offsets_buffer.clone(),
                    sender_edges_buffer: entry.sender_edges_buffer.clone(),
                    receiver_offsets_buffer: entry.receiver_offsets_buffer.clone(),
                    receiver_edges_buffer: entry.receiver_edges_buffer.clone(),
                });
            }
        }
        if let Some(entry) = static_cache.edge_index_buffers.iter().find(|entry| {
            entry.node_count == node_count && entry.edge_index.as_slice() == edge_index
        }) {
            return Ok(EdgeIndexBuffers {
                senders_buffer: entry.senders_buffer.clone(),
                receivers_buffer: entry.receivers_buffer.clone(),
                sender_offsets_buffer: entry.sender_offsets_buffer.clone(),
                sender_edges_buffer: entry.sender_edges_buffer.clone(),
                receiver_offsets_buffer: entry.receiver_offsets_buffer.clone(),
                receiver_edges_buffer: entry.receiver_edges_buffer.clone(),
            });
        }

        let (senders, receivers, sender_offsets, sender_edges, receiver_offsets, receiver_edges) =
            pack_edge_topology(edge_index, node_count, name)?;
        let options = MTLResourceOptions::StorageModeShared;
        let senders_buffer = buffer_with_slice_on_device(&self.device, &senders, options);
        let receivers_buffer = buffer_with_slice_on_device(&self.device, &receivers, options);
        let sender_offsets_buffer =
            buffer_with_slice_on_device(&self.device, &sender_offsets, options);
        let sender_edges_buffer = buffer_with_slice_on_device(&self.device, &sender_edges, options);
        let receiver_offsets_buffer =
            buffer_with_slice_on_device(&self.device, &receiver_offsets, options);
        let receiver_edges_buffer =
            buffer_with_slice_on_device(&self.device, &receiver_edges, options);
        static_cache
            .edge_index_buffers
            .push(EdgeIndexBufferCacheEntry {
                cache_key,
                node_count,
                edge_index: edge_index.to_vec(),
                senders_buffer: senders_buffer.clone(),
                receivers_buffer: receivers_buffer.clone(),
                sender_offsets_buffer: sender_offsets_buffer.clone(),
                sender_edges_buffer: sender_edges_buffer.clone(),
                receiver_offsets_buffer: receiver_offsets_buffer.clone(),
                receiver_edges_buffer: receiver_edges_buffer.clone(),
            });
        static_cache.trim_geometry_buffer_caches();
        Ok(EdgeIndexBuffers {
            senders_buffer,
            receivers_buffer,
            sender_offsets_buffer,
            sender_edges_buffer,
            receiver_offsets_buffer,
            receiver_edges_buffer,
        })
    }

    fn realspace_descriptor_smooth_buffer(
        &self,
        edge_index: &[[usize; 2]],
        smooth_by_edge_radial: &[f32],
        cache_key: Option<u64>,
        num_radial: usize,
        name: &str,
    ) -> Result<Buffer, String> {
        let expected_len = edge_index
            .len()
            .checked_mul(num_radial)
            .ok_or_else(|| format!("{name}.smooth length overflows usize"))?;
        if smooth_by_edge_radial.len() != expected_len {
            return Err(format!(
                "{name}.smooth_by_edge_radial expected length {expected_len}, got {}",
                smooth_by_edge_radial.len()
            ));
        }
        let mut static_cache = self
            .static_cache
            .lock()
            .map_err(|_| "MACE-Polar Metal static cache mutex was poisoned".to_owned())?;
        if let Some(cache_key) = cache_key {
            if let Some(entry) = static_cache
                .realspace_descriptor_smooth_buffers
                .iter()
                .find(|entry| {
                    entry.cache_key == Some(cache_key)
                        && entry.num_radial == num_radial
                        && entry.edge_index.len() == edge_index.len()
                        && entry.smooth_by_edge_radial.len() == smooth_by_edge_radial.len()
                })
            {
                return Ok(entry.buffer.clone());
            }
        }
        if let Some(entry) = static_cache
            .realspace_descriptor_smooth_buffers
            .iter()
            .find(|entry| {
                entry.num_radial == num_radial
                    && entry.edge_index.as_slice() == edge_index
                    && entry.smooth_by_edge_radial.as_slice() == smooth_by_edge_radial
            })
        {
            return Ok(entry.buffer.clone());
        }
        let buffer = buffer_with_slice_on_device(
            &self.device,
            smooth_by_edge_radial,
            MTLResourceOptions::StorageModeShared,
        );
        static_cache.realspace_descriptor_smooth_buffers.push(
            RealspaceDescriptorSmoothBufferCacheEntry {
                cache_key,
                num_radial,
                edge_index: edge_index.to_vec(),
                smooth_by_edge_radial: smooth_by_edge_radial.to_vec(),
                buffer: buffer.clone(),
            },
        );
        static_cache.trim_geometry_buffer_caches();
        Ok(buffer)
    }

    #[allow(clippy::too_many_arguments)]
    fn realspace_descriptor_vjp_geometry_buffers(
        &self,
        edge_index: &[[usize; 2]],
        smooth_derivative_by_edge_radial: &[f32],
        vectors_sender_minus_receiver: &[f32],
        distances: &[f32],
        cache_key: Option<u64>,
        num_radial: usize,
        name: &str,
    ) -> Result<(Buffer, Buffer, Buffer), String> {
        let edge_count = edge_index.len();
        let expected_derivative_len = edge_count
            .checked_mul(num_radial)
            .ok_or_else(|| format!("{name}.smooth_derivative length overflows usize"))?;
        if smooth_derivative_by_edge_radial.len() != expected_derivative_len {
            return Err(format!(
                "{name}.smooth_derivative expected length {expected_derivative_len}, got {}",
                smooth_derivative_by_edge_radial.len()
            ));
        }
        let expected_vector_len = edge_count
            .checked_mul(3)
            .ok_or_else(|| format!("{name}.vector length overflows usize"))?;
        if vectors_sender_minus_receiver.len() != expected_vector_len {
            return Err(format!(
                "{name}.vectors expected length {expected_vector_len}, got {}",
                vectors_sender_minus_receiver.len()
            ));
        }
        if distances.len() != edge_count {
            return Err(format!(
                "{name}.distances expected length {edge_count}, got {}",
                distances.len()
            ));
        }
        let mut static_cache = self
            .static_cache
            .lock()
            .map_err(|_| "MACE-Polar Metal static cache mutex was poisoned".to_owned())?;
        if let Some(cache_key) = cache_key {
            if let Some(entry) = static_cache
                .realspace_descriptor_vjp_geometry_buffers
                .iter()
                .find(|entry| {
                    entry.cache_key == Some(cache_key)
                        && entry.num_radial == num_radial
                        && entry.edge_index.len() == edge_index.len()
                        && entry.smooth_derivative_by_edge_radial.len()
                            == smooth_derivative_by_edge_radial.len()
                        && entry.vectors_sender_minus_receiver.len()
                            == vectors_sender_minus_receiver.len()
                        && entry.distances.len() == distances.len()
                })
            {
                return Ok((
                    entry.smooth_derivative_buffer.clone(),
                    entry.vectors_buffer.clone(),
                    entry.distances_buffer.clone(),
                ));
            }
        }
        if let Some(entry) = static_cache
            .realspace_descriptor_vjp_geometry_buffers
            .iter()
            .find(|entry| {
                entry.num_radial == num_radial
                    && entry.edge_index.as_slice() == edge_index
                    && entry.smooth_derivative_by_edge_radial.as_slice()
                        == smooth_derivative_by_edge_radial
                    && entry.vectors_sender_minus_receiver.as_slice()
                        == vectors_sender_minus_receiver
                    && entry.distances.as_slice() == distances
            })
        {
            return Ok((
                entry.smooth_derivative_buffer.clone(),
                entry.vectors_buffer.clone(),
                entry.distances_buffer.clone(),
            ));
        }
        let smooth_derivative_buffer = buffer_with_slice_on_device(
            &self.device,
            smooth_derivative_by_edge_radial,
            MTLResourceOptions::StorageModeShared,
        );
        let vectors_buffer = buffer_with_slice_on_device(
            &self.device,
            vectors_sender_minus_receiver,
            MTLResourceOptions::StorageModeShared,
        );
        let distances_buffer = buffer_with_slice_on_device(
            &self.device,
            distances,
            MTLResourceOptions::StorageModeShared,
        );
        static_cache.realspace_descriptor_vjp_geometry_buffers.push(
            RealspaceDescriptorVjpGeometryBufferCacheEntry {
                cache_key,
                num_radial,
                edge_index: edge_index.to_vec(),
                smooth_derivative_by_edge_radial: smooth_derivative_by_edge_radial.to_vec(),
                vectors_sender_minus_receiver: vectors_sender_minus_receiver.to_vec(),
                distances: distances.to_vec(),
                smooth_derivative_buffer: smooth_derivative_buffer.clone(),
                vectors_buffer: vectors_buffer.clone(),
                distances_buffer: distances_buffer.clone(),
            },
        );
        static_cache.trim_geometry_buffer_caches();
        Ok((smooth_derivative_buffer, vectors_buffer, distances_buffer))
    }

