pub(super) fn flat_rows_f32_from_metal_buffer(
    rows: &MacePolarFlatRowsF32Metal,
) -> MacePolarFlatRowsF32 {
    let mut values = vec![0.0_f32; rows.len];
    let ptr = rows.buffer.contents().cast::<f32>();
    copy_ptr_to_slice(ptr, &mut values);
    MacePolarFlatRowsF32 {
        values,
        row_count: rows.row_count,
        width: rows.width,
    }
}

pub(super) fn flat_rows_from_metal_buffer(rows: &MacePolarFlatRowsF32Metal) -> MacePolarRows {
    flat_rows_f32_from_metal_buffer(rows).to_rows()
}

