    #[test]
    fn density_gate_block_linear_rows_match_staged_path() -> Result<(), MacePolarError> {
        let _guard = metal_backend_test_lock()
            .lock()
            .expect("Metal backend test mutex should not be poisoned");
        let backend = match backend() {
            Ok(backend) => backend,
            Err(_) => return Ok(()),
        };

        let gate_plan = super::super::MacePolarParsedGatePlan {
            scalar_constants: vec![1.1],
            gate_constants: vec![0.8],
            scalar_partitions: vec![super::super::MacePolarGateActivationPartition {
                start: 0,
                end: 2,
                dim: 2,
            }],
            gate_partitions: vec![super::super::MacePolarGateActivationPartition {
                start: 2,
                end: 4,
                dim: 2,
            }],
            gate_offsets: vec![0],
            mul_output_mask: vec![1.0, 0.25, -0.5, 1.75],
            mul_instructions: vec![super::super::MacePolarGateMulInstruction {
                gate_partition_index: 0,
                gated_start: 4,
                final_output_start: 2,
                mask_start: 0,
                irrep_dim: 2,
                mul: 2,
                factor: 0.55,
            }],
            scalar_output_start: 0,
            scalar_output_end: 2,
        };
        let gate_table = GateStaticTable::from_plan(&gate_plan, "test.density_gate.gate")
            .map_err(|err| invalid("test.density_gate.gate_table", err))?;

        let block_weight = patterned_values(6 * 4, -0.033, 0.04);
        let block_bias = vec![0.0, 0.12, -0.08, 0.2];
        let block_mask = vec![1.0, 0.5, -1.5, 2.0];
        let block_instructions = vec![super::super::MacePolarBlockLinearInstruction {
            input_start: 0,
            output_start: 0,
            input_mul: 6,
            output_mul: 4,
            irrep_dim: 1,
            weight_offset: 0,
        }];
        let block_spec = super::super::MacePolarBlockLinearSpec {
            weight: &block_weight,
            bias: &block_bias,
            output_mask: &block_mask,
            instructions: &block_instructions,
            instruction_path_weights: Some(&[0.75]),
            input_dim: 6,
            output_dim: 4,
            name: "test.density_gate.block",
        };
        let block_table = BlockLinearStaticTable::from_spec(&block_spec)
            .map_err(|err| invalid("test.density_gate.block_table", err))?;

        let linear_1_rows = vec![
            vec![0.3, -0.8, 1.2, -1.5, 0.6, -0.4, 0.9, -1.1],
            vec![-0.7, 0.5, -1.1, 0.9, -0.2, 1.4, -0.6, 0.8],
        ];
        let linear_res_rows = vec![
            vec![0.05, 0.2, -0.3, 0.4, -0.6, 0.7, -0.25, 0.55],
            vec![0.9, -0.1, 0.25, -0.45, 0.35, -0.75, 0.65, -0.15],
        ];
        let denominator_rows = vec![vec![1.7], vec![0.8]];
        let expected_density = linear_1_rows
            .iter()
            .zip(&denominator_rows)
            .map(|(row, denom)| {
                let denom = denom[0] as f32;
                row.iter()
                    .map(|value| f64::from((*value as f32) / denom))
                    .collect::<Vec<_>>()
            })
            .collect::<Vec<_>>();
        let expected_residual = expected_density
            .iter()
            .zip(&linear_res_rows)
            .map(|(density, residual)| {
                density
                    .iter()
                    .zip(residual)
                    .map(|(density, residual)| f64::from((*density as f32) + (*residual as f32)))
                    .collect::<Vec<_>>()
            })
            .collect::<Vec<_>>();
        let (expected_gate, expected_linear) = gate_block_linear_rows_f32_with_static_tables(
            &expected_residual,
            &gate_table,
            &block_table,
            "test.density_gate.expected",
        )?;

        let (actual_density, actual_residual, actual_gate, actual_linear) =
            density_gate_block_linear_rows_f32_with_static_tables(
                &linear_1_rows,
                &linear_res_rows,
                &denominator_rows,
                &gate_table,
                &block_table,
                "test.density_gate.combined",
            )?;
        assert_rows_close(
            &actual_density,
            &expected_density,
            2.0e-6,
            "combined density normalize",
        );
        assert_rows_close(
            &actual_residual,
            &expected_residual,
            2.0e-6,
            "combined residual add",
        );
        assert_rows_close(
            &actual_gate,
            &expected_gate,
            2.0e-6,
            "combined density gate",
        );
        assert_rows_close(
            &actual_linear,
            &expected_linear,
            2.0e-6,
            "combined density gate block-linear",
        );

        let before_repeat = backend
            .scratch
            .lock()
            .expect("scratch mutex should not be poisoned")
            .buffer_allocation_count();
        let (repeat_density, repeat_residual, repeat_gate, repeat_linear) =
            density_gate_block_linear_rows_f32_with_static_tables(
                &linear_1_rows,
                &linear_res_rows,
                &denominator_rows,
                &gate_table,
                &block_table,
                "test.density_gate.combined",
            )?;
        let after_repeat = backend
            .scratch
            .lock()
            .expect("scratch mutex should not be poisoned")
            .buffer_allocation_count();
        assert_eq!(before_repeat, after_repeat);
        assert_rows_close(
            &repeat_density,
            &expected_density,
            2.0e-6,
            "repeated density normalize",
        );
        assert_rows_close(
            &repeat_residual,
            &expected_residual,
            2.0e-6,
            "repeated residual add",
        );
        assert_rows_close(
            &repeat_gate,
            &expected_gate,
            2.0e-6,
            "repeated density gate",
        );
        assert_rows_close(
            &repeat_linear,
            &expected_linear,
            2.0e-6,
            "repeated density gate block-linear",
        );
        Ok(())
    }

