        let ln4_bias = patterned_values(hidden, 0.013, -0.08);
        let ln7_weight = patterned_values(hidden, 0.023, 0.9);
        let ln7_bias = patterned_values(hidden, 0.019, 0.04);
        let eps = 1.0e-5;

        let linear0 = DenseLinearStaticTable::from_slices(&w0, &b0, 3, hidden, "test.conv.0")
            .map_err(|err| invalid("test.fused_edge_mlp.linear0", err))?;
